window.QKEY = "az900.v1";
window.QDATA = window.QDATA || {};

window.QDATA[1] = [
  {t:"Concepts cloud",q:"Qu'est-ce que le cloud computing selon Microsoft ?",o:["Le stockage de fichiers sur internet","La livraison de services informatiques (serveurs, stockage, bases de données, réseau, logiciels, analytique, IA) via internet avec facturation à l'usage","Un type de réseau local avancé","Un système d'exploitation distribué"],a:1,e:"Le cloud computing est la fourniture de services informatiques via internet ('le cloud'), permettant d'innover plus vite, de bénéficier d'économies d'échelle et d'une flexibilité maximale sans gérer d'infrastructure physique."},
  {t:"Concepts cloud",q:"Quel est l'avantage principal de la haute disponibilité dans le cloud ?",o:["La réduction des coûts uniquement","La garantie que les applications restent opérationnelles malgré les pannes, grâce aux SLA qui définissent les temps d'arrêt maxima","L'accès depuis n'importe quel appareil","La vitesse de déploiement"],a:1,e:"La haute disponibilité garantit que les ressources cloud restent disponibles via des SLA (Service Level Agreements) qui définissent le pourcentage de disponibilité (ex : 99,9% = max 8,7h d'arrêt/an). Azure offre des SLA jusqu'à 99,99%."},
  {t:"Concepts cloud",q:"Qu'est-ce que la scalabilité dans le contexte du cloud Azure ?",o:["La capacité à chiffrer les données","La capacité à augmenter ou réduire les ressources (CPU, mémoire, instances) selon la demande","La capacité à sauvegarder les données","La vitesse du réseau"],a:1,e:"La scalabilité permet d'ajuster les ressources : scale up/down (changer la puissance d'une ressource) ou scale out/in (ajouter/supprimer des instances). Azure ajuste les ressources automatiquement selon la demande."},
  {t:"Concepts cloud",q:"Qu'est-ce que l'élasticité dans le cloud ?",o:["La scalabilité manuelle uniquement","La capacité à s'adapter automatiquement et rapidement aux changements de charge de travail, en ajoutant ou retirant des ressources de façon dynamique","Un type de stockage extensible","La résistance aux cyberattaques"],a:1,e:"L'élasticité est la scalabilité automatique et dynamique : le cloud ajoute des ressources quand la charge augmente et les supprime quand elle diminue, sans intervention manuelle. Ex : Azure Autoscale pour les VMs et App Service."},
  {t:"Concepts cloud",q:"Qu'est-ce que la fiabilité (reliability) dans le cloud Azure ?",o:["La vitesse de connexion réseau","La capacité du cloud à fonctionner correctement et à récupérer après des pannes, grâce à une infrastructure distribuée mondialement","La qualité du support technique","La sécurité des données"],a:1,e:"La fiabilité Azure s'appuie sur son infrastructure mondiale décentralisée : si une région subit une panne, les autres régions continuent à fonctionner. Azure propose des paires de régions et des zones de disponibilité pour maximiser la résilience."},
  {t:"Concepts cloud",q:"Que signifie 'prévisibilité' des coûts dans le cloud ?",o:["Des coûts fixes identiques chaque mois","La capacité à anticiper les coûts grâce aux calculateurs de prix, aux budgets et aux alertes, et à comprendre l'impact des actions sur les dépenses","Des coûts toujours inférieurs à l'on-premises","L'absence de coûts cachés"],a:1,e:"La prévisibilité des coûts permet de planifier les dépenses cloud via Azure Pricing Calculator, Cost Management, budgets et alertes. Microsoft fournit aussi des benchmarks et des recommandations d'optimisation."},
  {t:"Concepts cloud",q:"Qu'est-ce que la sécurité dans le cloud Azure ?",o:["La responsabilité exclusive de Microsoft","Un ensemble d'outils et de pratiques partagés entre Microsoft (infrastructure) et le client (configuration et données) selon le modèle de responsabilité partagée","Une protection automatique sans configuration","Un service optionnel payant"],a:1,e:"La sécurité Azure suit le modèle de responsabilité partagée : Microsoft sécurise l'infrastructure physique, réseau et hyperviseur. Le client est responsable de la configuration des services, des données, des identités et des accès."},
  {t:"Concepts cloud",q:"Qu'est-ce que la gouvernance dans le cloud ?",o:["La gestion administrative de l'entreprise","Les processus et outils permettant d'établir et d'appliquer des règles, des normes et des politiques pour les ressources cloud","Un service de gestion des identités","La surveillance du réseau"],a:1,e:"La gouvernance cloud comprend les politiques (Azure Policy), les blueprints, les tags pour l'organisation, et RBAC pour les accès. Elle garantit la conformité, la sécurité et le contrôle des coûts à l'échelle."},
  {t:"Concepts cloud",q:"Qu'est-ce que la gérabilité (manageability) du cloud ?",o:["La facilité à comprendre les factures","La capacité à gérer les ressources cloud via des outils comme le portail Azure, CLI, PowerShell, ARM templates ou des APIs REST","La gestion des droits d'auteur","Le contrôle des performances réseau"],a:1,e:"La gérabilité du cloud signifie que vous pouvez déployer, configurer, monitorer et ajuster les ressources via de multiples interfaces : portail web, CLI, PowerShell, Infrastructure as Code (ARM/Bicep/Terraform) et APIs REST."},
  {t:"Modèles cloud",q:"Qu'est-ce qu'un cloud public ?",o:["Un cloud accessible à tous gratuitement","Un cloud dont l'infrastructure est gérée par un fournisseur tiers (Microsoft, Google, AWS) et partagée entre plusieurs clients, accessible via internet","Un cloud uniquement pour les agences gouvernementales","Un cloud sans mesures de sécurité"],a:1,e:"Le cloud public est opéré par un fournisseur tiers. L'infrastructure est partagée entre clients (multitenancy), les coûts sont mutualisés (OPEX), et les ressources sont accessibles via internet. Azure est un exemple de cloud public."},
  {t:"Modèles cloud",q:"Qu'est-ce qu'un cloud privé ?",o:["Un cloud uniquement pour les PME","Un environnement cloud dédié à une seule organisation, hébergé dans ses propres datacenters ou chez un fournisseur dédié, offrant plus de contrôle et de personnalisation","Un cloud sans connexion internet","Un cloud géré par un seul employé"],a:1,e:"Le cloud privé est exclusivement utilisé par une organisation. Il offre plus de contrôle, de personnalisation et de sécurité, mais nécessite plus d'investissements (CAPEX) et d'expertise pour être géré. Il peut être on-premises ou hébergé."},
  {t:"Modèles cloud",q:"Qu'est-ce qu'un cloud hybride ?",o:["Un cloud combinant deux fournisseurs publics","Une combinaison de cloud public et privé (et/ou on-premises) connectés, permettant aux données et applications de circuler entre les deux environnements","Un cloud pour les grandes et petites entreprises","Un cloud avec deux niveaux de sécurité"],a:1,e:"Le cloud hybride combine cloud public et privé. Il offre la flexibilité de garder les applications sensibles on-premises/privé tout en profitant de la scalabilité du cloud public. Azure Arc et Azure Stack permettent d'implémenter un cloud hybride."},
  {t:"Modèles cloud",q:"Qu'est-ce qu'un multi-cloud ?",o:["Plusieurs niveaux de stockage sur un même cloud","L'utilisation de services de plusieurs fournisseurs cloud publics (Azure + AWS + GCP) dans la même organisation","Un cloud avec plusieurs régions","Un cloud pour plusieurs départements"],a:1,e:"Le multi-cloud consiste à utiliser des services de plusieurs fournisseurs cloud (Azure, AWS, GCP) pour éviter la dépendance à un seul fournisseur, optimiser les coûts et utiliser les meilleures fonctionnalités de chacun. Azure Arc aide à gérer ce scénario."},
  {t:"Modèles service",q:"Qu'est-ce que l'IaaS (Infrastructure as a Service) ?",o:["Un service de logiciels en ligne","Un modèle où le fournisseur cloud gère l'infrastructure physique (serveurs, réseau, stockage) et le client gère l'OS, le middleware et les applications","Un service entièrement géré par le fournisseur","Un service de plateforme de développement"],a:1,e:"IaaS est le niveau le plus flexible : Azure gère hardware, réseau et virtualisation. Le client gère OS, middleware, runtime et applications. Exemples : Azure VMs, Azure Virtual Networks. Idéal pour les migrations lift-and-shift."},
  {t:"Modèles service",q:"Qu'est-ce que le PaaS (Platform as a Service) ?",o:["Un service où le client gère tout","Un modèle où le fournisseur gère l'infrastructure ET la plateforme (OS, runtime, middleware), le client se concentrant sur le code et les données","Un service cloud sans serveur","Un service identique au IaaS"],a:1,e:"PaaS permet aux développeurs de se concentrer sur le code sans gérer l'infrastructure sous-jacente. Azure gère OS, patches, scaling de la plateforme. Exemples : Azure App Service, Azure SQL Database, Azure Functions. Idéal pour le développement d'applications."},
  {t:"Modèles service",q:"Qu'est-ce que le SaaS (Software as a Service) ?",o:["Un logiciel installé localement","Un modèle où le fournisseur gère tout (infrastructure, plateforme et application), le client accédant via un navigateur ou API","Un service uniquement pour les développeurs","Un service de stockage en ligne"],a:1,e:"SaaS est le modèle le plus complet : le fournisseur gère tout, de l'infrastructure à l'application. Le client utilise le logiciel sans s'occuper de la maintenance. Exemples Microsoft : Microsoft 365, Dynamics 365, Teams."},
  {t:"Modèles service",q:"Quelle est la responsabilité du client dans un modèle IaaS vs PaaS ?",o:["Identique dans les deux cas","IaaS : client gère OS, middleware, runtime, applications et données; PaaS : client gère uniquement les applications, données et accès","IaaS : client gère uniquement les données","PaaS : client gère tout sauf le hardware"],a:1,e:"En IaaS, le client a plus de responsabilités (OS, patches, middleware, runtime). En PaaS, le fournisseur gère davantage, le client se concentrant sur les applications et données. Plus on monte vers SaaS, plus la responsabilité du fournisseur est grande."},
  {t:"Modèles service",q:"Dans quel scénario recommanderiez-vous Azure App Service (PaaS) plutôt qu'une VM Azure (IaaS) ?",o:["Pour migrer une application avec un OS personnalisé","Pour déployer une application web dont l'équipe veut se concentrer sur le code sans gérer l'OS, les patches et le scaling de l'infrastructure","Pour exécuter des applications nécessitant un accès root","Pour des workloads avec des exigences d'OS spécifiques"],a:1,e:"Azure App Service (PaaS) est recommandé quand l'équipe veut se concentrer sur le code. Azure gère OS, patches, scaling, SSL, domaines custom. Les VMs (IaaS) sont préférées quand un contrôle total sur l'OS et la configuration système est nécessaire."},
  {t:"CapEx vs OpEx",q:"Qu'est-ce que le CapEx (Capital Expenditure) dans le contexte IT ?",o:["Les dépenses variables mensuelles","Les dépenses en capital pour l'achat de matériel et d'infrastructure physique (serveurs, bâtiments) amorties sur plusieurs années","Les frais de licence logicielle","Les coûts de maintenance uniquement"],a:1,e:"Le CapEx représente les investissements initiaux en infrastructure physique (serveurs, stockage, réseau, datacenters). Ces coûts sont importants upfront et amortis sur plusieurs années. Le cloud réduit le CapEx en le convertissant en OpEx."},
  {t:"CapEx vs OpEx",q:"Qu'est-ce que l'OpEx (Operational Expenditure) et comment le cloud s'y inscrit-il ?",o:["Les dépenses exceptionnelles annuelles","Les dépenses opérationnelles récurrentes (abonnements, services); le cloud est un modèle OpEx — on paie pour ce qu'on consomme, sans investissement initial","Les coûts de formation du personnel","Les dépenses fixes de maintenance"],a:1,e:"L'OpEx regroupe les dépenses de fonctionnement récurrentes. Le cloud Azure fonctionne sur un modèle OpEx : paiement à l'utilisation sans CapEx initial. Cela améliore la trésorerie, offre de la flexibilité et aligne les coûts sur l'utilisation réelle."},
  {t:"CapEx vs OpEx",q:"Quel avantage offre le modèle de consommation cloud (OpEx) pour une startup ?",o:["Des coûts toujours inférieurs à l'on-premises","La capacité de démarrer sans investissement initial (pas de CapEx), de payer uniquement les ressources utilisées et d'ajuster les dépenses selon la croissance","Un accès gratuit aux services cloud","Des garanties de disponibilité illimitées"],a:1,e:"Pour une startup, le modèle OpEx cloud permet de lancer sans investissements initiaux en serveurs, de payer proportionnellement à l'utilisation et d'ajuster (scale up ou down) les ressources en fonction de la croissance réelle."},
  {t:"Responsabilité partagée",q:"Dans le modèle de responsabilité partagée Azure, qui est responsable de la sécurité physique des datacenters ?",o:["Le client","Microsoft Azure","Les deux partagent la responsabilité","Ni l'un ni l'autre"],a:1,e:"Microsoft est toujours responsable de la sécurité physique de ses datacenters (contrôles d'accès, caméras, personnel de sécurité). Le client est responsable de ses données et de la configuration de ses ressources dans Azure."},
  {t:"Responsabilité partagée",q:"Dans le cloud public Azure, qui est responsable de la configuration du pare-feu applicatif ?",o:["Microsoft Azure exclusivement","Le client — il doit configurer Azure Firewall, NSG et autres contrôles de sécurité réseau pour ses ressources","Partagé automatiquement","Un prestataire tiers obligatoire"],a:1,e:"La configuration de la sécurité réseau (NSG, Azure Firewall, WAF) est la responsabilité du client. Microsoft fournit les outils, mais c'est au client de les configurer correctement pour protéger ses ressources."},
  {t:"Responsabilité partagée",q:"Que signifie 'responsabilité partagée' pour les données dans un modèle SaaS comme Microsoft 365 ?",o:["Microsoft gère les données et les accès","Le client reste responsable de ses données (gouvernance, classification), des comptes utilisateurs et de la configuration des accès; Microsoft gère l'infrastructure et la disponibilité de l'application","Microsoft et le client partagent l'accès aux données","Le client n'a aucune responsabilité"],a:1,e:"Même en SaaS, le client conserve la responsabilité de ses données : qui y accède, comment elles sont classifiées, leur exportation et leur suppression. Microsoft gère la disponibilité et la sécurité de l'infrastructure de l'application."},
  {t:"Modèles cloud",q:"Quel modèle cloud offre le plus de contrôle sur l'infrastructure ?",o:["Cloud public","Cloud hybride","Cloud privé","Multi-cloud"],a:2,e:"Le cloud privé offre le plus de contrôle : l'organisation possède et gère son infrastructure dédiée. Cela permet une personnalisation maximale, des politiques de sécurité strictes et la conformité avec des réglementations spécifiques, mais nécessite plus d'investissements."},
  {t:"Avantages cloud",q:"Comment le cloud Azure facilite-t-il la reprise après sinistre (disaster recovery) ?",o:["En dupliquant les données localement","Via Azure Site Recovery et des zones/régions géographiquement séparées pour répliquer les données et applications, permettant une reprise rapide en cas de catastrophe","En fournissant des sauvegardes uniquement","En garantissant l'absence de pannes"],a:1,e:"Azure Site Recovery réplique les VMs et applications vers une région secondaire. En cas de sinistre, le basculement vers la région de secours peut être automatique ou manuel. Les paires de régions Azure garantissent la séparation géographique pour la DR."},
  {t:"Avantages cloud",q:"Qu'est-ce que 'l'agilité' dans le contexte du cloud Azure ?",o:["La vitesse de chargement des pages web","La capacité à déployer et configurer rapidement des ressources (en quelques minutes vs semaines pour du matériel physique), permettant d'innover et de répondre rapidement aux besoins métier","La sécurité automatique des données","La réduction automatique des coûts"],a:1,e:"L'agilité cloud permet de déployer de nouvelles ressources en quelques minutes depuis le portail Azure, CLI ou code (IaC). Cela contraste avec les semaines/mois nécessaires pour acquérir et configurer du matériel physique."},
  {t:"Avantages cloud",q:"Comment le cloud Azure contribue-t-il à la réduction des coûts de maintenance ?",o:["En supprimant tous les coûts IT","En externalisant la maintenance de l'infrastructure physique (hardware, datacenters) à Microsoft, permettant aux équipes IT de se concentrer sur la valeur ajoutée","En remplaçant tous les employés IT","En automatisant 100% des opérations"],a:1,e:"Azure gère la maintenance de l'infrastructure physique : remplacement des serveurs en panne, mises à jour du firmware, maintenance des datacenters. L'équipe IT cliente peut se concentrer sur les projets à valeur ajoutée plutôt que sur la maintenance hardware."},
  {t:"Avantages cloud",q:"Qu'est-ce que la portée mondiale (global reach) d'Azure ?",o:["La présence d'Azure dans une seule grande ville","La disponibilité des services Azure dans plus de 60 régions géographiques réparties sur tous les continents, permettant de servir les utilisateurs au plus près","L'accès à Azure depuis n'importe quel appareil","La gestion centralisée de toutes les ressources"],a:1,e:"Azure est disponible dans plus de 60 régions mondiales sur tous les continents. Cela permet de déployer des applications près des utilisateurs finaux pour réduire la latence, respecter les exigences de résidence des données et assurer la reprise après sinistre."},
  {t:"Avantages cloud",q:"Qu'est-ce que les économies d'échelle dans le cloud Azure ?",o:["Des réductions réservées aux grandes entreprises","La capacité de Microsoft à acheter matériel et énergie en grandes quantités, permettant de proposer des prix inférieurs à ce qu'une entreprise obtiendrait seule","Des réductions uniquement sur les licences","Des économies réalisées par la mutualisation des datacenters"],a:1,e:"Microsoft achète des millions de serveurs et consomme d'énormes quantités d'énergie, obtenant des tarifs préférentiels répercutés sur les clients Azure. Une entreprise seule ne pourrait obtenir ces conditions. C'est la base du modèle économique cloud."},
  {t:"Avantages cloud",q:"Quel est l'avantage de l'accès à la dernière technologie avec le cloud Azure ?",o:["L'accès aux anciens matériels réformés","L'accès immédiat aux dernières innovations (IA, machine learning, quantum computing) sans nécessiter d'investir dans du matériel spécialisé","L'accès aux technologies expérimentales non testées","L'accès aux technologies uniquement disponibles en Amérique"],a:1,e:"Azure intègre continuellement les dernières innovations (GPU Nvidia A100/H100, Azure Quantum, OpenAI, nouvelles régions). Les clients bénéficient immédiatement de ces innovations sans acheter de matériel spécialisé coûteux."}
];

window.QDATA[2] = [
  {t:"Architecture Azure",q:"Qu'est-ce qu'une région Azure ?",o:["Un pays où Azure est disponible","Une zone géographique contenant un ou plusieurs datacenters connectés par un réseau à faible latence, gérée comme une unité avec des critères de résidence des données","Un continent couvert par Azure","Un datacenter unique de Microsoft"],a:1,e:"Une région Azure est un ensemble de datacenters déployés dans un périmètre géographique défini et connectés via un réseau dédié. Les régions permettent la résidence des données et la conformité réglementaire. Exemples : France Centre, Europe Nord, East US."},
  {t:"Architecture Azure",q:"Qu'est-ce qu'une paire de régions Azure ?",o:["Deux régions quelconques dans le monde","Deux régions Azure dans la même zone géographique, séparées d'au moins 300 miles (480 km), qui se sauvegardent mutuellement pour la réplication et la reprise après sinistre","Deux datacenters dans la même ville","Deux abonnements Azure liés"],a:1,e:"Les paires de régions Azure (ex : France Centre/France Sud, East US/West US) garantissent que si une région tombe, l'autre prend le relais. Les mises à jour sont déployées séquentiellement. Minimum 300 miles pour réduire l'impact des catastrophes régionales."},
  {t:"Architecture Azure",q:"Qu'est-ce qu'une zone de disponibilité (Availability Zone) Azure ?",o:["Une région géographique Azure","Des datacenters physiquement séparés dans une même région Azure, chacun avec son alimentation, refroidissement et réseau indépendants, offrant une isolation des pannes","Un réseau virtuel Azure isolé","Un groupe de ressources Azure"],a:1,e:"Les zones de disponibilité sont des datacenters physiquement séparés au sein d'une région. Si une zone tombe en panne, les autres continuent à fonctionner. Idéal pour les applications nécessitant une haute disponibilité (SLA 99,99%). Actuellement disponibles dans ~30 régions."},
  {t:"Architecture Azure",q:"Qu'est-ce qu'un ensemble de disponibilité (Availability Set) Azure ?",o:["Un groupe de régions Azure","Un regroupement logique de VMs dans un datacenter Azure, distribué entre domaines de mise à jour et domaines de pannes pour réduire l'impact des pannes matérielles et des maintenances","Un type de stockage redondant","Un service de réplication de données"],a:1,e:"Un Availability Set répartit les VMs entre domaines de pannes (racks physiques différents) et domaines de mise à jour (pas de redémarrage simultané lors des maintenances). SLA 99,95% pour les VMs dans un Availability Set. Différent des Availability Zones (bâtiments séparés)."},
  {t:"Architecture Azure",q:"Qu'est-ce qu'un groupe de ressources Azure (Resource Group) ?",o:["Un abonnement Azure","Un conteneur logique qui regroupe les ressources Azure liées pour en faciliter la gestion, le déploiement et la facturation","Un réseau virtuel Azure","Un type de compte de stockage"],a:1,e:"Un Resource Group est un conteneur pour les ressources Azure (VMs, bases de données, réseaux). Toutes les ressources d'un RG partagent le même cycle de vie et peuvent être gérées ensemble (déploiement, suppression, RBAC). Une ressource appartient à un seul RG."},
  {t:"Architecture Azure",q:"Qu'est-ce qu'un abonnement Azure (Subscription) ?",o:["Un contrat de support technique","Une unité logique de services Azure liée à un compte Azure, qui définit les limites de facturation et de contrôle d'accès, et regroupe les ressources pour la gestion","Un type de compte utilisateur","Un service cloud Azure"],a:1,e:"Un abonnement Azure est la limite de facturation principale : toutes les ressources d'un abonnement sont facturées ensemble. Il définit aussi les limites de contrôle d'accès. Une organisation peut avoir plusieurs abonnements pour séparer environnements, départements ou projets."},
  {t:"Architecture Azure",q:"Qu'est-ce qu'un groupe d'administration Azure (Management Group) ?",o:["Un groupe de comptes utilisateurs","Un niveau hiérarchique au-dessus des abonnements qui permet d'appliquer des politiques et des contrôles d'accès à plusieurs abonnements simultanément","Un type de groupe de ressources","Un service de monitoring Azure"],a:1,e:"Les Management Groups permettent d'organiser plusieurs abonnements Azure dans une hiérarchie. Les politiques Azure Policy et RBAC appliqués à un Management Group s'héritent à tous les abonnements enfants. Jusqu'à 6 niveaux de profondeur. Utile pour les grandes organisations."},
  {t:"Architecture Azure",q:"Quelle est la hiérarchie correcte des niveaux d'organisation dans Azure, du plus large au plus précis ?",o:["Abonnement > Groupe d'administration > Groupe de ressources > Ressource","Groupe d'administration > Abonnement > Groupe de ressources > Ressource","Groupe de ressources > Abonnement > Groupe d'administration > Ressource","Ressource > Groupe de ressources > Abonnement > Groupe d'administration"],a:1,e:"La hiérarchie Azure est : Tenant (Azure AD) > Groupe d'administration > Abonnement > Groupe de ressources > Ressource. Cette hiérarchie permet d'appliquer des politiques, des droits RBAC et des limites de coût à chaque niveau, hérités vers le bas."},
  {t:"Azure Compute",q:"Qu'est-ce qu'une machine virtuelle (VM) Azure ?",o:["Un conteneur Docker hébergé dans Azure","Un service IaaS qui fournit des ressources informatiques à la demande (CPU, RAM, stockage) sans avoir à gérer l'infrastructure physique sous-jacente","Un service d'hébergement web uniquement","Un service de bases de données"],a:1,e:"Les Azure Virtual Machines sont des émulations logicielles d'ordinateurs physiques (IaaS). Vous choisissez la taille (CPU/RAM), l'image OS (Windows/Linux), la région. Azure gère l'hyperviseur et le hardware. Vous gérez l'OS, les applications et les données."},
  {t:"Azure Compute",q:"Qu'est-ce que Azure Virtual Machine Scale Sets ?",o:["Un ensemble de VMs identiques créées manuellement","Un service Azure qui permet de créer et gérer automatiquement un groupe de VMs identiques avec load balancing et autoscaling selon la charge","Un service de sauvegarde des VMs","Un type de réseau virtuel"],a:1,e:"Azure VM Scale Sets (VMSS) permet de déployer et gérer un groupe de VMs identiques. VMSS ajuste automatiquement le nombre d'instances (scale out/in) selon les règles définies (CPU, mémoire, métriques custom). Utilisé pour les applications nécessitant une haute disponibilité et scalabilité."},
  {t:"Azure Compute",q:"Qu'est-ce qu'Azure App Service ?",o:["Un service de messagerie","Un service PaaS entièrement géré pour héberger des applications web, des API REST, des backends mobiles, sans gérer l'infrastructure sous-jacente","Un service IaaS de VMs","Un service de bases de données"],a:1,e:"Azure App Service est une plateforme PaaS pour héberger des applications web (Node.js, Python, .NET, Java, PHP). Azure gère l'OS, les patches, la scalabilité et le SSL. Vous vous concentrez sur le code. Supporte les déploiements CI/CD depuis GitHub, Azure DevOps."},
  {t:"Azure Compute",q:"Qu'est-ce qu'Azure Container Instances (ACI) ?",o:["Un service de gestion Kubernetes","Le moyen le plus rapide d'exécuter un conteneur dans Azure sans gérer de VMs ou d'orchestrateur — démarrage en secondes, facturation à la seconde","Un service de registre de conteneurs","Un service de déploiement d'applications"],a:1,e:"Azure Container Instances est le service le plus simple pour exécuter des conteneurs dans Azure : aucune VM à gérer, pas de cluster Kubernetes. Idéal pour les tâches courtes, les tests et les workflows simples. Facturation à la seconde d'utilisation CPU/mémoire."},
  {t:"Azure Compute",q:"Qu'est-ce qu'Azure Kubernetes Service (AKS) ?",o:["Un service de déploiement de VMs","Un service Kubernetes managé qui simplifie le déploiement, la gestion et les opérations des clusters Kubernetes, Azure gérant le plan de contrôle","Un service de conteneurs sans orchestration","Un service uniquement pour les applications .NET"],a:1,e:"AKS est la solution Kubernetes managée d'Azure. Azure gère gratuitement le control plane (API server, etcd). Vous gérez les worker nodes. AKS s'intègre avec Azure Monitor, Azure AD, Azure Container Registry, et supporte les mises à jour automatiques."},
  {t:"Azure Compute",q:"Qu'est-ce qu'Azure Functions ?",o:["Un service de gestion de VMs","Un service serverless qui permet d'exécuter du code (fonctions) en réponse à des événements (HTTP, timer, message, fichier), sans gérer de serveurs","Un service de base de données serverless","Un service d'API Management"],a:1,e:"Azure Functions est un service FaaS (Function as a Service) : vous écrivez du code (Python, C#, JavaScript, etc.) qui s'exécute automatiquement en réponse à des déclencheurs. Azure gère l'infrastructure. Facturation uniquement lors de l'exécution (modèle consommation)."},
  {t:"Azure Compute",q:"Quelle est la différence principale entre Azure Container Instances (ACI) et Azure Kubernetes Service (AKS) ?",o:["ACI est plus sécurisé qu'AKS","ACI est simple pour des conteneurs isolés sans orchestration; AKS est adapté aux applications multi-conteneurs complexes nécessitant orchestration, scalabilité avancée et haute disponibilité","AKS est moins cher qu'ACI dans tous les cas","ACI supporte plus de langages qu'AKS"],a:1,e:"ACI est adapté aux workloads simples, isolés, de courte durée sans orchestration. AKS convient aux microservices complexes nécessitant l'orchestration Kubernetes (rolling updates, service discovery, auto-healing). AKS demande plus de configuration mais offre plus de contrôle."},
  {t:"Azure Networking",q:"Qu'est-ce qu'un Azure Virtual Network (VNet) ?",o:["L'internet public d'Azure","Une infrastructure réseau isolée dans Azure permettant aux ressources Azure de communiquer entre elles, avec internet et les réseaux on-premises de façon sécurisée","Un service de DNS Azure","Un service de load balancing"],a:1,e:"Un Azure VNet est l'équivalent cloud d'un réseau physique traditionnel. Il permet aux VMs, App Services et autres ressources de communiquer de façon privée. On définit l'espace d'adressage IP, les sous-réseaux, les routes et les règles de sécurité réseau."},
  {t:"Azure Networking",q:"Qu'est-ce qu'un Azure VPN Gateway ?",o:["Un service de mise en cache CDN","Un service qui envoie du trafic chiffré entre un VNet Azure et un réseau on-premises via l'internet public (VPN site-to-site) ou connecte des clients distants (VPN point-to-site)","Un service de monitoring réseau","Un service de load balancing"],a:1,e:"Azure VPN Gateway crée des tunnels VPN chiffrés (IPsec/IKE) entre Azure VNet et les réseaux locaux. VPN site-to-site pour les bureaux, point-to-site pour les télétravaillseurs. Maximum 1,25 Gbps de bande passante. Plus économique mais moins fiable qu'ExpressRoute."},
  {t:"Azure Networking",q:"Qu'est-ce qu'Azure ExpressRoute ?",o:["Un VPN rapide via internet","Une connexion privée dédiée entre infrastructure on-premises et Microsoft Azure, qui ne passe pas par internet public — offrant plus de fiabilité, vitesse et sécurité","Un service de CDN Azure","Un service de DNS dédié"],a:1,e:"ExpressRoute établit une connexion privée (via des partenaires télécom) entre vos locaux et Azure. Contrairement au VPN, le trafic ne passe pas par internet. Bandes passantes de 50 Mbps à 100 Gbps, faible latence, SLA garanti. Idéal pour les workloads sensibles et le transfer massif de données."},
  {t:"Azure Networking",q:"Qu'est-ce qu'Azure DNS ?",o:["Un service antivirus pour Azure","Un service d'hébergement DNS dans Azure permettant de gérer les enregistrements DNS en utilisant l'infrastructure mondiale Azure, avec haute disponibilité et performances","Un service de messagerie","Un service de recherche d'adresses IP"],a:1,e:"Azure DNS héberge les domaines DNS et gère les enregistrements (A, AAAA, CNAME, MX, etc.) en utilisant l'infrastructure mondiale Azure. Pas de serveurs DNS à gérer. Intégration avec Azure Resource Manager, prise en charge des zones privées pour les VNets."},
  {t:"Azure Networking",q:"Qu'est-ce que le VNet Peering dans Azure ?",o:["La connexion d'un VNet à internet","La connexion de deux VNets Azure pour qu'ils communiquent directement via le backbone Microsoft, sans VPN ni internet public, avec de faibles latences","La connexion d'un VNet à un réseau on-premises","La division d'un VNet en sous-réseaux"],a:1,e:"Le VNet Peering connecte deux VNets Azure (même région ou cross-régions) via le backbone privé Microsoft. Pas de chiffrement (le trafic est déjà sur le réseau privé Microsoft), faible latence, bande passante élevée. Utile pour partager des services entre VNets ou abonnements différents."},
  {t:"Azure Storage",q:"Qu'est-ce qu'Azure Blob Storage ?",o:["Un service de bases de données","Un service de stockage objet massivement scalable pour les données non structurées (images, vidéos, documents, sauvegardes, logs) accessibles via HTTP/HTTPS","Un service de partage de fichiers","Un service de stockage de tables"],a:1,e:"Azure Blob Storage stocke des objets binaires de grande taille (Binary Large OBjects). Idéal pour : images/vidéos, sauvegardes, données pour l'analytique (Data Lake), hébergement de sites statiques. Trois types : Block Blobs (fichiers), Append Blobs (logs), Page Blobs (disques VMs)."},
  {t:"Azure Storage",q:"Qu'est-ce qu'Azure File Storage ?",o:["Un service de stockage objet","Un service de partages de fichiers SMB et NFS entièrement gérés dans le cloud, accessibles depuis Windows, Linux et macOS comme un partage réseau traditionnel","Un service de base de données de fichiers","Un service de sauvegarde uniquement"],a:1,e:"Azure Files crée des partages de fichiers accessibles via SMB (Windows/Linux) ou NFS (Linux). Il remplace ou complète les serveurs de fichiers on-premises. Utile pour les applications nécessitant un système de fichiers partagé ou pour la migration de partages de fichiers."},
  {t:"Azure Storage",q:"Quelles sont les niveaux d'accès (tiers) disponibles pour Azure Blob Storage ?",o:["Standard et Premium uniquement","Chaud (Hot), Froid (Cool), Froid en archive (Cold) et Archive — avec des compromis différents entre coûts de stockage et coûts d'accès selon la fréquence d'utilisation","Rapide, Normal et Lent","Synchrone et Asynchrone"],a:1,e:"Azure Blob offre 4 tiers : Hot (accès fréquent, stockage cher, accès bon marché), Cool (accès peu fréquent, moins cher, accès plus cher), Cold (rarement consulté, encore moins cher), Archive (accès très rare, stockage le moins cher, récupération en heures, accès très cher). On peut déplacer les blobs entre tiers."},
  {t:"Azure Storage",q:"Qu'est-ce qu'Azure Queue Storage ?",o:["Un service de priorité pour les requêtes","Un service de messagerie pour stocker et récupérer des messages (jusqu'à 64 Ko) dans une file d'attente, permettant la communication asynchrone entre composants d'application","Un service de gestion des files d'attente réseau","Un service de stockage temporaire des logs"],a:1,e:"Azure Queue Storage permet à des composants d'application de communiquer de manière asynchrone via des messages. Un composant enqueue des messages, un autre les dequeue. Capacité de millions de messages. Utilisé pour les architectures découplées et les workflows asynchrones."},
  {t:"Azure Storage",q:"Qu'est-ce qu'Azure Table Storage ?",o:["Un service de bases de données relationnelles","Un magasin de données NoSQL de type clé-valeur pour le stockage de données structurées non relationnelles à grande échelle, à faible coût","Un service de visualisation de tableaux de bord","Un service identique à Azure SQL Database"],a:1,e:"Azure Table Storage est un store NoSQL clé-valeur pour de grandes quantités de données structurées semi-structurées. Pas de schéma fixe, schemaless. Utilisé pour les données d'utilisateurs, les catalogues, les données de configuration. Alternative moins coûteuse à Azure Cosmos DB pour les cas simples."},
  {t:"Azure Storage",q:"Qu'est-ce que la redondance LRS (Locally Redundant Storage) dans Azure ?",o:["Données répliquées dans trois régions mondiales","Données répliquées de façon synchrone trois fois dans un seul datacenter (dans la même zone) — protection contre les pannes de disques/racks mais pas contre les sinistres du datacenter","Données répliquées dans deux zones d'une même région","Données répliquées entre deux régions Azure"],a:1,e:"LRS réplique les données 3 fois dans un seul datacenter. C'est le niveau de redondance le moins cher. Protège contre les pannes de disques et serveurs individuels. Ne protège pas contre les pannes au niveau du datacenter (inondation, incendie). Durabilité de 11 nines (99,999999999%)."},
  {t:"Azure Storage",q:"Qu'est-ce que la redondance GRS (Geo-Redundant Storage) dans Azure ?",o:["Données répliquées uniquement localement","Données répliquées localement (LRS) dans la région primaire ET de façon asynchrone dans une région secondaire à des centaines de km — protection contre les sinistres régionaux","Données répliquées dans toutes les régions Azure","Données répliquées uniquement entre zones"],a:1,e:"GRS combine LRS (3 copies locales) + réplication asynchrone dans une région secondaire (paire de région). Durabilité de 16 nines. Protection contre les sinistres régionaux. En lecture, la région secondaire est accessible uniquement après basculement. RA-GRS ajoute l'accès en lecture à la région secondaire."},
  {t:"Azure Identity",q:"Qu'est-ce que Microsoft Entra ID (anciennement Azure Active Directory) ?",o:["Un Active Directory Windows traditionnel","Le service de gestion des identités et accès (IAM) cloud de Microsoft, offrant l'authentification, l'autorisation, la gestion des identités pour les services Microsoft 365, Azure et les applications tierces","Un service uniquement pour les entreprises","Un service de stockage des mots de passe"],a:1,e:"Microsoft Entra ID (ex Azure AD) est le service IAM cloud de Microsoft. Il gère les identités (utilisateurs, groupes, apps) et les accès (authentification avec MFA, SSO). Différent de l'AD Windows traditionnel : pas de stratégies GPO, pas de domaine LDAP. Utilisé pour Microsoft 365 et Azure."},
  {t:"Azure Identity",q:"Qu'est-ce que le Single Sign-On (SSO) dans Entra ID ?",o:["Un seul mot de passe pour tous les services","La capacité à se connecter une seule fois avec un compte Microsoft Entra et accéder à toutes les applications liées (Microsoft 365, Azure, apps SaaS tierces) sans se reconnecter","Un service de synchronisation des mots de passe","Un service de réinitialisation des mots de passe"],a:1,e:"Le SSO Entra ID permet à un utilisateur de se connecter une seule fois et d'accéder à toutes les applications configurées (Microsoft 365, Salesforce, GitHub, etc.) sans saisir ses identifiants à nouveau. Améliore la productivité et réduit les risques liés à la multiplication des mots de passe."},
  {t:"Azure Identity",q:"Qu'est-ce que l'authentification multifacteur (MFA) dans Entra ID ?",o:["Un système nécessitant deux mots de passe différents","Un mécanisme de sécurité qui exige au moins deux facteurs de vérification : quelque chose que vous connaissez (mot de passe) + quelque chose que vous avez (téléphone) ou êtes (biométrie)","Un service de gestion des appareils","Un service de connexion via réseaux sociaux"],a:1,e:"La MFA Entra ID ajoute une couche de sécurité : après le mot de passe, l'utilisateur doit valider via l'app Authenticator, un SMS, un appel ou une clé FIDO2. Réduit de 99,9% le risque de compromission de compte. Activable via Azure AD Conditional Access ou Entra ID Protection."},
  {t:"Azure Identity",q:"Qu'est-ce que l'Accès Conditionnel (Conditional Access) dans Entra ID ?",o:["Un accès limité aux heures de bureau uniquement","Un système de politiques qui évalue des signaux (utilisateur, localisation, appareil, application) pour décider d'autoriser, bloquer ou exiger une authentification renforcée (MFA)","Un service de gestion des mots de passe","Un accès disponible uniquement pour les administrateurs"],a:1,e:"L'Accès Conditionnel fonctionne comme un 'if/then' : SI un utilisateur accède depuis un pays risqué ou un appareil non géré, ALORS exiger MFA ou bloquer l'accès. Centralise le contrôle d'accès basé sur l'identité, l'appareil, la localisation, l'application et le risque."},
  {t:"Azure Security",q:"Qu'est-ce que le RBAC (Role-Based Access Control) dans Azure ?",o:["Un système de contrôle d'accès par mot de passe","Un système d'autorisation qui permet de gérer finement qui peut accéder aux ressources Azure, à quelles ressources et ce qu'ils peuvent faire, en attribuant des rôles à des identités","Un service antivirus Azure","Un type de pare-feu Azure"],a:1,e:"Le RBAC Azure attribue des rôles (Lecteur, Contributeur, Propriétaire, rôles personnalisés) à des identités (utilisateurs, groupes, service principals) sur une portée (groupe d'admin, abonnement, RG, ressource). Principe du moindre privilège. Les rôles s'héritent vers le bas."},
  {t:"Azure Security",q:"Qu'est-ce que Microsoft Defender for Cloud ?",o:["Un antivirus pour les VMs Azure","Un service de gestion de la posture de sécurité (CSPM) et de protection des workloads cloud (CWP) qui évalue en continu la sécurité des ressources Azure, AWS et GCP et génère des recommandations","Un service de pare-feu","Un service de gestion des identités"],a:1,e:"Microsoft Defender for Cloud (ex Security Center + Defender) combine CSPM (évaluation de la posture, Secure Score, recommandations) et CWP (protection contre les menaces pour VMs, containers, bases de données). Couvre Azure, AWS et GCP via Azure Arc."},
  {t:"Azure Security",q:"Qu'est-ce qu'Azure Key Vault ?",o:["Un coffre-fort physique pour les clés de datacenter","Un service cloud sécurisé pour stocker et gérer les secrets (mots de passe, clés API), les clés de chiffrement et les certificats, avec journalisation des accès et contrôle granulaire","Un service de gestion des accès","Un service de sauvegarde des données"],a:1,e:"Azure Key Vault permet de stocker de façon sécurisée : secrets (connection strings, API keys), clés de chiffrement (protection par HSM optionnelle), certificats TLS/SSL. L'accès est contrôlé via RBAC et journalisé. Les applications accèdent aux secrets via l'API sans les coder en dur."},
  {t:"Azure Security",q:"Qu'est-ce que le chiffrement côté serveur dans Azure Storage ?",o:["Un chiffrement que le client doit activer manuellement","Un chiffrement automatique des données au repos dans Azure Storage, géré par Microsoft, utilisant AES-256 — activé par défaut pour tous les nouveaux comptes sans impact sur les performances","Un chiffrement uniquement pour les données en transit","Un service payant optionnel"],a:1,e:"Azure Storage chiffre automatiquement toutes les données au repos avec AES-256 (identique à BitLocker). Activé par défaut, transparent, sans impact sur les performances. Clés gérées par Microsoft par défaut, ou Customer-Managed Keys (CMK) via Azure Key Vault pour plus de contrôle."},
  {t:"Azure Security",q:"Qu'est-ce que Microsoft Entra ID Protection ?",o:["Un antivirus pour les PC","Un service qui utilise l'IA pour détecter les risques liés aux identités (connexions suspectes, identifiants compromis) et permet d'automatiser les réponses via des politiques","Un service de gestion des certificats","Un service de contrôle d'accès réseau"],a:1,e:"Entra ID Protection analyse des milliards de signaux pour détecter les risques : impossible travel, IP anonymes, identifiants compromis, spray de mots de passe. Peut déclencher automatiquement MFA ou blocage pour les connexions risquées. Tableau de bord des risques pour les admins."},
  {t:"Azure Cost",q:"Qu'est-ce qu'Azure Cost Management ?",o:["Un service de réduction automatique des coûts","Un ensemble d'outils pour analyser, surveiller et optimiser les dépenses Azure, incluant les tableaux de bord de coûts, budgets, alertes et recommandations d'optimisation","Un service de facturation uniquement","Un service de prévision des coûts uniquement"],a:1,e:"Azure Cost Management + Billing permet de : visualiser les coûts par service/tag/RG, créer des budgets avec alertes par email, analyser les tendances, et suivre les recommandations Azure Advisor pour réduire les dépenses. Disponible dans le portail Azure sous 'Cost Management'."},
  {t:"Azure Cost",q:"Qu'est-ce qu'Azure Reservations ?",o:["Des réservations de bande passante","Des engagements de 1 ou 3 ans sur certaines ressources Azure (VMs, SQL, Cosmos DB, etc.) en échange de réductions significatives (jusqu'à 72%) par rapport aux tarifs à la demande","Un service de réservation de domaines","Des slots de déploiement réservés"],a:1,e:"Azure Reservations permet d'économiser jusqu'à 72% en s'engageant sur 1 ou 3 ans pour des ressources à usage prévisible (VMs en production, bases de données). Paiement initial ou mensuel. Économies comparables à celles du Savings Plan mais moins flexibles — liées à une région/taille spécifique."},
  {t:"Azure Cost",q:"Qu'est-ce que le Azure Savings Plan for Compute ?",o:["Un plan d'épargne financier de Microsoft","Un engagement de 1 ou 3 ans sur un montant horaire fixe de dépenses compute, offrant des réductions (jusqu'à 65%) quelle que soit la famille de VMs, région ou OS utilisés","Un service d'optimisation automatique des VMs","Un programme de fidélité pour les clients Azure"],a:1,e:"Azure Savings Plan est plus flexible que les Reservations : vous vous engagez sur un montant horaire (ex : 10$/h) et obtenez jusqu'à 65% de réduction sur toutes les ressources compute éligibles, peu importe la taille de VM, la région ou l'OS. Idéal pour les workloads dynamiques."},
  {t:"Azure Cost",q:"Qu'est-ce qu'Azure Hybrid Benefit ?",o:["Un avantage pour les clients hybrides cloud/on-premises uniquement","Un avantage de licence qui permet d'utiliser les licences Windows Server et SQL Server existantes avec Software Assurance pour réduire les coûts Azure des VMs Windows/SQL jusqu'à 85%","Un service de migration gratuit","Une fonctionnalité réseau Azure"],a:1,e:"Azure Hybrid Benefit permet de réutiliser les licences Windows Server et SQL Server avec Software Assurance pour les VMs Azure et Azure SQL, économisant jusqu'à 40-85% sur les coûts. Combiné aux Reservations, les économies peuvent atteindre 85% par rapport aux tarifs on-demand."},
  {t:"Azure Cost",q:"Qu'est-ce que le Total Cost of Ownership (TCO) Calculator d'Azure ?",o:["Un outil de calcul des taxes Azure","Un outil Microsoft permettant d'estimer les économies réalisables en migrant des workloads on-premises vers Azure, en comparant les coûts de l'infrastructure locale avec les coûts Azure équivalents","Un outil de comparaison des prix Azure","Un outil de budget mensuel Azure"],a:1,e:"Le TCO Calculator aide à quantifier les économies d'une migration cloud : vous saisissez vos serveurs, stockages et réseaux actuels, et l'outil estime le coût total de propriété on-premises (hardware, énergie, personnel, datacenters) versus Azure. Utile pour justifier la migration."},
  {t:"Azure Cost",q:"Qu'est-ce qu'Azure Pricing Calculator ?",o:["Un outil pour calculer les taxes sur les services Azure","Un outil web interactif pour estimer le coût mensuel d'une solution Azure en configurant les services souhaités (type, taille, région, durée) avant de les déployer","Un outil pour voir les factures Azure","Un outil pour comparer Azure avec AWS"],a:1,e:"Le Pricing Calculator (azure.microsoft.com/pricing/calculator) permet de simuler le coût d'une architecture Azure avant déploiement. On choisit les services, configure les paramètres (région, taille, redondance) et obtient une estimation mensuelle. Différent du TCO Calculator qui compare avec l'on-premises."},
  {t:"Azure Governance",q:"Qu'est-ce qu'Azure Policy ?",o:["Les politiques de confidentialité de Microsoft","Un service permettant de créer, assigner et gérer des politiques qui appliquent des règles sur les ressources Azure, garantissant la conformité avec les standards de l'organisation","Un service de gestion des utilisateurs","Un pare-feu Azure"],a:1,e:"Azure Policy évalue les ressources Azure par rapport à des règles définies (ex : toutes les VMs doivent être dans une région spécifique, les comptes de stockage doivent utiliser HTTPS). Peut auditer (rapport de conformité) ou bloquer les ressources non conformes. Intégré avec GitHub Actions."},
  {t:"Azure Governance",q:"Qu'est-ce que le principe du moindre privilège dans Azure ?",o:["Donner tous les droits administrateurs à tout le monde","Donner à chaque utilisateur ou processus uniquement les droits minimum nécessaires à l'exécution de ses tâches — ni plus, ni moins — pour réduire la surface d'attaque","Donner aucun droit par défaut","Partager les droits entre tous les membres d'une équipe"],a:1,e:"Le principe du moindre privilège (Least Privilege) est fondamental dans Azure RBAC : attribuez uniquement le rôle minimum nécessaire (Lecteur si la personne doit juste consulter, pas Propriétaire) sur la portée minimale (RG spécifique, pas tout l'abonnement). Réduit les dommages en cas de compromission."},
  {t:"Azure Governance",q:"Qu'est-ce que le Microsoft Cloud Adoption Framework (CAF) ?",o:["Un framework de développement d'applications","Un guide complet de bonnes pratiques, documentations et outils Microsoft pour planifier, implémenter et gouverner l'adoption du cloud Azure dans les organisations","Un service Azure de migration automatique","Un framework de facturation Azure"],a:1,e:"Le CAF (Cloud Adoption Framework) fournit les bonnes pratiques pour l'adoption d'Azure : Stratégie, Plan, Prêt, Adopter, Gouverner, Gérer. C'est le guide de référence pour les organisations qui commencent ou accélèrent leur transformation cloud. Couvre technique et organisationnel."},
  {t:"Azure Governance",q:"Qu'est-ce que le Microsoft Azure Well-Architected Framework ?",o:["Un outil de déploiement automatique","Un ensemble de 5 piliers (Fiabilité, Sécurité, Optimisation des coûts, Excellence opérationnelle, Efficacité des performances) pour évaluer et améliorer les architectures Azure","Un service de monitoring Azure","Un framework de développement d'applications"],a:1,e:"Le Well-Architected Framework évalue les architectures sur 5 piliers : Fiabilité (résilience), Sécurité (protection), Optimisation des coûts (valeur), Excellence opérationnelle (DevOps), Performance (scalabilité). Azure Advisor intègre ces recommandations dans le portail Azure."},
  {t:"Azure Governance",q:"Qu'est-ce que Azure Blueprints ?",o:["Des modèles de conception graphique","Un service permettant de créer des environnements Azure reproductibles et conformes en empaquetant Resource Groups, politiques, RBAC et ARM templates dans un seul artefact déployable","Un service de sauvegarde des configurations","Un service de versioning des ressources Azure"],a:1,e:"Azure Blueprints permet de définir des environnements standard (ex : environnement PCI-DSS compliant) avec tous leurs composants (RGs, politiques, RBAC, ARM templates) et de les déployer de façon répétable et auditée. Idéal pour assurer la conformité lors de la création de nouveaux abonnements."},
  {t:"Azure Monitoring",q:"Qu'est-ce qu'Azure Monitor ?",o:["Un service de sécurité Azure","La plateforme centralisée de monitoring Azure qui collecte, analyse et agit sur les métriques et logs des ressources Azure et on-premises, avec des alertes et tableaux de bord","Un service de gestion des coûts","Un service de déploiement automatique"],a:1,e:"Azure Monitor est la solution de monitoring unifiée d'Azure : collecte métriques (CPU, mémoire, latence) et logs (activités, diagnostics, applications), les analyse via Log Analytics (KQL), crée des alertes et actions automatiques. Intégre Application Insights pour les applications."},
  {t:"Azure Monitoring",q:"Qu'est-ce qu'Azure Service Health ?",o:["Un service de diagnostic des VMs","Un tableau de bord personnalisé qui informe sur la santé des services Azure que vous utilisez — incidents actifs, maintenances planifiées et avis de santé — avec des alertes configurables","Un service de vérification de la santé des bases de données","Un service de monitoring du réseau uniquement"],a:1,e:"Azure Service Health fournit des informations personnalisées sur : les incidents Azure affectant vos services (Service Issues), les maintenances planifiées (Planned Maintenance), les avis de santé et historiques. Configurez des alertes pour être notifié proactivement des problèmes affectant vos ressources."},
  {t:"Azure Monitoring",q:"Qu'est-ce qu'Azure Advisor ?",o:["Un service de support technique payant","Un service de conseil personnalisé qui analyse les ressources Azure et génère des recommandations pour améliorer la fiabilité, sécurité, performance, excellence opérationnelle et réduire les coûts","Un assistant IA pour la programmation","Un service de planning de migration"],a:1,e:"Azure Advisor analyse vos ressources et recommande des améliorations dans 5 catégories : Coûts (VMs sous-utilisées à réduire), Sécurité (MFA, correctifs), Fiabilité (Availability Sets), Excellence opérationnelle (ARM templates), Performance (mises à niveau). Gratuit, accessible dans le portail Azure."}
];

window.QDATA[3] = [
  {t:"Azure Database",q:"Qu'est-ce qu'Azure SQL Database ?",o:["Un SQL Server installé sur une VM Azure","Un service de base de données relationnelle PaaS entièrement géré, compatible SQL Server, avec haute disponibilité, sauvegardes automatiques, patches et scalabilité sans gestion de serveurs","Un service de base de données NoSQL","Un service d'entrepôt de données"],a:1,e:"Azure SQL Database est une base de données relationnelle DBaaS (Database as a Service). Microsoft gère tout : patches, sauvegardes automatiques (jusqu'à 35 jours de rétention), haute disponibilité (SLA 99,99%). Compatible avec les applications SQL Server existantes. Trois modèles d'achat : DTU, vCore, serverless."},
  {t:"Azure Database",q:"Qu'est-ce qu'Azure Cosmos DB ?",o:["Une base de données SQL uniquement","Une base de données NoSQL entièrement gérée et mondialement distribuée supportant plusieurs API (SQL/NoSQL, MongoDB, Cassandra, Gremlin, Table) avec latence inférieure à 10ms","Un service de cache Redis","Un entrepôt de données analytiques"],a:1,e:"Azure Cosmos DB est la base de données NoSQL flagship d'Azure : distribution mondiale en quelques clics, latence < 10ms au 99e percentile, SLA de disponibilité 99,999%, scalabilité automatique. Support de multiples modèles de données (documents, graphes, clé-valeur, colonnes) via différentes API."},
  {t:"Azure Database",q:"Qu'est-ce qu'Azure Database for PostgreSQL ?",o:["PostgreSQL installé sur une VM Azure","Un service de base de données PostgreSQL entièrement géré (PaaS) avec haute disponibilité, sauvegardes automatiques et mises à l'échelle sans gestion d'infrastructure","Un service de migration PostgreSQL","Un service d'analytique basé sur PostgreSQL"],a:1,e:"Azure Database for PostgreSQL Flexible Server est un PaaS pour PostgreSQL. Microsoft gère l'infrastructure, les patches OS et moteur, les sauvegardes automatiques. Vous gérez les bases de données, schémas, utilisateurs et performances. Haute disponibilité intégrée avec standby."},
  {t:"Azure Database",q:"Qu'est-ce qu'Azure Cache for Redis ?",o:["Un service de stockage permanent de données","Un service de cache en mémoire distribué basé sur Redis open-source, offrant des opérations à faible latence pour accélérer les applications en cachant les données fréquemment utilisées","Un service de messagerie","Un service de base de données graphe"],a:1,e:"Azure Cache for Redis fournit un cache en mémoire ultra-rapide (microsecondes) basé sur Redis. Cas d'usage : caching de résultats de requêtes, sessions utilisateurs, pub/sub, leaderboards. Microsoft gère l'infrastructure Redis. Niveaux : Basic, Standard (réplication), Premium (clustering, persistance)."},
  {t:"Azure Database",q:"Quand faut-il choisir Azure Cosmos DB plutôt qu'Azure SQL Database ?",o:["Toujours — Cosmos DB est supérieur","Pour les données non structurées ou semi-structurées avec besoin de distribution mondiale, latence ultra-faible et scalabilité massive, ou si le modèle NoSQL (document, graphe) convient mieux","Pour les transactions financières complexes uniquement","Pour les bases de données petites uniquement"],a:1,e:"Cosmos DB est préféré pour : données sans schéma fixe, distribution mondiale multi-régions, latence < 10ms, APIs multiples (MongoDB, Cassandra), scalabilité très large. SQL Database est préféré pour : données relationnelles avec intégrité référentielle, transactions ACID, jointures complexes."},
  {t:"Azure AI",q:"Qu'est-ce qu'Azure AI Services (anciennement Cognitive Services) ?",o:["Des services IA que les développeurs doivent entraîner eux-mêmes","Un ensemble d'APIs et services IA préentraînés permettant d'ajouter des capacités d'intelligence (vision, parole, langage, décision) aux applications sans expertise en ML","Un service de calcul GPU uniquement","Un service de stockage de modèles ML"],a:1,e:"Azure AI Services (ex Cognitive Services) fournit des APIs REST pour : vision (analyse d'images, OCR), parole (Speech-to-Text, Text-to-Speech), langage (traduction, analyse de sentiment, QnA), décision (anomalie detection, personnalisation). Utilisation via API sans gérer de modèles."},
  {t:"Azure AI",q:"Qu'est-ce qu'Azure Machine Learning ?",o:["Un service de Business Intelligence","Une plateforme cloud complète pour les data scientists permettant de créer, entraîner, déployer et gérer des modèles ML à grande échelle avec des outils no-code et code-first","Un service de visualisation de données","Un service de bases de données analytiques"],a:1,e:"Azure Machine Learning est la plateforme MLOps d'Azure : Azure ML Studio (interface visuelle no-code), notebooks Jupyter, SDK Python/R, AutoML, pipeline d'entraînement, gestion des expériences, registre de modèles, endpoints de déploiement, monitoring des modèles en production."},
  {t:"Azure AI",q:"Qu'est-ce qu'Azure OpenAI Service ?",o:["Un service de recherche web","Un service permettant d'accéder aux modèles GPT-4, DALL-E, Whisper d'OpenAI via l'infrastructure Azure sécurisée, avec les garanties de conformité et SLA Microsoft","Un service de traduction automatique","Un service de chatbot basique"],a:1,e:"Azure OpenAI Service fournit un accès API aux modèles OpenAI (GPT-4, DALL-E, Whisper, Ada embeddings) déployés sur l'infrastructure Azure sécurisée. Les données ne servent pas à entraîner OpenAI. Intégration avec Azure AI Search, Azure AI Studio, SLA Microsoft."},
  {t:"Azure AI",q:"Qu'est-ce qu'Azure AI Search (anciennement Cognitive Search) ?",o:["Un service de recherche Google intégré à Azure","Un service de recherche cloud avec IA intégrée qui permet d'indexer, enrichir (avec IA) et rechercher du contenu de diverses sources, incluant l'extraction d'informations depuis des documents non structurés","Un service de filtrage d'emails","Un service de recommandation de produits"],a:1,e:"Azure AI Search est une plateforme de recherche as a service : indexation de contenus (Blob, SQL, Cosmos DB), enrichissement via des compétences cognitives (extraction d'entités, OCR, traduction), recherche en texte intégral avec scores de pertinence. Utilisé pour la recherche d'entreprise et RAG."},
  {t:"Azure DevTools",q:"Qu'est-ce qu'Azure DevOps ?",o:["Un service de déploiement de VMs uniquement","Une suite d'outils pour les équipes DevOps : Azure Repos (Git), Azure Pipelines (CI/CD), Azure Boards (Agile), Azure Test Plans, Azure Artifacts (packages) — couvrant le cycle de vie complet du développement logiciel","Un IDE de développement","Un service de monitoring d'applications"],a:1,e:"Azure DevOps est une plateforme complète de développement : Boards (Scrum/Kanban), Repos (Git privé), Pipelines (CI/CD multi-cloud), Test Plans (tests manuels/automatisés), Artifacts (npm, NuGet, Maven). Intégration avec GitHub, Jenkins, Jira."},
  {t:"Azure DevTools",q:"Qu'est-ce que GitHub Actions dans le contexte Azure ?",o:["Un service de gestion de profils GitHub","Une plateforme CI/CD intégrée à GitHub permettant d'automatiser les workflows de build, test et déploiement, avec des intégrations natives pour Azure (deploy to App Service, AKS, Azure Functions)","Un service de révision de code uniquement","Un service de gestion des issues"],a:1,e:"GitHub Actions permet d'automatiser le cycle de vie des applications via des workflows YAML. Actions Azure officielles : déploiement sur App Service, AKS, Azure Functions, VMs. Intégration avec Azure credentials, OIDC pour l'authentification sans secrets. Alternative à Azure Pipelines."},
  {t:"Azure DevTools",q:"Qu'est-ce qu'Azure Resource Manager (ARM) ?",o:["Un gestionnaire de ressources humaines","La couche de gestion d'Azure qui traite toutes les requêtes de création, mise à jour et suppression des ressources Azure, permettant une gestion cohérente via portail, CLI, PowerShell ou APIs","Un service de monitoring","Un service de facturation Azure"],a:1,e:"ARM est le plan de contrôle d'Azure : toutes les opérations (portail, CLI, PowerShell, SDK, APIs REST) passent par ARM qui authentifie, autorise et orchestre les actions. Les ARM templates (JSON) ou Bicep permettent le déploiement déclaratif d'infrastructure (IaC)."},
  {t:"Azure DevTools",q:"Qu'est-ce qu'Azure Bicep ?",o:["Un service de monitoring Azure","Un langage déclaratif pour déployer des ressources Azure via des templates lisibles et concis — alternative plus simple aux ARM templates JSON pour l'Infrastructure as Code","Un service de container orchestration","Un service de déploiement de bases de données"],a:1,e:"Bicep est le langage IaC natif d'Azure : syntaxe plus simple qu'ARM JSON, sans accolades imbriquées, avec support des modules, décompilation depuis ARM JSON. Les fichiers .bicep se compilent automatiquement en ARM templates. Intégré dans Azure CLI, Azure DevOps, GitHub Actions."},
  {t:"Azure DevTools",q:"Qu'est-ce que le portail Azure ?",o:["Un site web public Microsoft","Une console web unifiée fournissant une interface graphique pour gérer tous les services Azure : créer, configurer, monitorer et supprimer des ressources depuis un navigateur","Un service Azure payant","Un service uniquement pour les administrateurs"],a:1,e:"Le portail Azure (portal.azure.com) est l'interface web pour gérer Azure : création de ressources, tableaux de bord personnalisés, monitoring, gestion IAM. Accessible depuis n'importe quel navigateur. Alternative aux outils en ligne de commande (Azure CLI, PowerShell) pour les tâches visuelles."},
  {t:"Azure DevTools",q:"Qu'est-ce que Azure Cloud Shell ?",o:["Un service de shell Linux uniquement","Un terminal interactif et authentifié accessible depuis le portail Azure ou shell.azure.com, fournissant Azure CLI et Azure PowerShell dans un environnement préconfiguré sans installation locale","Un service de connexion SSH aux VMs","Un service de gestion des certificats"],a:1,e:"Azure Cloud Shell fournit un environnement bash ou PowerShell directement dans le navigateur, pré-authentifié avec votre compte Azure, avec Azure CLI, PowerShell, kubectl, helm, terraform préinstallés. Stockage Azure Files pour la persistance des fichiers. Aucune installation locale nécessaire."},
  {t:"Azure Services",q:"Qu'est-ce qu'Azure Logic Apps ?",o:["Un service de logique mathématique","Un service d'automatisation des workflows et d'intégration d'applications via une interface visuelle no-code/low-code, avec plus de 400 connecteurs vers des services Azure et tiers","Un service de gestion de la logique métier uniquement","Un service de débogage d'applications"],a:1,e:"Azure Logic Apps permet d'automatiser des workflows sans code : déclencher sur un email, traiter des données, appeler des APIs, stocker dans SQL. Connecteurs natifs pour Salesforce, SAP, Twitter, Office 365, Azure services. Mode Standard (single-tenant) ou Consumption (multi-tenant)."},
  {t:"Azure Services",q:"Qu'est-ce qu'Azure Service Bus ?",o:["Un service de transport public digital","Un service de messagerie cloud d'entreprise entièrement géré pour les files d'attente (queues) et les topics pub/sub, avec garanties de livraison, ordonnancement et transactions","Un service de bus réseau virtuel","Un service de streaming de données en temps réel"],a:1,e:"Azure Service Bus est un broker de messages pour l'intégration d'applications et microservices : Queues (point-à-point, FIFO, sessions), Topics (publish/subscribe, filtres). Garanties : au moins une livraison, déduplication, transactions. Plus avancé qu'Azure Queue Storage."},
  {t:"Azure Services",q:"Qu'est-ce qu'Azure Event Hub ?",o:["Un hub pour les événements Teams","Un service d'ingestion de données et événements à grande échelle (millions d'événements/seconde), conçu pour les pipelines big data, la télémétrie IoT et les streams d'événements","Un service de gestion des alertes","Un service de messagerie one-to-one"],a:1,e:"Azure Event Hubs est une plateforme de streaming d'événements : ingestion de millions d'événements/seconde depuis IoT, applications, logs. Compatible Apache Kafka. Les événements sont retenus jusqu'à 90 jours. Différent de Service Bus : Event Hubs est pour les streams, Service Bus pour les messages."},
  {t:"Azure Services",q:"Qu'est-ce qu'Azure IoT Hub ?",o:["Un service de stockage IoT","Un hub cloud géré qui permet la communication bidirectionnelle entre applications IoT et les appareils connectés, avec gestion des identités d'appareils, messages device-to-cloud et cloud-to-device","Un service de monitoring IoT uniquement","Un service de déploiement d'appareils IoT"],a:1,e:"Azure IoT Hub connecte des millions d'appareils IoT au cloud : communication bidirectionnelle (D2C messages, C2D messages, méthodes directes, device twin), gestion des appareils (provisionnement, mise à jour firmware), sécurité per-device. S'intègre avec Event Hubs pour l'analytique."},
  {t:"Azure Services",q:"Qu'est-ce qu'Azure Content Delivery Network (CDN) ?",o:["Un service de compression de contenu","Un réseau mondial de serveurs distribués géographiquement (PoP) qui met en cache du contenu statique près des utilisateurs finaux pour réduire la latence et améliorer l'expérience utilisateur","Un service de création de contenu","Un service de traduction de contenu"],a:1,e:"Azure CDN distribue le contenu (images, vidéos, JS, CSS) depuis des PoP (Points of Presence) proches des utilisateurs, réduisant la latence. Partenaires : Microsoft, Akamai, Verizon. Réduit la charge sur le serveur origine et améliore les performances des applications mondialement distribuées."},
  {t:"Azure Services",q:"Qu'est-ce qu'Azure Synapse Analytics ?",o:["Un service de messagerie analytique","Une plateforme analytique unifiée combinant l'entrepôt de données (SQL Pools), le traitement big data (Spark Pools), la gestion des pipelines de données et l'intégration avec Power BI et Azure ML","Un service de monitoring des performances","Un service de stockage analytique uniquement"],a:1,e:"Azure Synapse Analytics intègre dans une seule expérience : SQL Serverless/Dedicated Pools (entrepôt de données), Apache Spark (big data), Data Integration (pipelines), Link vers Cosmos DB/SQL. Interface Synapse Studio. Successeur d'Azure SQL Data Warehouse."},
  {t:"Azure Services",q:"Qu'est-ce que Microsoft Power BI en relation avec Azure ?",o:["Un service de gestion d'alimentation","Un service de Business Intelligence et visualisation qui s'intègre nativement avec les services Azure (Synapse, SQL, Blob, Cosmos DB) pour créer des tableaux de bord et rapports interactifs","Un service de données uniquement","Un IDE pour les data scientists"],a:1,e:"Power BI est la solution BI de Microsoft qui s'intègre avec tous les services de données Azure. Connecteurs natifs vers Azure SQL, Synapse Analytics, Azure Analysis Services, Blob Storage, Cosmos DB. Les rapports publiés dans Power BI Service peuvent être intégrés dans Azure portail ou applications."},
  {t:"Azure Migration",q:"Qu'est-ce qu'Azure Migrate ?",o:["Un service de migration de fichiers uniquement","Un hub centralisé d'outils et services pour découvrir, évaluer et migrer les workloads on-premises (serveurs, bases de données, applications web, données) vers Azure","Un service de sauvegarde Azure","Un service de synchronisation de répertoires"],a:1,e:"Azure Migrate fournit un environnement centralisé pour la migration : découverte et inventaire des serveurs on-premises, évaluation de la compatibilité et estimation des coûts Azure, migration des VMs (VMware, Hyper-V, physiques), bases de données et applications web."},
  {t:"Azure Migration",q:"Qu'est-ce que le service Azure Database Migration Service ?",o:["Un service de sauvegarde des bases de données","Un service entièrement géré permettant de migrer des bases de données locales vers Azure avec un minimum de temps d'arrêt, supportant SQL Server, MySQL, PostgreSQL, MongoDB et Oracle","Un service de réplication de bases de données uniquement","Un service de création de bases de données"],a:1,e:"Azure Database Migration Service (DMS) simplifie la migration des bases de données on-premises vers Azure : SQL Server → Azure SQL, MySQL → Azure Database for MySQL, PostgreSQL → Azure Database for PostgreSQL, MongoDB → Cosmos DB. Migration online (temps d'arrêt minimal) ou offline."},
  {t:"Azure Support",q:"Quels sont les niveaux de support Azure disponibles ?",o:["Free uniquement","Basic (inclus), Developer, Standard, Professional Direct et Premier/Unified — chaque niveau offrant différents SLA de réponse, canaux de support et services proactifs","Standard et Premium uniquement","Free et Enterprise uniquement"],a:1,e:"Azure propose 5 plans de support : Basic (inclus, documentation/forums), Developer (email en heures ouvrées, < 8h pour sévérité C), Standard (24/7, < 2h pour sévérité B), Professional Direct (< 1h sévérité B, advisory), Premier/Unified (TAM dédié, formation). Prix croissants."},
  {t:"Azure Support",q:"Qu'est-ce que le SLA (Service Level Agreement) dans le contexte Azure ?",o:["Un contrat de location de serveurs","Un accord formel de Microsoft définissant les engagements de disponibilité et performance pour chaque service Azure, avec des crédits de service en cas de non-respect","Un guide de meilleures pratiques","Un document de pricing Azure"],a:1,e:"Le SLA Azure définit pour chaque service le pourcentage de disponibilité garanti (ex : 99,9% pour une VM avec disque Premium, 99,99% pour les zones de disponibilité). Si Microsoft ne respecte pas le SLA, des crédits de service sont accordés (10-30% de remboursement)."},
  {t:"Azure Support",q:"Qu'est-ce que le programme Azure Free Account ?",o:["Un abonnement Azure entièrement gratuit et illimité","Un compte Azure offrant 200$ de crédits pour 30 jours, 12 mois de services populaires gratuits (quantités limitées) et certains services toujours gratuits, idéal pour explorer Azure","Un service uniquement pour les développeurs","Un abonnement gratuit réservé aux étudiants"],a:1,e:"Azure Free Account offre : 200$ de crédits pendant 30 jours pour explorer tous les services, 12 mois de services populaires gratuits (VMs B1, 5GB Blob, 250GB SQL), et plus de 55 services toujours gratuits (Azure Functions, App Service F1, Cosmos DB). Carte bancaire requise pour vérification d'identité."},
  {t:"Azure Support",q:"Où trouver les mises à jour et annonces des services Azure ?",o:["Uniquement dans la documentation Azure","Sur azure.microsoft.com/updates — la page officielle des mises à jour Azure listant les nouvelles fonctionnalités, aperçus publics et disponibilités générales (GA) par service et région","Dans les emails de facturation Azure","Dans Azure Monitor uniquement"],a:1,e:"azure.microsoft.com/updates liste toutes les mises à jour Azure : nouvelles fonctionnalités, preview publiques, GA. Filtrable par service, région et type. Également : Azure Blog pour les annonces détaillées, Azure Roadmap pour les fonctionnalités à venir, et Tech Community pour les discussions."},
  {t:"Azure Compliance",q:"Qu'est-ce que Microsoft Trust Center ?",o:["Un centre de support téléphonique","Un portail centralisé (microsoft.com/trustcenter) fournissant des informations sur la sécurité, la confidentialité et la conformité des produits et services Microsoft, incluant les certifications et rapports d'audit","Un service de gestion des certificats SSL","Un service de vérification des identités"],a:1,e:"Microsoft Trust Center est la ressource principale pour la conformité Microsoft : certifications obtenues (ISO 27001, SOC 1/2/3, PCI DSS, HIPAA), informations sur la protection des données, rapports d'audit disponibles via Service Trust Portal. Aide à évaluer les risques de conformité."},
  {t:"Azure Compliance",q:"Qu'est-ce que le Service Trust Portal de Microsoft ?",o:["Un portail pour les demandes de support","Un portail où les clients Azure peuvent accéder aux rapports d'audit, certifications de conformité, évaluations de risques et autres documents relatifs à la sécurité et conformité Microsoft","Un portail de gestion des services Azure","Un portail de facturation Microsoft"],a:1,e:"Le Service Trust Portal (servicetrust.microsoft.com) fournit les rapports d'audit de conformité de Microsoft (SOC 2, ISO 27001, PCI DSS, etc.), les évaluations régionales et sectorielles, les guides de conformité par réglementation (RGPD, HIPAA). Accessible avec un compte Microsoft."},
  {t:"Azure Compliance",q:"Qu'est-ce que la résidence des données (data residency) dans Azure ?",o:["La vitesse de stockage des données","La capacité de contrôler le pays ou la région géographique où les données clients sont stockées et traitées, pour respecter les réglementations locales (ex : RGPD en Europe)","Le type de stockage utilisé","La durée de conservation des données"],a:1,e:"La résidence des données garantit que vos données restent dans la région Azure que vous choisissez. Azure s'engage à ne pas déplacer vos données hors de la région sélectionnée (sauf réplication DR que vous activez vous-même). Crucial pour le RGPD (données UE) et les réglementations nationales."},
  {t:"Azure Architecture",q:"Qu'est-ce que la Défense en profondeur (Defense in Depth) dans Azure ?",o:["Un type de pare-feu avancé","Une stratégie de sécurité qui utilise plusieurs couches de protection (physique, identité, réseau, hôte, application, données) pour qu'un attaquant doive franchir plusieurs barrières avant d'atteindre les données","Un service de sécurité Azure unique","Une politique de mots de passe complexes"],a:1,e:"La défense en profondeur utilise des couches concentriques : Physique (sécurité datacenter), Identité (MFA, Conditional Access), Périmètre (DDoS, Firewall), Réseau (NSG, segmentation), Hôte (Defender for Endpoint, patches), Application (OWASP, secure coding), Données (chiffrement). Chaque couche ralentit une attaque."},
  {t:"Azure Architecture",q:"Qu'est-ce que le modèle Zero Trust dans Azure ?",o:["Un modèle sans sécurité","Un modèle de sécurité qui part du principe qu'aucun utilisateur, appareil ou réseau n'est digne de confiance par défaut : vérifier explicitement, utiliser le moindre privilège, supposer la brèche","Un réseau sans authentification","Un service de sécurité Azure gratuit"],a:1,e:"Zero Trust : 'Ne jamais faire confiance, toujours vérifier'. Dans Azure : vérification systématique de l'identité (Entra ID, MFA), accès au moindre privilège (RBAC), microsegmentation réseau, chiffrement ubiquitaire. Plutôt que de faire confiance au réseau interne, toutes les requêtes sont traitées comme potentiellement hostiles."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Firewall ?",o:["Un service antivirus","Un service de sécurité réseau cloud managé qui protège les ressources Azure VNet avec inspection stateful, filtrage FQDN, renseignements sur les menaces et journalisation centralisée","Un service de pare-feu applicatif (WAF) uniquement","Un pare-feu pour les VMs individuellement"],a:1,e:"Azure Firewall est un pare-feu réseau/applicatif managé pour les VNets Azure : règles réseau (IP, port, protocole), règles d'application (FQDN filtrage), IDPS (Intrusion Detection), inspection TLS, renseignements sur les menaces Microsoft. Haute disponibilité built-in, scalabilité automatique."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'un Network Security Group (NSG) dans Azure ?",o:["Un groupe de services réseau Azure","Un groupe de règles de sécurité réseau (allow/deny) applicable aux subnets ou interfaces réseau de VMs Azure pour filtrer le trafic entrant et sortant selon IP source/destination, port et protocole","Un service de monitoring réseau","Un service de connexion VPN"],a:1,e:"Les NSG définissent des règles de sécurité réseau (priorité, protocole, source/destination IP, port, action allow/deny) appliquées aux sous-réseaux ou NICs. Règles par défaut permettent le trafic VNet interne et bloquent l'internet entrant. Gratuit, premier niveau de défense réseau."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure DDoS Protection ?",o:["Un service de protection contre les virus","Un service qui protège les ressources Azure contre les attaques DDoS (Distributed Denial of Service), avec Basic (inclus) ou Standard (avancé, avec mitigation adaptative et alertes)","Un service de monitoring réseau","Un service de compression réseau"],a:1,e:"Azure DDoS Protection Basic est activé automatiquement pour toutes les ressources Azure. DDoS Protection Standard (payant) ajoute : mitigation automatique adaptative, monitoring en temps réel, métriques détaillées, support de l'équipe DDoS Rapid Response, SLA de protection garantie."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Application Gateway ?",o:["Un service de gestion d'APIs","Un load balancer applicatif (Layer 7) qui offre des fonctionnalités SSL termination, URL-based routing, session affinity, Web Application Firewall (WAF) pour les applications web","Un service de passerelle pour les appareils IoT","Un service VPN pour les applications"],a:1,e:"Azure Application Gateway est un LB Layer 7 pour applications web : affinité de session basée sur les cookies, SSL offloading, routing basé sur URL (ex : /api → pool backend API), WAF pour protection OWASP Top 10, autoscaling, zone-redundant. Idéal pour les applications web complexes."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Load Balancer ?",o:["Un service d'équilibrage de charge applicatif","Un service d'équilibrage de charge Layer 4 (TCP/UDP) qui distribue le trafic entrant vers les VMs saines d'un pool backend, avec health probes et règles de load balancing","Un service de routage basé sur les URLs","Un service de gestion du trafic web"],a:1,e:"Azure Load Balancer est un LB Layer 4 (transport) interne ou public : distribue le trafic TCP/UDP entre les VMs d'un pool backend selon les health probes. Standard SKU : zone-redundant, HTTPS probes. Utilisé pour les applications non-HTTP ou avec besoin de contrôle bas niveau."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Traffic Manager ?",o:["Un gestionnaire du trafic dans un VNet","Un service DNS-based global load balancer qui distribue le trafic entre les endpoints Azure, on-premises ou externes selon des méthodes de routage (priorité, performance, géographique, round-robin)","Un service de monitoring du réseau","Un service de cache CDN global"],a:1,e:"Azure Traffic Manager est un DNS load balancer global : les clients reçoivent l'IP du meilleur endpoint selon la méthode de routage. Méthodes : Priority (failover), Weighted (A/B testing), Performance (latence), Geographic (résidence), Multivalue, Subnet. Health monitoring des endpoints."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Front Door ?",o:["Un service de contrôle d'accès physique","Un service d'entrée global sécurisé et scalable qui combine CDN, load balancing applicatif global, WAF et SSL offload pour accélérer et sécuriser les applications web à l'échelle mondiale","Un service de passerelle VPN","Un service de monitoring d'applications"],a:1,e:"Azure Front Door est une solution entrée mondiale Layer 7 : routage intelligent basé sur la latence, WAF global (protège contre OWASP Top 10, DDoS), CDN intégré, SSL offload, URL rewriting, health probes. Optimise les applications mondialement distribuées avec acceleration via anycast."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Arc ?",o:["Un service de sauvegarde Azure","Un service permettant de gérer des ressources hors d'Azure (serveurs on-premises, autres clouds, edge) via le portail Azure, ARM et les services Azure comme si elles étaient dans Azure","Un service de déploiement Kubernetes uniquement","Un service de réseau virtuel étendu"],a:1,e:"Azure Arc étend les outils de gestion Azure à n'importe où : serveurs Windows/Linux on-premises ou autres clouds (gestion, Defender, Monitor, Policy), clusters Kubernetes (GitOps, extensions Azure), SQL Server (inventaire, Defender). Unifie la gestion dans un contexte multi-cloud et hybride."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Batch ?",o:["Un service de traitement des commandes","Un service cloud pour l'exécution de workloads HPC (High Performance Computing) et batch à grande échelle — gère automatiquement un pool de VMs, distribue les jobs et gère les erreurs","Un service de traitement des messages","Un service de mise à jour groupée des ressources"],a:1,e:"Azure Batch est conçu pour les calculs HPC et batch à grande échelle : simulation scientifique, rendu 3D, transcoding vidéo. Azure gère le pool de VMs, distribue les tâches, surveille et gère les tentatives en cas d'erreur. Facturation uniquement pour les VMs utilisées pendant l'exécution."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Spring Apps ?",o:["Un service de gestion du printemps commercial","Un service entièrement géré pour héberger des microservices Java Spring Boot, Azure gérant l'infrastructure Spring Cloud (Eureka, Config Server, Gateway) sans configuration","Un service IoT basé sur Spring","Un framework de développement Java"],a:1,e:"Azure Spring Apps (ex Azure Spring Cloud) est un PaaS pour les applications Java Spring Boot et Spring Cloud. Azure gère : Config Server, Service Registry (Eureka), Gateway, Circuit Breaker. Les développeurs déploient juste leur code. Supporte aussi les microservices Steeltoe (.NET)."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Static Web Apps ?",o:["Un service d'hébergement de vidéos","Un service pour déployer des applications web statiques (HTML/CSS/JS, React, Angular, Vue) avec CI/CD intégré depuis GitHub/Azure DevOps, APIs serverless et distribution CDN mondiale","Un service de blogs uniquement","Un service d'hébergement de fichiers statiques uniquement"],a:1,e:"Azure Static Web Apps héberge automatiquement les applications web modernes (React, Angular, Vue, Svelte) avec : CI/CD automatique depuis GitHub Actions, APIs Azure Functions intégrées, distribution CDN mondiale, domaines custom, SSL, authentification intégrée (Entra ID, GitHub, Twitter)."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Container Registry (ACR) ?",o:["Un annuaire de conteneurs physiques","Un service de registre privé pour stocker et gérer les images de conteneurs Docker et les artefacts OCI (Helm charts), intégré avec AKS, App Service, Container Instances","Un service de déploiement de conteneurs","Un service de monitoring de conteneurs"],a:1,e:"Azure Container Registry (ACR) est le registre de conteneurs privé d'Azure : stockage et distribution d'images Docker et Helm charts, géo-réplication pour distribution mondiale, analyse de vulnérabilités avec Defender for Containers, tâches ACR pour build/test automatiques, accès via Entra ID."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure API Management ?",o:["Un service de gestion de projets API","Un service gateway pour publier, sécuriser, transformer et analyser les APIs, offrant un portail développeur, politiques de throttling/authentification, documentation et analytics","Un service de création d'APIs uniquement","Un service de monitoring d'APIs"],a:1,e:"Azure API Management (APIM) est un proxy intelligent pour les APIs : portail développeur (documentation, test), politiques (rate limiting, transformation, authentication, caching), analytics (usage, performance), multi-environnements (sandbox, prod). Supporte REST, SOAP, GraphQL, WebSocket, gRPC."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Service Fabric ?",o:["Un service de réseau virtuel distribué","Une plateforme de systèmes distribués pour déployer et gérer des microservices et conteneurs fiables et scalables, utilisée en interne par Microsoft pour de nombreux services Azure","Un service de messagerie d'entreprise","Un service de déploiement de VMs"],a:1,e:"Azure Service Fabric est la plateforme de microservices qui fait tourner de nombreux services Azure internes (Azure SQL Database, Cosmos DB, Event Hubs). Gère le cycle de vie des services (déploiement, mise à l'échelle, mise à jour, réparation automatique). Supporte .NET, Java, containers."},
  {t:"Azure Architecture",q:"Qu'est-ce que la Sovereign Cloud Azure ?",o:["Un cloud Azure uniquement pour la souveraineté nationale","Des instances Azure distinctes et isolées physiquement pour des exigences gouvernementales ou de conformité spécifiques (Azure Government pour les USA, Azure China via 21Vianet, Azure Germany)","Un cloud Azure sans connexion internet","Un cloud Azure réservé aux hôpitaux"],a:1,e:"Azure Sovereign Clouds sont des instances distinctes : Azure Government (FedRAMP, DoD Level 5, pour agences US), Azure China (opéré par 21Vianet, conformité China Cybersecurity Law), Azure Germany (Deutsche Telekom as data trustee, fermé en 2021). Données physiquement séparées du cloud public Azure."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Availability Zones par rapport aux régions Azure ?",o:["Des régions Azure plus petites","Des datacenters physiquement séparés DANS une même région Azure (bâtiments distincts avec alimentation/refroidissement/réseau indépendants), protégeant contre les pannes de datacenter","Des régions Azure de secours","Des zones de tests Azure"],a:1,e:"Les Availability Zones sont des datacenters séparés au sein d'une même région Azure (ex : 3 zones dans France Centre). Distance de quelques km entre zones. Protection contre les pannes de datacenter (incendie, coupure de courant). SLA 99,99% pour les VMs zone-redundant. Différent des régions (continents)."},
  {t:"Azure Architecture",q:"Qu'est-ce que Azure Site Recovery ?",o:["Un service de récupération de fichiers supprimés","Un service de reprise après sinistre qui réplique les VMs Azure, Hyper-V, VMware et serveurs physiques vers une région Azure secondaire, permettant le basculement automatique ou manuel en cas de sinistre","Un service de sauvegarde de bases de données","Un service de monitoring de l'infrastructure"],a:1,e:"Azure Site Recovery (ASR) fournit la réplication continue des VMs et données vers une région Azure secondaire. En cas de sinistre, ASR orchestre le basculement (failover) vers la région secondaire. Testez les plans DR sans impact sur la production. RTO et RPO configurables. S'intègre avec Azure Backup."},
  {t:"Azure Architecture",q:"Qu'est-ce qu'Azure Backup ?",o:["Un service de copie de fichiers uniquement","Un service de sauvegarde cloud centralisé, simple et économique pour protéger les données Azure (VMs, SQL, fichiers) et on-premises (Windows Server, Hyper-V, VMware) avec chiffrement et rétention configurable","Un service de réplication des données","Un service de snapshot uniquement"],a:1,e:"Azure Backup est le service de backup natif Azure : sauvegarde des VMs Azure, bases de données Azure SQL, Azure Files, partages SMB, serveurs Windows, VMware. Recovery Services Vault centralise les politiques de sauvegarde. Chiffrement automatique, rétention configurable (jours/semaines/mois/années), LRS ou GRS."}
];

window.QDATA[4] = [
  {t:"Azure Identity avancé",q:"Quelle est la différence entre authentification (AuthN) et autorisation (AuthZ) dans Azure ?",o:["Ce sont des synonymes","L'authentification vérifie l'identité ('qui êtes-vous ?') — Azure AD/Entra ID; l'autorisation détermine les permissions ('que pouvez-vous faire ?') — RBAC. Les deux sont nécessaires mais distincts","L'authentification gère les ressources","L'autorisation vérifie les mots de passe"],a:1,e:"AuthN (Authentication) : prouver son identité via credentials, MFA, certificat. AuthZ (Authorization) : une fois identifié, quels droits ? RBAC Azure gère AuthZ en attribuant des rôles. Azure AD/Entra ID gère AuthN. Exemple : vous vous connectez (AuthN) et accédez uniquement aux RGs autorisés (AuthZ)."},
  {t:"Azure Identity avancé",q:"Qu'est-ce qu'un Service Principal dans Azure ?",o:["Un compte admin Azure","Une identité de sécurité utilisée par les applications, services et outils d'automatisation pour s'authentifier auprès d'Azure et accéder aux ressources selon leurs rôles RBAC définis","Un compte de service Windows","Une clé d'API Azure"],a:1,e:"Un Service Principal est l'identité d'une application dans Azure AD (comme un compte utilisateur mais pour les apps). Utilisé par : Azure CLI, scripts, pipelines CI/CD, applications. Associé à un App Registration. S'authentifie via client secret, certificat ou Managed Identity. RBAC attribué pour les accès nécessaires."},
  {t:"Azure Identity avancé",q:"Qu'est-ce qu'une Managed Identity dans Azure ?",o:["Un compte utilisateur géré par Microsoft","Une identité automatiquement gérée par Azure pour les services Azure (VMs, App Service, Functions) qui permet de s'authentifier auprès d'autres services Azure sans gérer de credentials dans le code","Un service d'annuaire d'entreprise","Un type de compte de service AD DS"],a:1,e:"Managed Identity élimine la gestion des secrets dans le code : Azure crée et gère automatiquement une identité pour la ressource. Deux types : System-assigned (liée au cycle de vie de la ressource) et User-assigned (créée indépendamment, réutilisable). La VM/App accède à Key Vault sans mot de passe."},
  {t:"Azure Identity avancé",q:"Qu'est-ce que Microsoft Entra External ID ?",o:["Un service AD pour les clients externes payants uniquement","Un service permettant aux organisations de gérer les identités des clients et partenaires (B2C, B2B) avec des flux d'inscription, connexion via réseaux sociaux ou comptes d'entreprise","Un accès externe à Azure uniquement","Un service de VPN pour partenaires"],a:1,e:"Entra External ID (fusion de Azure AD B2C et Azure AD External Identities) gère les identités des utilisateurs externes : B2B (collaborateurs d'entreprises partenaires avec leurs comptes professionnels) et B2C (clients finaux pouvant s'inscrire avec email, Google, Facebook). Personnalisation de l'UX d'authentification."},
  {t:"Azure Identity avancé",q:"Qu'est-ce que Microsoft Entra Privileged Identity Management (PIM) ?",o:["Un service de gestion des identités premium","Un service qui fournit un accès juste-à-temps (JIT) et juste-assez (JEA) aux ressources Azure et Microsoft 365, avec workflow d'approbation, activation temporaire et audit des accès privilégiés","Un service d'authentification renforcée","Un service de révision de code"],a:1,e:"PIM applique le principe du moindre privilège aux comptes privilégiés : les admins n'ont des droits élevés que pendant le temps nécessaire (ex : 1 heure). Activation avec justification, approbation optionnelle, notification, audit complet. Réduit la surface d'attaque des comptes à hauts privilèges."},
  {t:"Azure Networking avancé",q:"Qu'est-ce que l'Azure Private Link ?",o:["Un VPN privé Azure","Un service permettant d'accéder aux services Azure PaaS (Azure Storage, SQL, etc.) via une endpoint privée dans votre VNet, le trafic ne passant jamais par internet public","Un service de réseau privé virtuel pour les employés","Un service de connexion entre VNets"],a:1,e:"Azure Private Link crée des Private Endpoints dans votre VNet avec une IP privée pour accéder aux services PaaS (Azure Storage, SQL, Cosmos DB, Key Vault, etc.) sans passer par internet. Le trafic reste sur le réseau backbone Microsoft. Améliore la sécurité et réduit les risques d'exfiltration de données."},
  {t:"Azure Networking avancé",q:"Qu'est-ce qu'Azure Bastion ?",o:["Un service de sauvegarde des VMs","Un service PaaS entièrement géré offrant un accès RDP/SSH sécurisé aux VMs Azure directement depuis le portail Azure via TLS, sans exposer les VMs à internet via des IPs publiques","Un service de pare-feu Azure","Un service de VPN site-to-site"],a:1,e:"Azure Bastion élimine le besoin d'IPs publiques sur les VMs pour l'administration. Connexion RDP/SSH depuis le portail Azure via le navigateur, sans installer de client, chiffrée TLS. La VM n'est exposée qu'au subnet Azure Bastion privé. Réduit la surface d'attaque des VMs de production."},
  {t:"Azure Networking avancé",q:"Qu'est-ce que l'Azure NAT Gateway ?",o:["Une passerelle réseau domestique","Un service permettant à un subnet Azure d'effectuer des connexions sortantes vers internet avec une IP publique statique et dédiée, sans nécessiter d'IP publique sur chaque VM","Un service de routage VPN","Un service de translation DNS"],a:1,e:"Azure NAT Gateway fournit une connectivité internet sortante pour un subnet via une ou plusieurs IPs publiques statiques et dédiées. Garantit que les connexions sortantes utilisent toujours les mêmes IPs (utile pour les whitelists). Remplace efficacement le NATting via Load Balancer ou VMs."},
  {t:"Azure Networking avancé",q:"Qu'est-ce qu'Azure Web Application Firewall (WAF) ?",o:["Un antivirus web","Un service de protection des applications web contre les attaques web courantes (OWASP Top 10 : injections SQL, XSS, CSRF) intégrable avec Application Gateway, Front Door et Azure CDN","Un pare-feu réseau pour les VNets","Un service de monitoring d'applications web"],a:1,e:"Azure WAF protège les applications web des attaques du OWASP Top 10 (injections SQL, XSS, etc.) via des règles prédéfinies et personnalisables. S'intègre avec Application Gateway (régional), Azure Front Door (global), Azure CDN. Mode détection (log) ou prévention (block). Bot protection incluse."},
  {t:"Azure Compute avancé",q:"Quand utiliser Azure Functions vs Azure Logic Apps ?",o:["Ce sont des services identiques","Functions est adapté au code custom complexe, à faible latence ou avec dependencies techniques; Logic Apps est idéal pour les workflows visuels d'intégration entre services avec des connecteurs no-code/low-code","Functions est uniquement pour Python","Logic Apps ne supporte pas Azure"],a:1,e:"Functions : code custom (Python, C#, JS, Java), logique complexe, bibliothèques tierces, performance critique. Logic Apps : orchestration visuelle de workflows d'intégration (connecteurs +400 services, conditions, boucles) sans écrire de code. Les deux peuvent être combinés dans un même workflow."},
  {t:"Azure Compute avancé",q:"Qu'est-ce qu'Azure Virtual Desktop (AVD) ?",o:["Un bureau virtuel pour les jeux","Un service de virtualisation de bureau et d'applications Windows dans Azure permettant aux utilisateurs d'accéder à Windows 10/11 multi-session et à Microsoft 365 depuis n'importe quel appareil","Un service de streaming vidéo","Un service de conférence vidéo"],a:1,e:"Azure Virtual Desktop (ex Windows Virtual Desktop) est une solution DaaS (Desktop as a Service) : Windows 10/11 Enterprise multi-session (jusqu'à 32 utilisateurs par VM), Microsoft 365 Apps optimisé, Outlook/Teams nativement intégrés. Accessible depuis Windows, Mac, iOS, Android, navigateur. Sécurisé via Entra ID."},
  {t:"Azure Storage avancé",q:"Qu'est-ce qu'Azure Data Lake Storage Gen2 (ADLS Gen2) ?",o:["Un lac de données pour le stockage de vidéos","Un service combinant Azure Blob Storage avec un système de fichiers hiérarchique (HDFS-compatible), optimisé pour les workloads analytiques big data, avec contrôle d'accès granulaire au niveau fichier","Un service de base de données analytique","Un service de streaming de données"],a:1,e:"ADLS Gen2 combine la scalabilité et l'économie d'Azure Blob avec un namespace hiérarchique (répertoires vrais, pas simulés) et une sécurité granulaire (ACL POSIX au niveau fichier/dossier). Compatible Hadoop (HDFS). Utilisé avec Azure Databricks, Synapse Analytics, HDInsight pour le big data."},
  {t:"Azure Storage avancé",q:"Qu'est-ce que le stockage ZRS (Zone-Redundant Storage) dans Azure ?",o:["Réplication dans 3 pays différents","Réplication synchrone dans 3 zones de disponibilité d'une même région Azure, protégeant contre les pannes de datacenter tout en maintenant une durabilité de 12 nines","Réplication uniquement locale","Réplication dans 2 régions Azure"],a:1,e:"ZRS réplique les données dans 3 zones de disponibilité de la même région. Protection contre les pannes d'un datacenter entier (contrairement à LRS). Les lectures/écritures continuent si une zone tombe. Durabilité 12 nines (99,9999999999%). Plus cher que LRS mais disponibilité supérieure. Recommandé pour les données critiques."},
  {t:"Azure Database avancée",q:"Qu'est-ce qu'Azure SQL Managed Instance ?",o:["Une VM avec SQL Server","Une instance SQL Server dans Azure avec une compatibilité proche de 100% avec SQL Server on-premises (SQL Agent, CLR, linked servers, Service Broker), intégrée dans un VNet pour la sécurité réseau","Un service de migration SQL uniquement","Un service identique à Azure SQL Database"],a:1,e:"Azure SQL Managed Instance est un PaaS SQL Server avec compatibilité maximale : SQL Server Agent, CLR, Service Broker, Database Mail, Linked Servers, databases multi-bases. Déployé dans un VNet pour l'isolation réseau. Idéal pour les migrations SQL Server complexes nécessitant ces fonctionnalités non disponibles dans Azure SQL Database."},
  {t:"Azure Database avancée",q:"Qu'est-ce qu'Azure Databricks ?",o:["Un service de bases de données Databricks","Une plateforme d'analytique collaborative basée sur Apache Spark, optimisée par Microsoft et Databricks, pour le traitement big data, le machine learning et l'analytique avancée","Un service de visualisation de données","Un service de déploiement Kubernetes"],a:1,e:"Azure Databricks est une plateforme d'analytique et de ML basée sur Apache Spark : notebooks collaboratifs (Python, Scala, R, SQL), clusters Spark managés, MLflow intégré pour MLOps, Delta Lake pour ACID sur le data lake. Intégration avec ADLS Gen2, Synapse, Power BI, Azure ML."},
  {t:"Azure AI avancé",q:"Qu'est-ce qu'Azure AI Studio ?",o:["Un studio de création musicale IA","Un portail unifié pour créer, entraîner et déployer des solutions d'IA générative, avec accès aux modèles Azure OpenAI, aux outils de prompt engineering, au Responsible AI toolkit et au déploiement","Un service de reconnaissance d'images uniquement","Un IDE pour les développeurs Python"],a:1,e:"Azure AI Studio (ai.azure.com) est le hub centralisé pour l'IA générative sur Azure : catalogue de modèles (Azure OpenAI, Meta, Mistral, Cohere), playground de prompts, fine-tuning, évaluation des modèles, déploiement, métriques de Responsible AI. Successeur de Azure ML Studio pour l'IA générative."},
  {t:"Azure AI avancé",q:"Qu'est-ce que le Responsible AI dans Azure ?",o:["Une politique de support Azure","Un ensemble de 6 principes Microsoft (équité, fiabilité, confidentialité, inclusion, transparence, responsabilité) guidant le développement et l'utilisation de l'IA, avec des outils dans Azure AI Studio pour les évaluer","Un service de certification Azure","Un audit externe des algorithmes"],a:1,e:"Responsible AI Microsoft s'appuie sur 6 principes : Fairness (équité), Reliability & Safety (fiabilité), Privacy & Security (confidentialité), Inclusiveness (inclusion), Transparency (transparence), Accountability (responsabilité). Azure Responsible AI tools : Fairlearn, InterpretML, Azure Machine Learning Responsible AI dashboard."},
  {t:"Azure DevOps avancé",q:"Qu'est-ce que l'Infrastructure as Code (IaC) dans Azure ?",o:["Un code de facturation Azure","La pratique de définir et gérer l'infrastructure (VMs, réseaux, bases de données) via des fichiers de configuration versionables (ARM templates, Bicep, Terraform, Pulumi) plutôt que manuellement","La génération automatique de code applicatif","Un service de déploiement sans code"],a:1,e:"L'IaC permet de traiter l'infrastructure comme du code : versionné dans Git, révisable, testable, reproductible. Azure supporte : ARM JSON (natif), Bicep (simplifié, natif), Terraform (HashiCorp, multi-cloud), Pulumi (code Python/JS/C#). Les pipelines CI/CD déploient l'infrastructure automatiquement."},
  {t:"Azure DevOps avancé",q:"Qu'est-ce que DevOps et comment Azure y contribue ?",o:["Un service Azure uniquement","Une culture et ensemble de pratiques combinant développement (Dev) et opérations (Ops) pour livrer plus rapidement et de façon fiable; Azure DevOps, GitHub Actions, Azure Monitor facilitent les pipelines CI/CD, tests et monitoring","Un service de déploiement automatique uniquement","Un framework de gestion de projet"],a:1,e:"DevOps combine Dev + Ops pour des livraisons rapides et fiables. Sur Azure : CI/CD avec Azure Pipelines/GitHub Actions, Infrastructure as Code (Bicep/Terraform), monitoring avec Azure Monitor/Application Insights, tests automatisés, déploiements blue/green ou canary avec slots App Service."},
  {t:"Azure Governance avancé",q:"Qu'est-ce que les tags Azure et comment aident-ils ?",o:["Des étiquettes esthétiques sur les ressources","Des métadonnées clé-valeur appliquées aux ressources Azure pour l'organisation, la facturation par département/projet, la recherche et les politiques de gouvernance (Azure Policy peut exiger les tags)","Un service de nommage automatique","Un service de catégorisation des abonnements"],a:1,e:"Les tags Azure sont des paires clé-valeur (ex : Env:Prod, Team:Finance, Project:Migration) attachées aux ressources. Utilisations : analyse des coûts par tag dans Cost Management, automatisation (scripts ciblant les ressources taguées), conformité (Azure Policy exigeant certains tags), inventaire."},
  {t:"Azure Governance avancé",q:"Qu'est-ce que Azure Cost Management + Billing ?",o:["Un service de paiement des factures uniquement","Une suite d'outils pour analyser les dépenses Azure (par service, région, tag, groupe de ressources), définir des budgets, recevoir des alertes de dépassement et obtenir des recommandations d'optimisation","Un service de prévision boursière","Un service d'audit de conformité"],a:1,e:"Azure Cost Management : tableaux de bord de coûts avec drill-down (par tag, RG, service, région), budgets avec alertes email (ex : 80% atteint), analyse des tendances, recommandations Azure Advisor pour réduire les coûts. Intégré dans le portail Azure, accessible via API. Exportations vers Storage."},
  {t:"Azure Compliance avancé",q:"Qu'est-ce que le RGPD (GDPR) et comment Azure y répond-il ?",o:["Une réglementation Azure interne","Un règlement européen sur la protection des données personnelles des citoyens UE; Azure offre des outils pour y répondre : résidence des données EU, chiffrement, audit logs, outils de conformité, DPA (Data Processing Agreement)","Un service de sécurité Azure","Une norme de sécurité internationale"],a:1,e:"Le RGPD exige : consentement explicite, droit d'accès/suppression, notification de brèche (72h), résidence des données. Azure répond via : DPA Microsoft RGPD, régions EU pour la résidence, Azure Purview pour la gouvernance des données, EUDB (EU Data Boundary), chiffrement par défaut, audit logs."},
  {t:"Azure Compliance avancé",q:"Qu'est-ce que la norme ISO 27001 et Azure la détient-il ?",o:["Une norme de qualité alimentaire","Une norme internationale de management de la sécurité de l'information (ISMS); Azure détient la certification ISO 27001 pour la majorité de ses services, attestant des pratiques de sécurité rigoureuses","Une norme de développement logiciel","Une réglementation financière"],a:1,e:"ISO 27001 est la norme internationale de référence pour les ISMS (Information Security Management Systems). Azure est certifié ISO 27001 via des audits tiers indépendants. La certification couvre les processus de gestion des risques, sécurité physique, contrôles d'accès, cryptographie. Consultable sur Service Trust Portal."},
  {t:"Azure Compliance avancé",q:"Qu'est-ce que SOC 2 et comment Azure est-il conforme ?",o:["Un service cloud concurrent","Un standard d'audit américain (AICPA) évaluant les contrôles de sécurité, disponibilité, intégrité du traitement, confidentialité et vie privée; Azure obtient des rapports SOC 2 Type I et II annuels vérifiés par des tiers","Un type d'abonnement Azure","Un service de conformité automatique"],a:1,e:"SOC 2 Type II est un audit indépendant AICPA qui vérifie les contrôles sur 6-12 mois (vs Type I : à un instant). Azure obtient des rapports SOC 2 Type II couvrant Security, Availability, Confidentiality. Disponibles sur Service Trust Portal avec un NDA Microsoft."},
  {t:"Azure Sustainability",q:"Qu'est-ce que l'engagement de durabilité de Microsoft pour Azure ?",o:["Microsoft s'engage uniquement sur la réduction des coûts","Microsoft s'engage à être carbone négatif d'ici 2030, carbone zéro d'ici 2050, en fonctionnant avec 100% d'énergie renouvelable, et fournit un 'Emissions Impact Dashboard' aux clients Azure pour mesurer leur empreinte","Microsoft n'a pas d'engagement environnemental","Microsoft utilise uniquement de l'énergie nucléaire"],a:1,e:"Microsoft Azure : 100% énergies renouvelables depuis 2025, carbone négatif en 2030, élimination des émissions historiques en 2050, zéro déchet en décharge en 2030. Emissions Impact Dashboard dans Azure Portal permet aux clients de mesurer l'empreinte carbone de leurs workloads Azure."},
  {t:"Azure Sustainability",q:"Qu'est-ce que l'Azure Emissions Impact Dashboard ?",o:["Un tableau de bord de consommation électrique","Un outil dans le portail Azure permettant aux clients de visualiser les émissions carbone associées à leurs services Azure, segmentées par service, région et période de temps","Un service de monitoring des performances","Un tableau de bord de facturation verte"],a:1,e:"L'Emissions Impact Dashboard affiche les émissions CO2 (scope 1, 2, 3) de vos ressources Azure : breakdown par service (VMs, Storage, SQL), par région (les régions avec plus d'énergies renouvelables émettent moins), et tendances temporelles. Aide à optimiser les déploiements pour réduire l'empreinte carbone."},
  {t:"Azure Misc",q:"Qu'est-ce qu'Azure Subscription vs Azure Account ?",o:["Ce sont des termes identiques","Un compte Azure (Microsoft Account ou Work Account) est l'identité pour se connecter; un abonnement est une unité de facturation et de limite de ressources liée à ce compte — un compte peut avoir plusieurs abonnements","Un abonnement est supérieur au compte","Un compte est uniquement pour les tests"],a:1,e:"Compte Azure = identité Microsoft (personal: @outlook.com, work: @entreprise.com). Un compte peut être associé à plusieurs abonnements (Dev, Test, Prod). Chaque abonnement est une limite de facturation et de contrôle indépendante. Les ressources sont créées dans un abonnement spécifique."},
  {t:"Azure Misc",q:"Qu'est-ce que Azure Marketplace ?",o:["Un magasin de produits physiques Microsoft","Un store en ligne proposant des milliers d'applications, services et solutions certifiés de Microsoft et ses partenaires, déployables directement dans Azure (VMs préconfigurées, logiciels, services gérés)","Un service de vente de licences uniquement","Un service de recherche d'emplois IT"],a:1,e:"Azure Marketplace est la boutique en ligne de solutions Azure : VMs préconfigurées (SQL, SAP, Oracle), outils de sécurité, solutions de backup/monitoring tiers, services SaaS des partenaires. Solutions certifiées par Microsoft, déployables en quelques clics, facturées via la facture Azure."},
  {t:"Azure Misc",q:"Quelle est la différence entre Azure Preview (Aperçu) et GA (General Availability) ?",o:["Ce sont des termes identiques","Les Previews sont des fonctionnalités en cours de développement sans SLA ni garantie de support, souvent gratuites ou réduites; GA signifie que la fonctionnalité est officiellement disponible avec SLA, support complet et tarification stable","Les GA sont moins stables que les Previews","Les Previews sont disponibles uniquement pour Microsoft"],a:1,e:"Preview Public : fonctionnalité disponible pour tous mais sans SLA ni support standard, peut changer ou être supprimée. Preview Privée : invitation seulement. GA : fonctionnalité officiellement disponible avec SLA garanti, support complet, tarification stable. Évitez les Previews en production sauf évaluation."},
  {t:"Azure Misc",q:"Qu'est-ce qu'Azure Arc enabled servers ?",o:["Des serveurs Azure uniquement","Un service permettant de gérer des serveurs Windows/Linux situés en dehors d'Azure (on-premises, AWS, GCP) comme s'ils étaient des ressources Azure natives, avec Azure Policy, Defender, Monitor et RBAC","Un type de VM Azure","Un service de migration de serveurs"],a:1,e:"Azure Arc pour serveurs installe un agent sur des serveurs hors-Azure. Une fois connectés, ces serveurs apparaissent dans le portail Azure : gestion via Azure Policy (conformité), monitoring via Azure Monitor, sécurité via Defender for Servers, RBAC Azure, tags. Unifie la gestion multi-environnements."},
  {t:"Azure Misc",q:"Qu'est-ce qu'Azure Resource Graph ?",o:["Un graphique de visualisation des ressources","Un service permettant d'explorer et interroger toutes les ressources Azure à grande échelle via des requêtes KQL (Kusto Query Language) dans le portail Azure ou via API, sans dépendances de données","Un service de relation entre ressources","Un service de mapping réseau Azure"],a:1,e:"Azure Resource Graph permet des requêtes complexes sur toutes vos ressources Azure : 'Toutes les VMs non-taguées', 'Tous les comptes de stockage avec HTTP activé', 'Ressources créées ce mois'. Utilise KQL, résultats quasi-instantanés même sur des milliers de ressources. Intégré dans Azure Policy."},
  {t:"Azure Misc",q:"Qu'est-ce que l'Azure Well-Architected Review ?",o:["Un audit payant de Microsoft","Un outil d'évaluation interactif gratuit (learn.microsoft.com/azure/architecture) qui évalue votre architecture Azure selon les 5 piliers du Well-Architected Framework et génère des recommandations personnalisées","Un service de certification Azure","Une API d'évaluation de code"],a:1,e:"Le Well-Architected Review est un questionnaire en ligne sur vos workloads Azure : questions sur la fiabilité, sécurité, coûts, performance, excellence opérationnelle. Génère un rapport avec un score par pilier et des recommandations priorisées avec liens vers les documentations Azure."},
  {t:"Azure Misc",q:"Qu'est-ce que Microsoft Learn pour Azure ?",o:["Un service de gestion d'employés","La plateforme de formation officielle gratuite de Microsoft (learn.microsoft.com) offrant des modules, parcours d'apprentissage, labs pratiques sandbox et préparation aux certifications Azure","Un service de consulting payant","Un forum de support communautaire"],a:1,e:"Microsoft Learn fournit : modules interactifs gratuits, parcours d'apprentissage structurés par rôle (administrateur, développeur, architecte) et certification, sandbox Azure gratuite pour les labs (sans besoin d'abonnement), practice assessments pour la préparation aux certifications AZ-900, AZ-104, etc."},
  {t:"Azure Misc",q:"Qu'est-ce qu'Azure Policy Initiative (Policy Set) ?",o:["Un ensemble de politiques de facturation","Un regroupement de plusieurs Azure Policies en une seule entité assignable, permettant d'appliquer un ensemble cohérent de règles de conformité (ex : toutes les politiques pour NIST SP 800-53) en une seule action","Un type d'abonnement Azure","Un service de gestion des utilisateurs"],a:1,e:"Une Initiative Azure Policy (Policy Set) regroupe plusieurs Azure Policies : ex l'initiative 'NIST SP 800-53' contient ~200 politiques. Assigner une initiative assigne toutes ses politiques simultanément. Simplifie la gestion de la conformité réglementaire. Microsoft fournit des initiatives prédéfinies pour ISO 27001, PCI-DSS, HIPAA, etc."},
  {t:"Azure Misc",q:"Qu'est-ce qu'Azure Lighthouse ?",o:["Un service de phare réseau","Un service permettant aux prestataires de services (MSPs) de gérer les ressources Azure de plusieurs clients dans une seule expérience unifiée, avec des permissions granulaires et une audit trail complète","Un service de monitoring avancé","Un service de déploiement automatique"],a:1,e:"Azure Lighthouse est conçu pour les MSPs (Managed Service Providers) : gestion déléguée de plusieurs tenants clients depuis un seul tenant fournisseur. Permissions granulaires (pas de compte admin dans le tenant client), surveillance dans Azure Monitor, audit via Azure Policy. Sécurisé et transparent pour le client."},
  {t:"Azure Misc",q:"Qu'est-ce que la limite de ressources (Quota) dans Azure ?",o:["Le prix maximum d'un service","Des limites par défaut sur le nombre de ressources d'un certain type par région/abonnement, configurées pour protéger contre l'utilisation accidentelle excessive et modifiables via une demande de support","Un type de restriction de sécurité","La durée maximale d'une ressource"],a:1,e:"Les quotas Azure limitent : nombre de VMs par région (250 par défaut), cœurs vCPU par famille de VM, IPs publiques, etc. Ces limites évitent les dépenses accidentelles et protègent la capacité Azure. Pour augmenter un quota, soumettez une demande via Azure Support (souvent approuvée rapidement)."},
  {t:"Azure Misc",q:"Qu'est-ce qu'Azure Cost Allocation et les cost allocation rules ?",o:["Un service de répartition physique des serveurs","Un service permettant de redistribuer les coûts partagés Azure (réseaux, Key Vault, monitors) entre les différents groupes ou projets au sein d'une organisation selon des règles définies","Un service de facturation externe","Un service uniquement pour les grandes entreprises"],a:1,e:"Cost Allocation dans Cost Management permet de redistribuer les coûts de ressources partagées (Log Analytics workspace, Azure Firewall, VPN Gateway) entre les abonnements/groupes de ressources/tags qui les utilisent. Utile pour les showback/chargeback internes entre départements."}
];

window.QDATA[5] = [
  {t:"Révision Cloud",q:"Un client souhaite migrer ses applications on-premises vers Azure pour éliminer les coûts de remplacement matériel. Quel bénéfice cloud décrit-il ?",o:["La haute disponibilité","La conversion des dépenses CapEx en OpEx, éliminant les investissements matériels initiaux et leurs coûts de remplacement en faveur d'un modèle de paiement à l'utilisation","La sécurité améliorée","La réduction de la latence"],a:1,e:"Ce client décrit la conversion CapEx→OpEx : plus besoin d'acheter/remplacer des serveurs physiques. Les coûts Azure sont OpEx (abonnement mensuel). Pas de cycles de remplacement matériel tous les 3-5 ans, pas d'amortissement, pas de coûts de maintenance hardware."},
  {t:"Révision Cloud",q:"Une startup a besoin de déployer rapidement une infrastructure globale pour lancer son application dans 5 pays simultanément. Quel avantage cloud est le plus pertinent ?",o:["La reprise après sinistre","La portée mondiale d'Azure avec plus de 60 régions permettant un déploiement dans de multiples pays en quelques minutes, sans investissement en datacenters locaux","La réduction des coûts uniquement","La sécurité des données"],a:1,e:"La portée mondiale est l'avantage clé : Azure permet de déployer dans 5 régions en quelques minutes. Sans cloud, ouvrir des datacenters dans 5 pays prendrait des mois et coûterait des millions. L'agilité et la portée mondiale du cloud sont des avantages compétitifs majeurs."},
  {t:"Révision Cloud",q:"Quel est l'avantage de la scalabilité élastique pour une boutique en ligne lors du Black Friday ?",o:["Une sécurité renforcée","La capacité d'Azure à augmenter automatiquement les ressources (instances, CPU) pour absorber le pic de trafic du Black Friday puis les réduire automatiquement après, payant uniquement pour la capacité utilisée","Une disponibilité 24/7","Des sauvegardes automatiques"],a:1,e:"L'élasticité est parfaite pour les pics de trafic : Azure Scale Sets ajoute automatiquement des instances quand le CPU dépasse 70%, les retire quand il descend en dessous de 30%. Pendant le reste de l'année, on paie pour la capacité normale. Impossible à prévoir et coûteux avec du matériel physique."},
  {t:"Révision IaaS/PaaS/SaaS",q:"Un DBA migre une base de données SQL Server vers Azure. Il veut se concentrer sur l'optimisation des requêtes sans gérer l'OS ou les patches. Quel service Azure recommandez-vous ?",o:["SQL Server sur une VM Azure (IaaS)","Azure SQL Database (PaaS) — Microsoft gère l'OS, les patches SQL Server, la haute disponibilité et les sauvegardes; le DBA gère uniquement les bases de données, schémas et performances","Azure Table Storage","Azure Cosmos DB"],a:1,e:"Azure SQL Database (PaaS) est le bon choix : le DBA se concentre sur son cœur de métier (optimisation requêtes, modélisation). Azure gère OS, patches, sauvegardes automatiques, HA (99,99%), scaling. SQL Server sur VM (IaaS) nécessiterait aussi la gestion de l'OS."},
  {t:"Révision IaaS/PaaS/SaaS",q:"Une entreprise utilise Microsoft 365 (Outlook, Teams, SharePoint). Dans quel modèle de service se trouve-t-elle ?",o:["IaaS","PaaS","SaaS — Microsoft gère tout (infrastructure, plateforme et application), l'entreprise utilise juste les applications via son navigateur ou client","Aucun des précédents"],a:2,e:"Microsoft 365 est du SaaS : Microsoft gère tout de l'infrastructure à l'application. L'entreprise n'installe et ne gère rien d'autre que les licences et la configuration des utilisateurs. Exemples SaaS Microsoft : Microsoft 365, Dynamics 365, Power BI (version service)."},
  {t:"Révision Architecture",q:"Vous déployez une application critique qui ne peut pas se permettre plus de 4,4 heures d'arrêt par an. Quelle configuration Azure recommandez-vous ?",o:["Une seule VM sans redondance","Des VMs déployées dans plusieurs Availability Zones de la même région pour obtenir un SLA de 99,99% (max 52 minutes d'arrêt/an), bien en dessous du seuil de 4,4 heures","Un Availability Set uniquement","Un seul datacenter Azure"],a:1,e:"4,4 heures/an = 99,95%. Pour dépasser ce seuil et obtenir la marge de sécurité, les VMs dans plusieurs Availability Zones offrent 99,99% (max 52 min/an). Availability Set : 99,95% (max 4,4h/an — trop juste). VM sans redondance : ~99,9% (max 8,7h/an — insuffisant)."},
  {t:"Révision Sécurité",q:"Un administrateur veut s'assurer que les développeurs ne peuvent créer que des ressources Azure dans la région France Centre. Quel outil Azure utiliser ?",o:["Un NSG (Network Security Group)","Azure Policy — créer une politique 'Allowed Locations' restreignant les déploiements à la région France Centre et l'assigner à l'abonnement ou groupe de ressources concerné","Azure RBAC uniquement","Azure Key Vault"],a:1,e:"Azure Policy est l'outil de gouvernance : la politique 'Allowed Locations' (ou 'Allowed Azure regions') liste les régions autorisées. Azure bloque automatiquement toute tentative de créer une ressource dans une région non autorisée. Le NSG contrôle le trafic réseau, pas les déploiements."},
  {t:"Révision Sécurité",q:"Un développeur stocke des clés d'API en dur dans le code source de son application Azure App Service. Quelle est la meilleure pratique Azure pour remplacer cela ?",o:["Chiffrer le code source","Utiliser Azure Key Vault pour stocker les secrets, et Managed Identity pour que l'App Service accède à Key Vault sans aucun credential dans le code","Stocker les clés dans des variables d'environnement en clair","Utiliser Azure Storage pour stocker les secrets"],a:1,e:"Meilleure pratique : secrets dans Azure Key Vault + Managed Identity pour App Service. L'application obtient une identité Entra ID automatique (Managed Identity), à laquelle on accorde l'accès Key Vault. L'app récupère les secrets via l'API Key Vault sans aucun credential dans le code ou les configs."},
  {t:"Révision Sécurité",q:"Un compte administrateur Azure a été compromis. Comment l'accès conditionnel aurait-il pu réduire les risques ?",o:["En changeant automatiquement les mots de passe","En bloquant ou exigeant une MFA supplémentaire pour les connexions depuis des localisations inhabituelles, des IPs anonymes ou des appareils non conformes, rendant l'utilisation des credentials volés très difficile","En interdisant toutes les connexions externes","En activant automatiquement le chiffrement"],a:1,e:"L'Accès Conditionnel avec Entra ID Protection aurait détecté la connexion anormale (pays inhabituel, IP Tor, etc.) et exigé une MFA que l'attaquant ne peut pas fournir ou bloqué l'accès. Même avec le mot de passe correct, le compte restait protégé."},
  {t:"Révision Réseau",q:"Une entreprise a une application Azure qui doit accéder à une base de données Azure SQL sans trafic sur internet public. Quelle solution recommandez-vous ?",o:["Un VPN site-to-site","Azure Private Endpoint pour la base de données Azure SQL, créant une IP privée dans le VNet de l'application — le trafic reste sur le backbone privé Microsoft sans passer par internet","Azure ExpressRoute","Un VNet Peering uniquement"],a:1,e:"Azure Private Endpoint crée une IP privée dans le VNet pour Azure SQL. L'application accède à SQL via l'IP privée, trafic sur le backbone Microsoft. Plus sécurisé que les service endpoints (réseau d'application privé mais pas l'IP SQL). Pas besoin de VPN ou ExpressRoute pour ce cas."},
  {t:"Révision Réseau",q:"Une entreprise a des datacenters on-premises et Azure avec un besoin de connexion à 10 Gbps fiable et privée (sans internet). Quelle solution Azure choisir ?",o:["Azure VPN Gateway","Azure ExpressRoute — connexion privée dédiée via un opérateur télécom partenaire, ne passant pas par internet, avec des débits jusqu'à 100 Gbps, faible latence et SLA Microsoft garantis","Azure Virtual WAN","Azure DNS"],a:1,e:"ExpressRoute est la réponse pour les connexions privées haute performance : bande passante de 50 Mbps à 100 Gbps, ne passe pas par internet (plus fiable, plus sécurisé), latence prévisible, SLA. VPN Gateway passe par internet (moins fiable, max 1,25 Gbps, chiffré mais public)."},
  {t:"Révision Coûts",q:"Une équipe utilise des VMs Azure de taille Standard_D4s_v3 en production 24/7 depuis 2 ans et prévoit de continuer 2 ans de plus. Comment réduire significativement les coûts ?",o:["Passer aux VMs gratuites","Acheter des Azure Reservations sur 1 ou 3 ans pour ces VMs — économies jusqu'à 72% par rapport aux tarifs on-demand, avec paiement initial ou mensuel","Arrêter les VMs la nuit","Migrer vers IaaS"],a:1,e:"Pour des VMs 24/7 avec usage prévisible, les Reservations sont idéales : jusqu'à 72% d'économies sur 3 ans. Paiement tout upfront (maximum d'économies), partial upfront, ou mensuel sans frais initiaux. On s'engage sur une taille/région/OS. La VM continue de tourner normalement."},
  {t:"Révision Coûts",q:"Un projet de développement a des VMs utilisées 8h/jour les jours ouvrés uniquement. Comment optimiser les coûts ?",o:["Acheter des Reservations 3 ans","Configurer Azure Automation ou des schedules VM pour arrêter les VMs le soir et les week-ends — économiser environ 65% (16h/24h × 2 jours weekend vs 5 jours) en ne payant que les heures d'utilisation","Supprimer et recréer les VMs chaque jour","Utiliser Azure Spot VMs en production"],a:1,e:"Pour les environnements dev/test à utilisation partielle, arrêter les VMs (Stop Deallocated) coupe les coûts compute (le stockage continue). Azure Automation, schedules via Azure Portal ou scripts PowerShell peuvent automatiser les starts/stops. Économies ≈ 65% vs running 24/7."},
  {t:"Révision Coûts",q:"Un architecte compare le coût de garder un serveur on-premises vs le migrer vers Azure. Quel outil Microsoft utiliser pour estimer les économies ?",o:["Azure Pricing Calculator","Azure TCO (Total Cost of Ownership) Calculator — il modélise les coûts complets du serveur on-premises (hardware, énergie, espace, personnel, licences) vs Azure et calcule les économies potentielles sur 3-5 ans","Azure Cost Management","Azure Advisor"],a:1,e:"Le TCO Calculator (azure.microsoft.com/pricing/tco) est conçu pour comparer on-premises vs Azure : saisissez les specs serveurs, type de stockage, données réseau, coûts de datacenter. L'outil calcule le coût réel total on-premises (souvent sous-estimé) vs Azure. Pricing Calculator est pour configurer les coûts Azure uniquement."},
  {t:"Révision Gouvernance",q:"Une grande entreprise a 15 équipes avec 15 abonnements Azure différents. Comment appliquer une politique de gouvernance à tous les abonnements simultanément ?",o:["Assigner la politique à chaque abonnement manuellement 15 fois","Regrouper tous les abonnements sous un Management Group et assigner la politique Azure au niveau du Management Group — elle s'hérite automatiquement à tous les abonnements enfants","Créer 15 politiques identiques","Utiliser Azure Blueprints uniquement"],a:1,e:"Les Management Groups permettent d'appliquer des politiques (Azure Policy), des rôles RBAC et des budgets à plusieurs abonnements en une seule action. La politique s'hérite automatiquement vers le bas. Une organisation peut avoir plusieurs niveaux de Management Groups pour refléter sa structure."},
  {t:"Révision Support",q:"Un développeur Azure rencontre un problème non critique pendant les heures de bureau et a besoin d'aide par email. Quel plan de support Azure est adapté ?",o:["Basic (inclus)","Developer — supporte les requêtes de support non critiques par email en heures de bureau (lundi-vendredi), avec un SLA de réponse < 8 heures, conçu pour les développeurs et tests","Standard","Premier"],a:1,e:"Le plan Developer (environ 30$/mois) offre : support par email en heures ouvrées, < 8h pour les problèmes sévérité C (non critiques). Pour la production 24/7, il faudrait Standard. Basic (gratuit) ne donne que la documentation et les forums communautaires, sans support technique direct."},
  {t:"Révision Monitoring",q:"Une application Azure commence à avoir des erreurs en production. Quel service Azure permet de voir les logs d'erreur détaillés, les stack traces et la fréquence des exceptions ?",o:["Azure Cost Management","Azure Application Insights (composant d'Azure Monitor) — collecte automatiquement les exceptions, les traces, les dépendances et les requêtes des applications, avec recherche et alertes sur les erreurs","Azure Service Health","Azure Advisor"],a:1,e:"Application Insights est la solution APM (Application Performance Monitoring) d'Azure : collecte automatique des exceptions, stack traces, compteurs de performance, dépendances (SQL, HTTP). Détecte les anomalies, crée des alertes, map des dépendances. Intégré dans Azure Monitor."},
  {t:"Révision Monitoring",q:"Une équipe reçoit une alerte que le service Azure SQL Database de leur application a connu une panne. Où trouver les informations sur l'incident et la date de résolution prévue ?",o:["Azure Cost Management","Azure Service Health — affiche les incidents en cours affectant les services Azure que vous utilisez, avec updates en temps réel, cause, régions impactées et ETA de résolution","Azure Monitor","Azure Advisor"],a:1,e:"Azure Service Health affiche les incidents Azure affectant vos services spécifiques (pas tous les clients Azure, juste votre configuration). Pour SQL Database en France Centre, Service Health montre l'incident en cours, son état (investigué, en cours de résolution), les updates et l'historique."},
  {t:"Révision Conformité",q:"Un auditeur demande la preuve que les données d'une entreprise stockées dans Azure sont traitées conformément au RGPD. Où trouver les documents de conformité Microsoft ?",o:["Dans les paramètres Azure Portal","Sur le Service Trust Portal (servicetrust.microsoft.com) — documents de conformité, DPA (Data Processing Agreement), rapports d'audit, certifications et guides régionaux pour le RGPD","Dans Azure Cost Management","Dans Azure Monitor"],a:1,e:"Service Trust Portal est le centre de conformité Microsoft : DPA RGPD, rapports SOC 2, ISO 27001, PCI-DSS, guides de conformité par pays. L'entreprise peut télécharger le DPA Microsoft (accord sur le traitement des données) et les rapports d'audit pour prouver la conformité à l'auditeur."},
  {t:"Révision Sécurité avancée",q:"Comment Azure implémente-t-il la défense en profondeur au niveau réseau ?",o:["Via un seul pare-feu central","Via des couches multiples : Azure DDoS Protection (périmètre), Azure Firewall (réseau), NSG (sous-réseau/NIC), Application Gateway + WAF (application), Private Endpoints (élimination accès public)","Via SSL uniquement","Via un VPN unique"],a:1,e:"La défense en profondeur réseau Azure utilise des couches : 1) DDoS Protection (attaques volumétriques), 2) Azure Firewall (inspection L4/L7, FQDN filtering), 3) NSG (règles IP/port sur sous-réseau/NIC), 4) Application Gateway + WAF (OWASP Top 10 pour HTTP), 5) Private Endpoints (trafic PaaS sans internet)."},
  {t:"Révision Identity",q:"Un administrateur veut s'assurer que les comptes Entra ID avec des rôles d'administrateur global utilisent MFA. Quelle est la meilleure approche ?",o:["Envoyer un email demandant aux admins d'activer MFA","Créer une politique d'Accès Conditionnel exigeant MFA pour tous les utilisateurs avec le rôle 'Global Administrator', avec une action 'Require MFA' et aucune exception possible","Activer MFA manuellement compte par compte","Utiliser des mots de passe longs uniquement"],a:1,e:"L'Accès Conditionnel est la meilleure approche : créez une politique ciblant le rôle 'Global Administrator', avec l'action 'Require multifactor authentication'. Cette politique s'applique automatiquement à tous les admins actuels et futurs, sans dépendre de leur coopération individuelle."},
  {t:"Révision Architecture",q:"Un développeur veut exécuter une petite fonction Python qui envoie un email de bienvenue lorsqu'un utilisateur s'inscrit sur son site. Quel service Azure est le plus approprié ?",o:["Une VM Azure","Azure Functions — exécute le code Python uniquement lors de l'inscription (déclencheur HTTP ou queue), sans serveur à gérer, avec facturation uniquement à l'exécution (modèle consommation)","Azure App Service Plan Dédié","Azure Kubernetes Service"],a:1,e:"Azure Functions est parfait : code minimal (quelques lignes Python), déclenché par événement (HTTP webhook, message Queue), facturation à l'exécution. Pas besoin de serveur, OS ou scaling à gérer. Si l'inscription est rare (100/jour), les coûts sont négligeables vs une VM en continu."},
  {t:"Révision Stockage",q:"Une entreprise conserve des archives légales qui ne seront probablement jamais consultées mais doivent être conservées 10 ans. Quel tier de stockage Azure Blob recommandez-vous ?",o:["Hot (accès chaud)","Archive — le coût de stockage le plus bas (100x moins cher que Hot), tolérant une récupération en heures car les archives légales sont rarement accédées","Cool (accès froid)","LRS Premium"],a:1,e:"Archive est optimal pour les données rarement consultées : coût de stockage minimal. La récupération (réhydratation) prend 1-15 heures selon la priorité, ce qui est acceptable pour des archives légales. Si une consultation urgente est possible, Cold ou Cool serait préférable (accès en minutes)."},
  {t:"Révision Migration",q:"Une entreprise veut migrer des dizaines de VMs VMware vers Azure avec un minimum de modification. Quelle stratégie et quel outil Azure utiliser ?",o:["Recoder toutes les applications pour le cloud natif","Stratégie lift-and-shift (Rehost) avec Azure Migrate — découverte et évaluation automatique des VMs VMware, puis migration avec très peu de modifications, les VMs s'exécutant dans Azure comme on-premises","Stratégie de refactorisation complète","Reconstruction depuis zéro"],a:1,e:"Lift-and-shift avec Azure Migrate est le chemin le plus rapide : Azure Migrate découvre les VMs VMware, évalue la compatibilité et les coûts, puis migre via Azure Site Recovery. Les VMs tournent dans Azure quasiment à l'identique, sans recodage. La modernisation vers PaaS peut venir ensuite."},
  {t:"Révision Coûts avancé",q:"Quel est l'impact sur la facture Azure si une VM est arrêtée via l'OS (shutdown depuis Windows/Linux) mais pas 'deallocated' via Azure ?",o:["La VM ne coûte plus rien","La VM continue à facturer les coûts de compute car elle est toujours allouée sur l'hyperviseur Azure (les ressources CPU/RAM lui sont réservées) — seul le 'Stop Deallocated' Azure arrête la facturation compute","La VM ne coûte que le stockage","La VM est automatiquement désallouée"],a:1,e:"Critical : arrêter l'OS (shutdown) ne 'deallocate' pas la VM — Azure réserve toujours les ressources compute. Pour arrêter la facturation compute, il faut Deallocate via le portail Azure (bouton 'Stop'), CLI (`az vm deallocate`) ou PowerShell. Seul le stockage continue à être facturé après deallocate."},
  {t:"Révision Coûts avancé",q:"Qu'est-ce qu'Azure Cost Management Exports ?",o:["Un service de facturation externe","Une fonctionnalité permettant d'exporter automatiquement les données de coûts Azure vers un compte Azure Storage (CSV), pour les intégrer dans des outils BI tiers, des analyses personnalisées ou Power BI","Un rapport annuel Azure","Un service de transfert de données"],a:1,e:"Cost Management Exports programme l'exportation automatique des données de facturation Azure (usage et coûts détaillés) vers Azure Storage en CSV. Configurable pour exporter quotidiennement, hebdomadairement ou mensuellement. Les données peuvent ensuite être analysées avec Power BI, Excel ou des outils BI custom."},
  {t:"Révision Architecture avancée",q:"Quelle est la différence entre Azure Load Balancer et Azure Application Gateway ?",o:["Ce sont des services identiques","Azure Load Balancer opère en Couche 4 (TCP/UDP) et distribue le trafic basé sur l'IP et le port; Azure Application Gateway opère en Couche 7 (HTTP/HTTPS) et peut router basé sur l'URL, les headers et propose un WAF","Load Balancer est plus sécurisé","Application Gateway est moins cher"],a:1,e:"LB (Couche 4) : distribution TCP/UDP sans regarder le contenu, haute performance, pour tout trafic. Application Gateway (Couche 7) : inspecte le contenu HTTP, route /api vers serveurs API et /images vers serveurs statiques, SSL termination, WAF. Pour les applications web, Application Gateway offre plus de fonctionnalités."},
  {t:"Révision Sécurité complète",q:"Qu'est-ce que Microsoft Defender for Cloud Secure Score ?",o:["Un score de crédit Microsoft","Un score numérique (0-100%) dans Microsoft Defender for Cloud qui mesure la posture de sécurité globale de votre environnement Azure en fonction des recommandations de sécurité implémentées","Un score de performance des applications","Un score de conformité ISO"],a:1,e:"Secure Score mesure votre posture de sécurité : plus vous implémentez de recommandations Defender for Cloud (activer MFA, chiffrer les disques, patcher les VMs), plus le score augmente. Chaque recommandation a un impact sur le score. Objectif : améliorer continuellement en prioritisant les actions à fort impact."}
];

window.QDATA[6] = [
  {t:"Well-Architected",q:"Quels sont les 5 piliers du Microsoft Azure Well-Architected Framework ?",o:["Sécurité, Coût, Performance, Fiabilité, Excellence opérationnelle","Disponibilité, Scalabilité, Sécurité, Coût, Monitoring","Infrastructure, Application, Données, Réseau, Identité","Compute, Storage, Network, Database, Security"],a:0,e:"Les 5 piliers du Well-Architected Framework Azure : 1) Fiabilité (Reliability) — résilience et récupération, 2) Sécurité (Security) — protection des données et systèmes, 3) Optimisation des coûts (Cost Optimization) — valeur business, 4) Excellence opérationnelle (Operational Excellence) — déploiement et monitoring, 5) Efficacité des performances (Performance Efficiency) — scaling et latence."},
  {t:"Well-Architected",q:"Un architecte veut évaluer son workload Azure par rapport aux meilleures pratiques Microsoft. Quel outil utiliser ?",o:["Azure Pricing Calculator","Azure Well-Architected Review — un questionnaire interactif sur aka.ms/assessments qui évalue le workload selon les 5 piliers et génère un rapport de recommandations priorisées","Azure Cost Management","Azure Advisor uniquement"],a:1,e:"Azure Well-Architected Review (aka.ms/assessments) : questionnaire guidé par pilier, génère un rapport avec score par pilier et recommandations priorisées. Azure Advisor est automatique (scan les ressources existantes) mais moins ciblé sur l'architecture globale. Les deux sont complémentaires."},
  {t:"Well-Architected",q:"Comment le pilier 'Fiabilité' du Well-Architected Framework est-il implémenté dans Azure ?",o:["Via des mots de passe forts uniquement","Via la combinaison d'Availability Zones (zones de disponibilité), de régions pairées, d'Azure Site Recovery (DR), d'Azure Backup, de Load Balancers et de patterns de conception résilients comme le circuit breaker","Via la sauvegarde manuelle uniquement","Via Azure Cost Management"],a:1,e:"La fiabilité Azure combine : infrastructure (AZ, régions pairées), services de résilience (Site Recovery, Backup), distribution de charge (Load Balancer, Traffic Manager), et patterns de conception (retry, circuit breaker, graceful degradation). L'objectif est de concevoir des systèmes qui résistent aux pannes et récupèrent automatiquement."},
  {t:"Hybrid Cloud",q:"Une entreprise veut gérer ses serveurs on-premises et ses VMs Azure avec les mêmes outils et politiques Azure. Quel service utiliser ?",o:["Azure Migrate","Azure Arc — étend les services Azure de gestion (Azure Policy, Azure Monitor, Defender for Cloud, RBAC) aux serveurs on-premises, autres clouds (AWS, GCP) et appareils edge, les faisant apparaître comme des ressources Azure","Azure Virtual WAN","Azure ExpressRoute"],a:1,e:"Azure Arc est le service hybrid/multicloud : il projette les serveurs Linux/Windows on-premises dans Azure Resource Manager. Ils apparaissent dans le portail Azure, peuvent avoir des tags, des politiques Azure Policy appliquées, être monitorés avec Azure Monitor. Idéal pour la gouvernance unififiée."},
  {t:"Hybrid Cloud",q:"Quelle est la différence principale entre Azure Stack HCI et Azure Stack Hub ?",o:["Ce sont des services identiques","Azure Stack HCI est une solution hyperconvergée pour moderniser les datacenters existants avec une connexion Azure requise; Azure Stack Hub est une version complète d'Azure déployée on-premises, fonctionnant même déconnectée d'internet (scénarios air-gapped)","Stack HCI est gratuit, Stack Hub est payant","Stack Hub est plus récent"],a:1,e:"Azure Stack HCI : infrastructure hyperconvergée (compute+storage+network) gérée via Azure, requiert connexion Azure. Azure Stack Hub : version complète d'Azure (IaaS + PaaS) déployée on-premises, peut fonctionner déconnectée (régions isolées, compliance stricte). Azure Stack Edge : appliance physique Azure pour edge computing et ML at the edge."},
  {t:"Migration",q:"Quelles sont les 6 stratégies de migration cloud (6 R) selon Azure ?",o:["Copier, Déplacer, Supprimer, Reconfigurer, Répliquer, Réécrire","Rehost (lift-and-shift), Replatform (lift-and-optimize), Rearchitect (refactor), Rebuild (reconstruire), Replace (SaaS), Retire (décommissioner) — le 6ème R","Move, Migrate, Modernize, Monitor, Manage, Measure","IaaS, PaaS, SaaS, FaaS, CaaS, DBaaS"],a:1,e:"Les 6 R de migration : 1) Rehost — copier as-is vers Azure (VMs → Azure VMs), 2) Replatform — légères optimisations (SQL Server → Azure SQL Managed Instance), 3) Rearchitect — restructurer pour cloud-native (monolithe → microservices), 4) Rebuild — réécrire from scratch, 5) Replace — remplacer par SaaS (Exchange → Microsoft 365), 6) Retire — décommissionner les apps non nécessaires."},
  {t:"Migration",q:"Une entreprise veut migrer 500 VMs VMware vers Azure. Quel est le processus recommandé avec Azure Migrate ?",o:["Copier manuellement chaque VM","Étapes : 1) Déployer l'appliance Azure Migrate pour découvrir les VMs VMware, 2) Évaluer la compatibilité et estimer les coûts, 3) Répliquer les VMs sélectionnées via Azure Site Recovery, 4) Tester la migration avec un failover test, 5) Migrer en production avec le failover final","Utiliser FTP pour transférer les fichiers VMs","Exporter en OVF et importer manuellement"],a:1,e:"Azure Migrate fournit un hub centralisé : appliance légère déployée on-premises pour la découverte automatique VMware, évaluation (taille recommandée, coût estimé, compatibilité), réplication (via l'agent ASR ou sans agent pour VMware), test de migration (failover test sans impact prod), et migration finale."},
  {t:"Architecture Patterns",q:"Qu'est-ce que le pattern 'Blue-Green Deployment' et comment Azure le supporte-t-il ?",o:["Un pattern de sécurité réseau","Un pattern de déploiement avec deux environnements identiques (bleu=production active, vert=nouvelle version), permettant un basculement instantané et un rollback rapide — supporté via Azure Traffic Manager, Application Gateway ou App Service deployment slots","Un type de stockage Azure","Un pattern de base de données"],a:1,e:"Blue-Green : deux environnements identiques. Bleu = production actuelle. Vert = nouvelle version déployée et testée. Basculement instantané via Traffic Manager (changement de DNS) ou App Service Deployment Slots (swap). Si problème, rollback immédiat en rebasculant vers bleu. Zéro downtime."},
  {t:"Architecture Patterns",q:"Qu'est-ce que le pattern 'Circuit Breaker' dans le contexte Azure ?",o:["Un disjoncteur physique dans un datacenter","Un pattern de résilience qui détecte quand un service appelé échoue fréquemment et 'ouvre le circuit' pour arrêter les appels et répondre immédiatement avec une erreur ou valeur par défaut, évitant la surcharge en cascade — implémenté via Azure API Management ou des bibliothèques comme Polly","Un type de réseau virtuel","Un service de monitoring"],a:1,e:"Circuit Breaker protège des défaillances en cascade : l'état 'Closed' (normal), 'Open' (trop d'échecs → fail fast), 'Half-Open' (test si service récupéré). Azure API Management peut implémenter des politiques de circuit breaker. La bibliothèque Polly (.NET) offre des implémentations clés en main."},
  {t:"Serverless",q:"Quelle est la différence entre Azure Functions plan Consommation et plan Premium ?",o:["Ils sont identiques","Plan Consommation : facturation à l'exécution (gratuit si peu utilisé), démarrage à froid possible, max 5 minutes d'exécution; Plan Premium : instances pré-chauffées (pas de cold start), durées illimitées, réseau VNet, plus puissant — payé à l'heure comme un App Service Plan","Plan Premium est gratuit","Plan Consommation supporte le réseau VNet"],a:1,e:"Plan Consommation : scale-to-zero, payé par exécution/GB-s, cold start (100ms-5s), max 10 min (configurable). Plan Premium : instances toujours chaudes (no cold start), durée illimitée, intégration VNet, VNET injection, scaling illimité. Payé à l'heure. Pour les apps avec trafic régulier ou besoins réseau privé."},
  {t:"Serverless",q:"Azure Logic Apps vs Azure Functions : quand utiliser l'un plutôt que l'autre ?",o:["Ils sont toujours interchangeables","Logic Apps : workflows d'intégration visuels avec 400+ connecteurs, sans code, idéal pour l'intégration B2B, ETL, automatisation de processus métier; Functions : code personnalisé (C#, Python, JavaScript), traitements complexes nécessitant une logique de programmation","Functions est toujours supérieur","Logic Apps ne supporte pas Microsoft 365"],a:1,e:"Logic Apps = low-code/no-code : glisser-déposer des connecteurs (Outlook, Salesforce, SQL, SAP), conditions, boucles. Idéal pour les intégrations sans développeur. Functions = code : flexibilité totale, algorithmes complexes, bibliothèques custom. Souvent combinés : Logic Apps orchestre le workflow et appelle des Functions pour la logique métier complexe."},
  {t:"Sécurité avancée",q:"Qu'est-ce que le Zero Trust Security Model dans Azure ?",o:["Un modèle où on fait confiance à tout le monde","Un modèle de sécurité basé sur 'ne jamais faire confiance, toujours vérifier' : chaque accès est vérifié explicitement (identité + appareil + localisation), les accès sont limités au minimum nécessaire (moindre privilège), et l'on part du principe que la violation aura lieu (assume breach) — implémenté avec Entra ID, Conditional Access, PIM","Un modèle réseau sans pare-feu","Un type de VPN"],a:1,e:"Zero Trust dans Azure : 1) Verify explicitly — Conditional Access vérifie identité, appareil (compliant?), localisation, risque à chaque connexion, 2) Least privilege — PIM pour l'accès JIT (Just-In-Time) aux rôles admin, RBAC granulaire, 3) Assume breach — segmentation réseau (NSGs, Private Endpoints), surveillance continue (Sentinel, Defender), chiffrement bout-en-bout."},
  {t:"Sécurité avancée",q:"Qu'est-ce qu'Azure Sentinel (maintenant Microsoft Sentinel) ?",o:["Un pare-feu Azure","Un SIEM (Security Information and Event Management) et SOAR (Security Orchestration, Automation and Response) cloud-native qui collecte des données de sécurité à grande échelle, détecte les menaces avec l'IA, et permet l'investigation et la réponse automatisée aux incidents","Un service de sauvegarde","Un service de monitoring des coûts"],a:1,e:"Microsoft Sentinel = SIEM cloud-native basé sur Azure Monitor et Log Analytics : collecte logs de tout Azure, Microsoft 365, et solutions tierces; détecte menaces via règles analytiques et ML; visualise via workbooks; investigate avec graph d'entités; répond automatiquement via playbooks (Logic Apps). Remplace un SIEM on-premises coûteux."},
  {t:"Données",q:"Quelle est la différence entre Azure Synapse Analytics et Azure Databricks ?",o:["Ce sont des services identiques","Azure Synapse Analytics : plateforme unifiée Microsoft pour SQL data warehousing + Spark + ETL/ELT + intégration Power BI, tout-en-un avec studio intégré; Azure Databricks : plateforme Spark collaborative basée sur Apache Spark, plus puissante pour le ML/data science avancé, multi-cloud, partenariat Databricks/Microsoft","Synapse est gratuit","Databricks ne supporte pas Python"],a:1,e:"Synapse : point d'entrée unifié Microsoft (SQL Dedicated Pool pour DWH, Serverless SQL, Spark, Pipelines = ADF intégré, Power BI intégration). Databricks : Spark managé plus puissant et flexible, MLflow intégré, Delta Lake, Delta Sharing, adapté aux équipes data science avancées. Peuvent coexister : Synapse pour l'orchestration, Databricks pour le ML."},
  {t:"Données",q:"Qu'est-ce qu'Azure Data Factory (ADF) ?",o:["Une usine de fabrication Azure","Un service ETL/ELT cloud-native pour créer des pipelines de données : ingère des données depuis 90+ sources (on-premises, cloud, SaaS), transforme avec des flux de données visuels ou Spark, orchestre des workflows de données complexes avec déclencheurs et dépendances","Un service de stockage de données uniquement","Un service de visualisation de données"],a:1,e:"Azure Data Factory est le service d'intégration de données principal d'Azure : 90+ connecteurs (SQL, Oracle, SAP, Salesforce, S3, etc.), transformation visuelle (Mapping Data Flows = Spark sans code), orchestration avec pipelines, déclencheurs (temps, événements), monitoring. Utilisé pour les projets d'entrepôt de données (→ Synapse), de data lake (→ ADLS Gen2), de BI."},
  {t:"Données",q:"Pour quels cas d'usage Azure Cosmos DB est-il le meilleur choix vs Azure SQL Database ?",o:["Cosmos DB est toujours supérieur","Cosmos DB excelle pour : données à schéma variable ou semi-structurées (JSON, documents), distribution mondiale multi-région active-active, latence < 10ms garantie par SLA, scalabilité horizontale massive (pétaoctets, millions req/s), APIs multiples (SQL, MongoDB, Cassandra, Gremlin); SQL Database est supérieur pour : transactions ACID complexes, requêtes relationnelles riches (JOINs), données très structurées","SQL Database est toujours supérieur","Cosmos DB ne supporte pas les transactions"],a:1,e:"Cosmos DB pour : IoT (millions d'événements/s), gaming (profils joueurs globaux), e-commerce (catalogue produits variable), applications mobiles mondiales, graphes (social network). SQL Database pour : ERP, CRM, applications financières transactionnelles. Cosmos DB garantit < 10ms pour read/write via SLA, une rareté dans les bases de données."},
  {t:"DevOps",q:"Quelle est la différence entre Azure DevOps et GitHub dans l'écosystème Microsoft ?",o:["Ce sont des services identiques","Azure DevOps (anciennement VSTS) : suite complète CI/CD entreprise (Boards, Repos, Pipelines, Test Plans, Artifacts), idéal pour les grandes entreprises avec des processus établis; GitHub : plateforme de développement centrée sur Git et la communauté open-source, GitHub Actions pour CI/CD, GitHub Copilot pour l'IA — Microsoft possède les deux depuis 2018","GitHub est gratuit, DevOps est payant","Azure DevOps ne supporte pas Git"],a:1,e:"Microsoft possède les deux. Azure DevOps : entreprise, processus complexes, intégration Azure native, Azure Boards pour project management. GitHub : monde open-source, GitHub Actions (très populaire), GitHub Packages, Codespaces, Copilot. Tendance : migration vers GitHub Actions pour CI/CD, GitHub Copilot pour productivité développeur. Azure DevOps reste pertinent pour les grandes entreprises."},
  {t:"DevOps",q:"Qu'est-ce que l'Infrastructure as Code (IaC) et quels sont les outils Azure pour l'implémenter ?",o:["Coder l'infrastructure physique","Gérer et provisionner l'infrastructure via des fichiers de configuration versionables (comme du code) plutôt que des interfaces manuelles — outils Azure : ARM Templates (JSON natif Azure), Bicep (DSL simplifié Azure, transpile en ARM), Terraform (multi-cloud, HashiCorp), Ansible (configuration management)","Utiliser uniquement le portail Azure","Coder uniquement les VMs"],a:1,e:"IaC permet la reproductibilité, la version control (Git), les révisions de code, et l'automatisation. Bicep est le langage IaC recommandé par Microsoft : syntaxe concise, déclaratif, transpile en ARM, support natif dans VS Code. Terraform est l'alternative multi-cloud si l'entreprise gère aussi AWS/GCP. ARM Templates = plus verbeux mais natif."},
  {t:"Conformité",q:"Qu'est-ce que la résidence des données (data residency) dans Azure et pourquoi est-ce important ?",o:["La vitesse de transfert des données","La garantie qu'Azure stocke les données client dans des régions géographiques spécifiques (ex: toutes les données restent en France/Europe) pour satisfaire aux exigences légales comme le RGPD, la souveraineté numérique, et les réglementations sectorielles (banque, santé)","Le chiffrement des données","La réplication des données"],a:1,e:"La résidence des données est critique pour la conformité : le RGPD exige que les données des citoyens UE restent en UE (ou pays adéquat). Azure permet de choisir la région de déploiement et garantit que les données primaires restent dans la région choisie. Les Sovereign Clouds (Azure Government, Azure China) offrent des garanties renforcées pour les gouvernements."},
  {t:"Conformité",q:"Qu'est-ce que le Microsoft Trust Center ?",o:["Un datacenter physique Microsoft","Le portail central où Microsoft documente son engagement envers la sécurité, la conformité, la confidentialité et la transparence — incluant les certifications de conformité (ISO 27001, SOC 2, PCI-DSS), les politiques de protection des données, les réponses aux demandes gouvernementales et les meilleures pratiques","Un outil de gestion des coûts","Un service d'authentification"],a:1,e:"Microsoft Trust Center (microsoft.com/trust-center) : hub d'information sur les engagements Microsoft. Sécurité : comment les datacenters sont protégés. Conformité : plus de 90 certifications. Confidentialité : comment Microsoft utilise les données client. Service Trust Portal (servicetrust.microsoft.com) : documents téléchargeables (rapports audit, DPA)."},
  {t:"Tarification",q:"Qu'est-ce que le plan Azure Free Account et quelles sont ses limites principales ?",o:["Un abonnement gratuit illimité","Un compte gratuit avec : 200$ de crédit Azure à utiliser en 30 jours, 55+ services gratuits pendant 12 mois (VM B1s Windows, VM B1s Linux, SQL Database S0, Blob Storage 5Go, etc.), et 40+ services Always Free (Functions 1M exec/mois, Azure Cosmos DB 25Go, Bandwidth 15Go/mois)","Un abonnement Enterprise gratuit","Un service uniquement pour les étudiants"],a:1,e:"Azure Free Account : 200$ crédit (30 jours, tous services), puis 12 mois de services populaires gratuits (ex: VM B1s = 1 vCore, 1 Go RAM), puis Always Free (Functions, Cosmos DB 25Go, etc.). Azure for Students : 100$ crédit sans carte bancaire. Dev/Test pricing : réductions pour abonnements MSDN/Visual Studio Enterprise."},
  {t:"Tarification",q:"Quelle est la différence entre le Azure Pricing Calculator et le TCO Calculator ?",o:["Ils font la même chose","Azure Pricing Calculator : estime le coût de services Azure spécifiques que vous prévoyez d'utiliser (configurez type VM, région, stockage → obtenez un coût mensuel estimé); TCO Calculator : compare le coût total on-premises (hardware+énergie+datacenter+RH) vs Azure pour justifier la migration","Pricing Calculator est réservé aux entreprises","TCO Calculator est gratuit, Pricing Calculator est payant"],a:1,e:"Pricing Calculator (azure.microsoft.com/pricing/calculator) : conception d'architecture et estimation de coûts Azure. TCO Calculator (azure.microsoft.com/pricing/tco) : business case pour migrer — saisir infrastructure on-prem actuelle, obtenir comparaison des coûts réels (incluant les coûts cachés on-prem comme l'électricité, le refroidissement, le personnel IT)."},
  {t:"Support",q:"Quels sont les niveaux de support Azure et leurs SLA de réponse pour les incidents critiques ?",o:["Un seul niveau de support universel","Basic (gratuit) : documentaiton+forums, pas de support technique; Developer (~30$/mois) : <8h email, non-production; Standard (~100$/mois) : <2h téléphone, production; Professional Direct (~1000$/mois) : <1h, proactive; Premier (sur devis) : <15min pour P1 critique, TAM dédié","Tous les plans ont le même SLA","Le support est inclus dans toutes les VMs"],a:1,e:"SLA réponse incident sévérité A (critique) : Developer (non supporté en prod), Standard <2h, Professional Direct <1h, Premier <15 min. La sévérité A = arrêt de production complet. Developer couvre dev/test uniquement. Pour la production, Standard minimum. Premier = grandes entreprises avec TAM (Technical Account Manager) dédié."},
  {t:"SLA",q:"Comment calculer le SLA composite de deux services Azure déployés en série (l'un dépend de l'autre) ?",o:["SLA = max(SLA1, SLA2)","SLA composite en série = SLA1 × SLA2 (multiplication). Ex: VM à 99,9% + SQL Database à 99,99% = 99,9% × 99,99% = 99,89%. La disponibilité totale est inférieure au SLA le plus faible car les deux doivent fonctionner simultanément","SLA = min(SLA1, SLA2)","SLA composite = (SLA1 + SLA2) / 2"],a:1,e:"Série : les deux doivent fonctionner → SLA = SLA1 × SLA2. Plus la chaîne est longue, plus la dispo baisse. Parallèle (redondance) : au moins un doit fonctionner → SLA = 1 - (1-SLA1) × (1-SLA2). Ex: deux VMs à 99,9% en parallèle = 1 - (0,001 × 0,001) = 99,9999%. L'architecture redondante améliore drastiquement la disponibilité."},
  {t:"Architecture",q:"Qu'est-ce que la géo-réplication dans Azure et quels services l'offrent ?",o:["Une réplication locale dans un datacenter","La réplication automatique des données dans une région Azure secondaire (généralement distante de centaines de km) pour la reprise après sinistre — offerte par : Azure SQL Database (géo-réplication active, 4 secondaires lisibles), Cosmos DB (multi-région natif), Azure Storage (GRS/GZRS), Azure Cache for Redis Premium","Une fonctionnalité réseau uniquement","La géo-réplication est manuelle dans Azure"],a:1,e:"Géo-réplication : réplication asynchrone (ou synchrone pour Cosmos DB) vers une autre région. En cas de panne régionale, failover vers la région secondaire. Azure SQL Database Geo-Replication : RPO < 5s, RTO < 30s. GRS Storage : RPO < 15min. Cosmos DB : failover automatique ou manuel selon config. Régions pairées Microsoft sont à plus de 300km pour les catastrophes régionales."},
  {t:"Architecture",q:"Quelle est la différence entre RTO et RPO dans le contexte de la reprise après sinistre Azure ?",o:["Ce sont des termes identiques","RTO (Recovery Time Objective) : temps maximum acceptable pour restaurer le service après une panne (ex: max 4h d'arrêt); RPO (Recovery Point Objective) : quantité maximale de données perdues acceptable (ex: max 1h de données perdues) — ces deux métriques guident le choix de la stratégie DR dans Azure","RTO = durée de la sauvegarde uniquement","RPO concerne uniquement la sécurité"],a:1,e:"RTO : 'Combien de temps peut-on être arrêté?' → détermine l'architecture (Azure Site Recovery pour RTO < 1h, geo-réplication active pour RTO < 5min). RPO : 'Combien de données peut-on perdre?' → détermine la fréquence de sauvegarde/réplication. Application financière critique : RTO=15min, RPO=0. Application interne non critique : RTO=24h, RPO=24h."}
];

window.QDATA[7] = [
  {t:"Révision finale",q:"Un examen AZ-900 vous demande : quelle est la principale caractéristique qui distingue le cloud public du cloud privé ?",o:["Le cloud public est moins sécurisé","Le cloud public est exploité par un fournisseur tiers (Microsoft Azure) et partagé entre plusieurs organisations via internet; le cloud privé est dédié à une seule organisation, exploité on-premises ou par un fournisseur hébergé, offrant plus de contrôle mais moins d'élasticité","Le cloud public est toujours moins cher","Le cloud public n'offre pas de SLA"],a:1,e:"Cloud public : infrastructures partagées multi-tenants, gérées par Azure/AWS/GCP, élasticité maximale, modèle OpEx. Cloud privé : infrastructure dédiée, plus de contrôle et conformité, CapEx ou coût fixe, moins élastique. Cloud hybride : combinaison des deux, données sensibles on-prem, charges élastiques dans le cloud public."},
  {t:"Révision finale",q:"Dans quel scénario recommanderiez-vous Azure Spot Virtual Machines ?",o:["Pour héberger une base de données de production critique","Pour des workloads tolérants aux interruptions comme le rendu 3D, le backtesting financier, les tests de charge, l'entraînement ML non critique — les Spot VMs utilisent la capacité Azure non utilisée à des prix jusqu'à 90% moins chers, mais peuvent être évictées avec 30s de préavis","Pour héberger un site e-commerce en production","Pour des VMs qui doivent tourner 24/7"],a:1,e:"Azure Spot VMs (équivalent AWS Spot Instances) : jusqu'à 90% moins cher que les tarifs on-demand. Microsoft peut reprendre la VM avec 30 secondes de préavis. Idéal pour : batch processing, CI/CD builds, entraînement ML, simulations, rendu. Inadaptés pour : production 24/7, bases de données, applications avec état."},
  {t:"Révision finale",q:"Qu'est-ce qu'un SLA de 99,9% signifie en termes de temps d'indisponibilité ?",o:["Zéro indisponibilité","Maximum 8,7 heures d'indisponibilité par an (0,1% de 8760h/an), soit environ 43,2 minutes par mois ou ~10 minutes par semaine","Maximum 1 heure par an","Maximum 1 heure par mois"],a:1,e:"Calcul : 0,1% × 365 jours × 24h = 8,76h/an. Comparaison des SLA Azure : 99,9% (8,7h/an), 99,95% (4,4h/an), 99,99% (52 min/an), 99,999% (5 min/an — five nines). Une VM Azure seule offre 99,9%. VMs en Availability Zones → 99,99%. Pour 99,999%, il faut une architecture active-active multi-région."},
  {t:"Révision finale",q:"Azure Resource Manager (ARM) est-il un service ou une couche d'infrastructure ?",o:["C'est un service payant","C'est la couche de gestion (management plane) d'Azure que tous les outils utilisent — Portail Azure, Azure CLI, PowerShell, SDKs et REST API envoient tous leurs requêtes à ARM qui gère l'authentification (Entra ID), l'autorisation (RBAC), le déploiement et la gestion des ressources Azure","C'est uniquement un outil de déploiement","C'est un service de monitoring"],a:1,e:"ARM est l'infrastructure de contrôle d'Azure : toutes les opérations (créer VM, créer policy, assigner rôle) passent par ARM. Bénéfices : cohérence entre outils, templates ARM pour IaC, tags sur toutes les ressources, RBAC uniforme, déploiements atomiques (tout ou rien), historique des déploiements, pre-flight validation."},
  {t:"Révision finale",q:"Une entreprise veut que ses développeurs déploient uniquement des ressources conformes aux politiques de sécurité (ex: pas de ressources sans chiffrement). Quelle est l'approche Azure recommandée ?",o:["Former les développeurs manuellement","Créer une Azure Policy avec l'effet 'Deny' pour les ressources non chiffrées + une Azure Policy Initiative regroupant toutes les politiques de conformité, assignée au Management Group — les déploiements non conformes sont automatiquement bloqués à la soumission ARM","Utiliser RBAC uniquement","Auditer manuellement après déploiement"],a:1,e:"Azure Policy avec effet Deny : la politique est vérifiée par ARM avant chaque déploiement. Si une ressource ne satisfait pas la condition (ex: Blob sans chiffrement), le déploiement est refusé. Policy Initiative = regroupement de politiques (ex: initiative 'CIS Azure Foundations Benchmark' avec 100+ politiques). Plus efficace qu'une formation manuelle."},
  {t:"Révision finale",q:"Quel service Azure permet de créer une architecture serverless de traitement d'événements IoT en temps réel ?",o:["Azure VMs + SQL Database","Azure IoT Hub (ingestion des données IoT) → Azure Event Hub (streaming) → Azure Stream Analytics (traitement temps réel SQL) → Azure Functions (traitement événements) → Azure Cosmos DB (stockage) — architecture serverless complète","Azure Blob Storage uniquement","Azure App Service"],a:1,e:"Architecture IoT serverless Azure : IoT Hub reçoit les données des appareils (millions/s), Event Hub pour le streaming, Stream Analytics pour les requêtes SQL en temps réel (détection d'anomalies), Functions pour le traitement événementiel, Cosmos DB pour le stockage basse latence. Zéro serveur à gérer, scaling automatique."},
  {t:"Révision finale",q:"Quelle est la différence entre une ressource 'Preview' et 'Generally Available (GA)' dans Azure ?",o:["Il n'y a aucune différence","Preview : service en cours de test/validation, peut être modifié ou retiré sans préavis, exclu des SLA Azure, tarification peut être réduite ou gratuite — ne pas utiliser en production critique; GA (Generally Available) : service stable, couvert par SLA, support complet, engagement Microsoft sur la durabilité","Preview est plus stable que GA","GA est gratuit, Preview est payant"],a:1,e:"Preview = Beta Azure : fonctionnalités nouvelles en test public. Private Preview (invitation), Public Preview (tous peuvent tester). Pas de SLA, pas de garantie de disponibilité, peut changer. GA = production-ready : SLA contractuel, support Microsoft standard, facturation normale, Microsoft s'engage à maintenir. Règle : jamais de Preview en production critique."},
  {t:"Révision finale",q:"Comment fonctionne la facturation Azure pour les services PaaS comme Azure App Service ?",o:["Facturation uniquement à l'utilisation CPU","Facturation basée sur le plan App Service choisi (Free F1, Shared, Basic B1-B3, Standard S1-S3, Premium P1-P3) — le plan détermine CPU/RAM/stockage/fonctionnalités disponibles; on peut héberger plusieurs apps sur un même plan et ne payer que le plan, pas par app","Facturation par nombre de requêtes HTTP","Facturation uniquement au déploiement"],a:1,e:"App Service Plan = unité de facturation. B1 (1 vCore, 1,75 Go RAM) ~55$/mois, peu importe le nombre d'apps déployées dessus. Free et Shared sont limités (pas de domaines custom, pas d'IP dédiée). Standard+ : auto-scaling, staging slots, trafic SSL. Pour serverless → Functions plan Consommation (payer par exécution)."},
  {t:"Révision finale",q:"Qu'est-ce que la fonctionnalité 'Azure Reservation Exchange' ?",o:["Un service d'échange de données","La possibilité d'échanger une Reservation existante contre une nouvelle (changer la taille VM, la région ou le service) avant la fin de son terme, permettant de s'adapter à l'évolution des besoins sans perdre la valeur d'engagement initial","Un service de conversion de devises","Un service d'échange de ressources entre abonnements"],a:1,e:"Azure Reservations Exchange : si une VM réservée est remplacée par une taille différente ou que la charge migre vers une autre région, on peut échanger la réservation existante contre une nouvelle sans pénalité (avant fin 2025, avec nouvelles règles après). Reservation Cancellation : remboursement partiel possible (12,000$/an max). Réservations : engagement 1 an ou 3 ans."},
  {t:"Révision finale",q:"Quand une entreprise devrait-elle choisir Azure Government Cloud plutôt que le cloud Azure commercial ?",o:["Pour économiser de l'argent","Quand il s'agit d'agences gouvernementales américaines ou de leurs contractants qui traitent des données soumises à des réglementations comme FedRAMP, ITAR, DoD SRG, CJIS ou IRS 1075 — Azure Government offre une infrastructure physiquement séparée, opérée uniquement par des citoyens américains vérifiés","Pour toutes les entreprises","Pour les startups uniquement"],a:1,e:"Azure Government : datacenters aux États-Unis uniquement, opérés par du personnel américain avec vérification d'antécédents, certifications gouvernementales (FedRAMP High, DoD IL2/IL4/IL5, CJIS). Séparation physique d'Azure commercial. Équivalent: Azure Germany (Treuhänder), Azure China (21Vianet). Conçu pour satisfaire les réglementations de sécurité les plus strictes du gouvernement américain."},
  {t:"Révision finale",q:"Qu'est-ce que Azure Managed Disks et quels sont les types disponibles ?",o:["Des disques gérés manuellement","Des disques de stockage Azure pour les VMs, gérés par Microsoft (réplication, chiffrement automatique) — types : Ultra Disk (NVMe, latence < 1ms, IOPS illimitées pour bases de données critiques), Premium SSD v2, Premium SSD (production standard), Standard SSD (dev/test léger), Standard HDD (archivage, faible coût)","Des disques réseau uniquement","Un type de Blob Storage"],a:1,e:"Managed Disks simplifient la gestion : Microsoft gère la réplication sous-jacente, le chiffrement par défaut (SSE avec clés Microsoft ou client), les snapshots. Ultra Disk : latence < 1ms, IOPS configurable, pour SQL Server en production, SAP HANA. Premium SSD : IOPS et latence stables, standard pour VMs de production. Standard SSD : OK pour dev, web, peu d'IOPS. HDD : archivage uniquement."},
  {t:"Révision finale",q:"Comment Azure gère-t-il la mise à jour des VMs tout en maintenant la disponibilité ?",o:["Azure arrête toutes les VMs en même temps pour les mises à jour","Via les Update Domains dans les Availability Sets : les VMs dans des Update Domains différents ne sont pas redémarrées simultanément lors des maintenances Azure — un seul Update Domain est restarté à la fois, garantissant qu'au moins 4/5 des VMs restent disponibles pendant une mise à jour","Azure n'effectue pas de mises à jour","Les mises à jour sont toujours instantanées"],a:1,e:"Availability Set avec Update Domains (UD) : 5 UDs par défaut (configurable jusqu'à 20). Lors d'une maintenance Azure planifiée, Azure ne redémarre qu'un UD à la fois. Combiné aux Fault Domains (différents racks physiques), l'Availability Set protège contre les pannes matérielles ET les maintenances. Maintenant, les AZs (Availability Zones) offrent une meilleure protection."},
  {t:"Révision finale",q:"Qu'est-ce que Azure Cost Anomaly Detection ?",o:["Un service de détection d'intrusion","Une fonctionnalité d'Azure Cost Management qui utilise le machine learning pour détecter automatiquement les pics de coûts anormaux par rapport aux patterns historiques et envoie des alertes par email, permettant de réagir rapidement avant que la facture mensuelle ne soit trop élevée","Un service de monitoring des performances","Un service de sécurité des réseaux"],a:1,e:"Cost Anomaly Detection dans Azure Cost Management : ML détecte les dépenses anormales (ex: une VM oubliée tourne en boucle, une erreur de configuration crée des milliers de ressources). Alertes email automatiques au propriétaire de l'abonnement. Complète les Budget Alerts (alertes quand le budget est atteint). Essentiel pour éviter les 'bill shock'."},
  {t:"Révision finale",q:"Quel est le rôle du service Azure Front Door dans une architecture globale ?",o:["Un service de stockage global","Un CDN et load balancer global de Couche 7 qui : route le trafic vers le datacenter Azure le plus proche de l'utilisateur (Anycast), offre un WAF global, l'accélération SSL, le caching des contenus statiques, et le failover automatique entre régions — pour les applications web mondiales à très faible latence","Un service VPN","Un service de base de données global"],a:1,e:"Azure Front Door est le point d'entrée global pour les applications web : Anycast (le DNS pointe vers 150+ POPs mondiaux → trafic routé vers la région la plus proche), SSL offloading, WAF (OWASP), caching de contenus statiques, routing basé sur la latence ou la géographie, health probes pour failover automatique. Traffic Manager = DNS L4, Front Door = L7 HTTP/HTTPS avec accélération."},
  {t:"Révision finale",q:"Qu'est-ce que la fonctionnalité 'Azure Autoscale' et comment la configurer ?",o:["Une mise à l'échelle uniquement manuelle","Autoscale ajuste automatiquement le nombre d'instances (VMs dans Scale Sets, App Service instances, etc.) basé sur des règles : métriques (CPU > 70% → +1 instance), planification (scale out à 9h, scale in à 18h), ou les deux — configurable dans Azure Monitor avec des limites min/max","Une fonctionnalité uniquement disponible pour AKS","Autoscale est un service payant supplémentaire"],a:1,e:"Azure Autoscale dans Azure Monitor : scale-out (ajouter instances) et scale-in (supprimer instances). Règles métriques : CPU%, mémoire, longueur de queue (Service Bus), requêtes HTTP. Planification : scale-out le lundi matin, scale-in le vendredi soir. Limites : min instances (jamais en dessous), max instances (jamais au-dessus), default (si métriques indisponibles). Cooldown period évite le thrashing."},
  {t:"Révision finale",q:"Dans Azure, comment partager des ressources (images de VM, blueprints) entre plusieurs abonnements d'une même organisation ?",o:["Copier manuellement dans chaque abonnement","Via Azure Compute Gallery (anciennement Shared Image Gallery) pour partager des images VM personnalisées, Azure Blueprints pour les configurations d'environnement, et les Management Groups + Azure Policy pour appliquer des contrôles — ces services permettent la gouvernance et le partage au niveau organisationnel","Recréer les ressources dans chaque abonnement","Via le portail Azure uniquement"],a:1,e:"Azure Compute Gallery (images VM customisées), Azure Blueprints (templates d'environnement = policies + RBAC + ARM templates), Management Groups (hiérarchie organisationnelle pour policy/RBAC). Un Blueprint peut déployer automatiquement un environnement conforme (ex: LZ Landing Zone avec VNet, NSGs, policies) dans n'importe quel abonnement enfant."},
  {t:"Révision finale",q:"Quel est l'impact de l'activation d'Azure Defender for SQL sur les performances de la base de données ?",o:["Impact critique, les bases de données ralentissent de 50%","Impact minimal — Defender for SQL est un service de sécurité externe qui analyse les logs et la configuration, pas un agent dans le moteur SQL; il détecte les menaces (injections SQL, accès anormal) et les vulnérabilités (configurations non sécurisées) sans modifier le moteur SQL","Aucune fonctionnalité de sécurité n'est ajoutée","Impact uniquement sur le réseau"],a:1,e:"Microsoft Defender for SQL (composant de Defender for Cloud) : analyse les activités SQL via les logs d'audit Azure SQL (pas un agent dans le moteur), identifie les patterns d'attaque (SQL injection, brute force, lateral movement), scanne les configurations pour les vulnérabilités. L'impact performance est minimal. Coût : ~15$/serveur/mois."},
  {t:"Révision finale",q:"Qu'est-ce que le modèle de responsabilité partagée pour Azure SQL Database (PaaS) ?",o:["Microsoft est responsable de tout","Microsoft gère : infrastructure physique, OS, patches du moteur SQL, haute disponibilité, sauvegardes automatiques; Le client gère : données, schéma de base de données, utilisateurs/permissions SQL, configuration des connexions, classification des données","Le client gère tout","La responsabilité est 50/50 mais indéfinie"],a:1,e:"PaaS Azure SQL : Microsoft gère tout jusqu'au moteur de base de données. Le client gère ce qui est dans la base de données (données, schéma, requêtes, accès). Comparaison : IaaS SQL Server sur VM → le client gère aussi OS, patches SQL Server, configuration HA. SaaS → Microsoft gère tout. Plus on monte vers SaaS, plus Microsoft prend de responsabilités."},
  {t:"Révision finale",q:"Une application Azure rencontre des problèmes de performance intermittents. Quelle est la bonne séquence d'investigation avec les outils Azure ?",o:["Appeler le support Microsoft directement","1) Azure Monitor Metrics pour les métriques ressources (CPU, mémoire, latence) en temps réel, 2) Application Insights pour les traces applicatives et les dépendances lentes, 3) Azure Log Analytics pour des requêtes KQL avancées sur les logs, 4) Azure Advisor pour les recommandations d'optimisation, 5) Azure Service Health pour vérifier les incidents Azure","Redémarrer toutes les VMs","Augmenter la taille des VMs immédiatement"],a:1,e:"Séquence d'investigation : Monitor Metrics (vue rapide CPU/mémoire/réseau → identifier la ressource en cause), Application Insights (où dans l'application ? SQL lent, appel externe lent ?), Log Analytics KQL (patterns, corrélation temporelle), Advisor (recommandations long terme), Service Health (incident Azure ?). Diagnostiquer avant d'agir évite les coûts inutiles."},
  {t:"Révision finale",q:"Qu'est-ce que le concept de 'Landing Zone' dans Azure ?",o:["Une zone d'atterrissage pour les hélicoptères","Un environnement Azure pré-configuré et gouverné suivant les meilleures pratiques du Cloud Adoption Framework (CAF) — avec réseau hub-spoke, politiques de conformité, accès RBAC, monitoring, sécurité et connectivité configurés dès le départ pour accueillir des workloads de production","Un type de région Azure","Une zone de disponibilité"],a:1,e:"Azure Landing Zone = socle Azure clé en main : Management Groups (hiérarchie), Abonnements segmentés (Platform, Landing Zones, Sandbox), réseau Hub-Spoke (VNet hub partagé, VNets spoke par workload), Azure Policy (conformité), Azure Monitor (logging centralisé), Defender for Cloud. Accélérateurs Landing Zone disponibles sur GitHub pour déploiement en quelques heures."},
  {t:"Récap AZ-900",q:"AZ-900 récapitulatif : quel domaine représente le plus grand pourcentage de l'examen AZ-900 ?",o:["Services Azure principaux (35-40%)","Gestion et gouvernance Azure (35-40%) — récent changement du programme : la gouvernance, la conformité, la gestion des coûts et le support représentent maintenant la plus grande part de l'examen AZ-900","Concepts du cloud (25-30%)","Sécurité uniquement (10-15%)"],a:1,e:"Répartition AZ-900 (2024-2025) : Gestion et gouvernance Azure 35-40% (Cost Management, Azure Policy, RBAC, Tags, blueprints, compliance, monitoring), Services Azure 35-40% (Compute, Réseau, Stockage, Identity, Security), Concepts Cloud 20-25% (cloud models, IaaS/PaaS/SaaS, CapEx/OpEx, availability). Priorité d'étude : gouvernance + services Azure."},
  {t:"Récap AZ-900",q:"Pour réussir l'examen AZ-900, quel score minimum est requis et combien de questions comporte-t-il ?",o:["60% minimum, 100 questions","700/1000 points minimum (soit environ 70%), environ 40-60 questions de types variés (QCM, cas pratiques, glisser-déposer, ordonnancement) — durée : 65 minutes, disponible en présentiel et en ligne (surveillé)","80% minimum, 200 questions","50% minimum, 30 questions"],a:1,e:"AZ-900 : score 700/1000 pour réussir. ~40-60 questions (le nombre exact varie). Types : QCM (most frequent), case studies, drag-and-drop, true/false, ordering. Durée : 65 minutes. Disponible : Pearson VUE en centre ou online proctored. Validité : 2 ans (renouvellement gratuit via Microsoft Learn). Prix : environ 165€. Recommandé comme première certification Azure."},
  {t:"Récap AZ-900",q:"Laquelle de ces affirmations sur Azure est correcte ?",o:["Azure ne propose que des services IaaS","Azure est une plateforme cloud complète proposant IaaS (VMs, réseaux, stockage), PaaS (App Service, Azure SQL, AKS, Functions), SaaS (Microsoft 365 via Entra ID), et des services spécialisés (AI, IoT, analytics) avec plus de 200 services disponibles","Azure ne propose que des services dans 5 régions mondiales","Azure ne propose pas de services de base de données"],a:1,e:"Azure est la plateforme cloud de Microsoft couvrant tous les modèles de service (IaaS, PaaS, SaaS, FaaS) et segments : compute, stockage, réseau, base de données, IA/ML, DevOps, IoT, analytics, sécurité, gouvernance. Plus de 60 régions mondiales, plus de 200 services. Deuxième plus grand fournisseur cloud mondial après AWS (2024)."},
  {t:"Récap AZ-900",q:"Comment les services Azure sont-ils organisés hiérarchiquement pour la gestion ?",o:["Toutes les ressources sont au même niveau sans hiérarchie","Hiérarchie Azure de haut en bas : Management Groups (gouvernance multi-abonnement) → Abonnements (unité de facturation et de gouvernance) → Resource Groups (regroupement logique de ressources liées) → Ressources individuelles (VM, SQL, VNet). Les politiques et RBAC appliqués en haut héritent vers le bas","Les ressources sont organisées par région uniquement","Les abonnements sont le seul niveau de gestion"],a:1,e:"La hiérarchie Azure est clé pour l'AZ-900 : Tenant Entra ID > Management Groups (jusqu'à 6 niveaux) > Abonnements > Resource Groups > Ressources. Chaque niveau hérite des politiques et RBAC du niveau parent. Un Resource Group doit exister dans une région (pour les métadonnées) mais peut contenir des ressources de n'importe quelle région."}
];

// Supplément Jour 1 — 20 questions supplémentaires pour atteindre 50
window.QDATA[1].push(
  {t:"Concepts Cloud",q:"Qu'est-ce que la 'consommation basée sur l'utilisation' (consumption-based model) dans Azure ?",o:["Un abonnement à tarif fixe mensuel","Un modèle où vous ne payez que pour ce que vous utilisez réellement (heures CPU, Go de stockage, Go de données transférées) — si vous n'utilisez pas de ressources, vous ne payez rien; à l'opposé du modèle CapEx fixe","Un abonnement annuel prépayé","Un modèle de location de matériel"],a:1,e:"Le modèle de consommation Azure : OpEx pur basé sur l'usage réel. Une VM arrêtée (deallocated) ne coûte que son stockage. Azure Functions plan Consommation : facturation à la milliseconde d'exécution. Opposé au datacenter on-premises : vous payez les serveurs même inutilisés. Ce modèle permet d'aligner les coûts IT avec l'activité business réelle."},
  {t:"Concepts Cloud",q:"Quel avantage cloud décrit le fait qu'Azure surveille automatiquement la santé des ressources et remplace les VMs défaillantes ?",o:["La scalabilité","La fiabilité (reliability) — Azure surveille en permanence l'infrastructure et peut automatiquement migrer une VM vers un hôte sain en cas de défaillance matérielle, maintenant la disponibilité sans intervention humaine","La sécurité","L'élasticité"],a:1,e:"La fiabilité cloud va au-delà de la simple haute disponibilité : Azure Live Migration déplace les VMs en cours d'exécution vers des hôtes sains avant une maintenance ou lors d'une défaillance. Les Service Health notifications prévenient des maintenances planifiées. Azure Backup et Site Recovery complètent la stratégie de fiabilité."},
  {t:"Concepts Cloud",q:"Une startup attend une croissance de 500% de ses utilisateurs en 6 mois mais n'est pas sûre du timing. Quel avantage cloud est le plus critique ?",o:["La sécurité","L'agilité cloud — capacité à provisionner de nouvelles ressources en quelques minutes pour supporter la croissance, puis à les supprimer si la croissance est plus lente que prévu, sans engagement en capital, adaptant l'infrastructure au besoin réel","La conformité","La haute disponibilité"],a:1,e:"L'agilité est clé pour les startups : Azure permet de doubler la capacité en quelques clics ou via du code (Terraform, Bicep). Si la croissance est en retard, on peut réduire les ressources et économiser. Avec du matériel physique, un surcapacité = coûts fixes inutiles; une sous-capacité = perte de revenus. Le cloud élimine ce dilemme."},
  {t:"Modèles Cloud",q:"Quelle est la différence entre la scalabilité et l'élasticité dans le contexte Azure ?",o:["Ces termes sont synonymes","Scalabilité : capacité à augmenter les ressources (scale up = plus grande VM; scale out = plus d'instances); Élasticité : scalabilité automatique et bidirectionnelle — Azure Autoscale ajoute des ressources quand la charge augmente ET les retire quand elle diminue, optimisant automatiquement les coûts","Scalabilité ne s'applique qu'aux bases de données","L'élasticité est uniquement pour le stockage"],a:1,e:"Scalabilité = capacité à grandir. Élasticité = scalabilité automatique et dans les deux sens. Azure Autoscale (pour VMs Scale Sets, App Service, AKS) implémente l'élasticité : règles basées sur CPU, requêtes HTTP, longueur de queue. Scale in automatique = économies la nuit/weekend. Les deux sont des avantages fondamentaux du cloud."},
  {t:"Modèles Cloud",q:"Dans quel cas de figure le cloud privé est-il préférable au cloud public Azure ?",o:["Le cloud privé est toujours préférable","Quand une organisation a des exigences réglementaires très strictes imposant un contrôle physique total des données (ex: certaines agences gouvernementales classifiées), ou quand les investissements existants en datacenter sont entièrement amortis et les charges de travail sont stables et prévisibles — sinon, les avantages du cloud public l'emportent généralement","Le cloud privé est toujours moins cher","Le cloud privé offre plus de scalabilité"],a:1,e:"Cloud privé avantageux : conformité stricte exigeant isolation physique totale, données ultra-sensibles (renseignement), investissement existant déjà amorti, charges de travail 100% stables (pas d'élasticité nécessaire). Dans la plupart des autres cas, le cloud public ou hybride offre plus de valeur. Azure Sovereign Clouds (Government) comblent souvent l'écart pour les organismes publics."},
  {t:"IaaS",q:"Quelle est la principale différence entre Azure Virtual Machines (IaaS) et Azure App Service (PaaS) pour héberger une application web ?",o:["Il n'y a aucune différence","VMs (IaaS) : contrôle total sur l'OS, les logiciels, la configuration réseau — vous gérez OS, patches, runtime, scaling manuel; App Service (PaaS) : vous déployez le code uniquement — Azure gère l'OS, le runtime (.NET, Node, Python), les patches, le scaling automatique, la HA — moins de contrôle mais moins de gestion","App Service coûte toujours plus cher","Les VMs sont toujours plus performantes"],a:1,e:"Choix IaaS vs PaaS : VMs si vous avez besoin de logiciels spécifiques non supportés par App Service, d'un OS particulier, ou de configurations réseau complexes (Windows Services, COM objects). App Service si vous voulez vous concentrer sur le code sans gérer l'infrastructure. 90% des applications web standard conviennent à App Service."},
  {t:"IaaS",q:"Pourquoi les mises à jour de sécurité OS sont-elles la responsabilité du client dans un modèle IaaS Azure ?",o:["Azure gère toutes les mises à jour dans tous les modèles","Dans le modèle IaaS, le client loue l'infrastructure (hyperviseur, réseau physique) mais gère le système d'exploitation et tout ce qui est au-dessus — les patchs OS (Windows Update, yum/apt) restent la responsabilité du client car il a le contrôle total de la VM, y compris quand et comment appliquer les mises à jour","Les mises à jour sont automatiques dans IaaS","Azure Update Management gère automatiquement tout"],a:1,e:"IaaS : Azure gère jusqu'à l'hyperviseur. Le client gère l'OS et tout ce qui est dessus. Azure Update Management peut aider à automatiser les patchs Windows/Linux mais c'est toujours la responsabilité du client de le configurer et de valider les patchs. En PaaS, Microsoft gère les patchs OS automatiquement."},
  {t:"CapEx vs OpEx",q:"Une entreprise veut acheter un serveur on-premises pour 50 000€ et l'amortir sur 5 ans. Quelle est la nature de cette dépense et quel est l'équivalent Azure ?",o:["C'est une dépense OpEx","C'est une dépense CapEx (Capital Expenditure) — investissement initial en actif immobilisé amorti sur plusieurs années, impactant le bilan; l'équivalent Azure serait des VMs facturées mensuellement en OpEx (Operational Expenditure), déduites immédiatement du résultat sans amortissement","C'est une dépense variable","Ce n'est ni CapEx ni OpEx"],a:1,e:"CapEx : achat de serveur 50K€ → actif immobilisé, amorti 10K€/an sur 5 ans. OpEx Azure : 1K€/mois de VMs → charge mensuelle déductible immédiatement. Avantage fiscal de l'OpEx : déduction immédiate vs amortissement étalé. Avantage business : flexibilité, pas d'immobilisation de trésorerie, pas de risque d'obsolescence."},
  {t:"CapEx vs OpEx",q:"Une PME hésite entre acheter des serveurs pour son datacenter (scénario A) ou passer à Azure (scénario B). Quel scénario correspond à un modèle CapEx et lequel à OpEx ?",o:["Scénario A = OpEx, Scénario B = CapEx","Scénario A (achat serveurs) = CapEx : investissement initial, amortissement sur 3-5 ans, coûts fixes même si sous-utilisé; Scénario B (Azure) = OpEx : paiement mensuel basé sur l'usage, pas d'immobilisation, flexibilité totale","Les deux sont CapEx","Les deux sont OpEx"],a:1,e:"CapEx : dépense d'investissement initiale pour un actif physique durable. OpEx : dépense opérationnelle récurrente pour services/ressources consommés. Azure = OpEx pur : paiement à la consommation, aucun actif à amortir. Conséquence comptable : CapEx impacte le bilan (actif), OpEx impacte le compte de résultat (charges). Pour beaucoup de CFOs, l'OpEx cloud est préférable à l'immobilisation CapEx."},
  {t:"Responsabilité partagée",q:"Dans un modèle SaaS comme Microsoft 365, qu'est-ce que le client gère encore ?",o:["Le client ne gère absolument rien","Le client gère : les comptes utilisateurs et leurs licences, la configuration des applications (ex: règles DLP, politiques Exchange), les données qu'il stocke dans le service, les autorisations d'accès — Microsoft gère tout le reste (infrastructure, application, sécurité physique, disponibilité)","Le client gère l'OS et l'application","Le client gère les sauvegardes de données"],a:1,e:"Même en SaaS, le client garde des responsabilités : gestion des identités (créer/supprimer comptes, attribuer licences), configuration des services (règles email, politiques partage SharePoint), protection des données (classification, DLP), et conformité de l'usage (s'assurer que les employés utilisent le service correctement). Microsoft gère tout le reste."},
  {t:"Avantages Cloud",q:"Qu'est-ce que la 'prédictibilité' comme avantage du cloud Azure ?",o:["La capacité à prédire les pannes","La capacité à prévoir les coûts et les performances : Azure Cost Management avec des budgets et alertes permet de prévoir et contrôler les dépenses; les SLA Azure garantissent des niveaux de performance (latence, disponibilité) prévisibles, permettant aux équipes de planifier les besoins IT avec confiance","La prédiction du trafic réseau","La prédiction des menaces de sécurité uniquement"],a:1,e:"Prédictibilité cloud : 1) Coûts prévisibles (budgets Azure, Cost Management, Pricing Calculator — estimer avant de déployer), 2) Performance prévisible (SLA contractuels sur disponibilité et latence), 3) Capacité prévisible (scaling automatique = jamais de saturation surprenante). Opposé au datacenter on-prem : pics de charge imprévus = dégradation de service."},
  {t:"Avantages Cloud",q:"Comment le cloud Azure améliore-t-il la 'gouvernance' par rapport à un datacenter traditionnel ?",o:["La gouvernance est plus difficile dans Azure","Azure offre une gouvernance centralisée et automatisée via : Azure Policy (enforcement automatique des règles), RBAC (contrôle d'accès basé sur les rôles), Management Groups (hiérarchie de gestion), Tags (organisation et suivi des coûts), Azure Monitor (audit et logging) — bien plus difficile à réaliser dans un environnement physique distribué","La gouvernance est identique","La gouvernance cloud est optionnelle"],a:1,e:"Gouvernance Azure : tout est en code (Policy as Code, IaC), auditable (Activity Logs, Azure Monitor), enforçable automatiquement (Policy Deny). On-premises : gouvernance = règles manuelles, audits périodiques, conformité non automatisée. Azure permet la conformité continue et automatique plutôt que la conformité périodique et manuelle."},
  {t:"Avantages Cloud",q:"Qu'est-ce que la 'manageabilité' dans le contexte des avantages cloud Azure ?",o:["La capacité à gérer les équipes RH","La facilité de gestion de l'environnement cloud : via le portail web Azure (interface graphique), Azure CLI et PowerShell (scripts d'automatisation), APIs REST (intégration dans des outils existants), templates ARM/Bicep (IaC), et Azure Mobile App (gestion depuis son téléphone) — plusieurs façons standardisées de gérer toutes les ressources","La gestion des licences uniquement","La manageabilité est un terme uniquement marketing"],a:1,e:"Manageabilité Azure : interface unifiée pour tous les services (portail, CLI, PowerShell, SDK). On-prem : chaque serveur/équipement a ses propres outils de gestion. Azure permet de gérer 1 000 VMs aussi facilement qu'une seule (via des scripts, ARM templates, Azure Automation). Azure Mobile App : surveiller et redémarrer des ressources depuis son smartphone."},
  {t:"Modèles Cloud",q:"Une entreprise financière veut profiter de l'élasticité du cloud pour ses calculs de risque (très variables) mais doit garder ses données client dans son propre datacenter (conformité). Quel modèle cloud recommandez-vous ?",o:["Cloud public uniquement","Cloud hybride — les calculs élastiques s'exécutent dans Azure (burst cloud), les données sensibles restent on-premises, une connexion ExpressRoute ou VPN sécurisée assure la communication — combine contrôle/conformité du cloud privé et élasticité/coûts du cloud public","Cloud privé uniquement","Cloud communautaire"],a:1,e:"Hybride cloud pour ce cas : données client on-premises (conformité bancaire), calculs de risque sur Azure (élasticité, GPU si ML). Connexion ExpressRoute pour la sécurité et latence. Pattern 'cloud bursting' : capacité de base on-prem, pics dans Azure. Azure Arc permet de gérer l'ensemble avec les mêmes outils Azure."},
  {t:"Modèles Service",q:"Un CTO demande : 'Qui est responsable de la disponibilité du service en IaaS, PaaS et SaaS ?' Comment répondre correctement ?",o:["Le client est toujours 100% responsable","IaaS : responsabilité partagée — Azure garantit la disponibilité de l'infrastructure (SLA hyperviseur), le client est responsable de la HA de son application (configuration redondante, Load Balancer); PaaS : Azure garantit la disponibilité du service (SLA App Service 99,95%), le client doit concevoir son app pour être tolérante aux pannes; SaaS : Azure garantit la disponibilité (SLA Microsoft 365 99,9%)","Azure est toujours 100% responsable","La responsabilité est toujours 50/50"],a:1,e:"La responsabilité de la disponibilité se déplace vers Microsoft selon le modèle : IaaS (client gère la HA applicative), PaaS (Microsoft garantit la plateforme, client gère l'app), SaaS (Microsoft garantit tout le service). En IaaS, une VM sans Load Balancer ni Availability Set n'a pas de SLA de disponibilité pour l'application, même si l'hyperviseur est garanti à 99,9%."},
  {t:"Modèles Service",q:"Azure Kubernetes Service (AKS) est-il classé IaaS, PaaS, ou quelque chose d'autre ?",o:["IaaS pur","AKS est considéré comme PaaS (ou CaaS — Container as a Service) : Microsoft gère le plan de contrôle Kubernetes (API Server, etcd, scheduler) gratuitement, le client gère uniquement les node pools (VMs qui tournent les containers) et les applications deployées","SaaS uniquement","AKS n'est pas classifiable"],a:1,e:"AKS = CaaS (Container as a Service), souvent considéré PaaS : le control plane K8s est entièrement géré par Azure (mises à jour, HA, sécurité) et gratuit. Le client gère ses node pools (types de VMs, nombre de nœuds), ses workloads (deployments, services, ingress). Simplifie énormément K8s self-hosted. Azure gère aussi l'intégration avec ACR, Key Vault, Monitor, AAD."},
  {t:"Concepts Cloud",q:"Qu'est-ce que le modèle de déploiement 'cloud communautaire' (community cloud) ?",o:["Un cloud ouvert à tous","Une infrastructure cloud partagée entre plusieurs organisations ayant des préoccupations communes (secteur, conformité, mission) — ex: cloud des hôpitaux français conformes au référentiel HDS, cloud des banques européennes — offrant les économies d'échelle du cloud public avec la conformité spécifique du cloud privé","Un cloud social uniquement","Un sous-type de cloud privé"],a:1,e:"Cloud communautaire : type de cloud moins fréquent dans l'AZ-900 mais important. Exemple : Azure Government = cloud communautaire pour agences gouvernementales US. GovCloud = isolation physique + conformité FedRAMP/ITAR. Des organisations similaires (banques, hôpitaux, universités) peuvent partager une infrastructure dédiée à leur secteur. Compromis entre public (économies) et privé (conformité sectorielle)."},
  {t:"Concepts Cloud",q:"Quels sont les 5 caractéristiques essentielles du cloud computing selon le NIST ?",o:["Vitesse, Sécurité, Stockage, Service, Scalabilité","Self-service à la demande (provisionner sans intervention humaine), Large accès réseau (disponible via internet depuis n'importe quel appareil), Mutualisation des ressources (multi-tenant), Élasticité rapide (scale in/out), Service mesuré (payer à l'usage)","Disponibilité, Fiabilité, Performance, Sécurité, Conformité","IaaS, PaaS, SaaS, CaaS, FaaS"],a:1,e:"Le NIST SP 800-145 définit 5 caractéristiques du cloud : 1) On-demand self-service (portail Azure = provisionner sans appeler un technicien), 2) Broad network access (Azure accessible partout), 3) Resource pooling (multi-tenant, ressources partagées), 4) Rapid elasticity (Autoscale), 5) Measured service (facturation à l'usage). Ces concepts fondamentaux sont testés dans l'AZ-900."},
  {t:"Concepts Cloud",q:"Pourquoi dit-on qu'Azure réduit la 'complexité de gestion' par rapport aux datacenters on-premises ?",o:["Azure n'a pas de complexité de gestion","Azure fournit des services managés qui abstrait la complexité infrastructurelle : au lieu de gérer des clusters Redis manuellement, vous utilisez Azure Cache for Redis (managé) ; au lieu d'administrer Kubernetes, vous utilisez AKS ; les sauvegardes, patches, HA sont automatiques — les équipes IT se concentrent sur la valeur business plutôt que sur l'administration systèmes","Azure est plus complexe que l'on-premises","La complexité est identique"],a:1,e:"Réduction de complexité : Azure Cache for Redis → pas d'administration Redis cluster. Azure SQL → pas de DBA pour patches et HA. Azure Kubernetes Service → control plane géré. L'équipe passe de 'gérer des serveurs' à 'livrer des fonctionnalités'. Cela permet à des petites équipes IT de gérer des infrastructures importantes. C'est le cœur de la valeur du cloud."}
);

// Supplément Jour 4 — 13 questions pour atteindre 50
window.QDATA[4].push(
  {t:"Identity avancé",q:"Qu'est-ce que Microsoft Entra External ID (anciennement Azure AD B2C) ?",o:["Un service d'authentification interne uniquement","Un service permettant aux applications d'accueillir des utilisateurs externes (clients, partenaires) avec leurs propres identités (Google, Facebook, Apple, comptes email) — les utilisateurs créent leur compte via des flux d'inscription personnalisables, sans avoir besoin d'un compte Microsoft","Un service VPN","Un service de gestion des licences"],a:1,e:"Entra External ID (B2C) : pour les applications customers-facing. L'utilisateur final (votre client) s'inscrit avec Google/Facebook/email, reçoit un token JWT. Votre app valide le token avec Azure. Complètement configurable (pages de connexion brandées). Différent d'Entra B2B (inviter des utilisateurs partenaires dans votre tenant Entra ID)."},
  {t:"Identity avancé",q:"Qu'est-ce que le Privileged Identity Management (PIM) dans Microsoft Entra ID ?",o:["Un gestionnaire de mots de passe","Un service permettant l'accès Just-In-Time (JIT) aux rôles Entra ID et Azure : les administrateurs n'ont pas les droits admin en permanence mais les 'activent' à la demande pour une durée limitée, avec approbation et MFA obligatoires — réduit drastiquement les risques liés aux comptes compromis","Un service de gestion des VM","Un service de facturation"],a:1,e:"PIM implémente le principe du moindre privilège dans le temps : admin global actif 24/7 = risque maximal (si compte compromis, attaquant a les droits). Avec PIM : admin n'a les droits que 1h quand il active son rôle, avec MFA et justification. Audit complet de qui a activé quoi et quand. Réduction drastique de la surface d'attaque."},
  {t:"Networking avancé",q:"Quelle est la différence entre un NSG (Network Security Group) et Azure Firewall ?",o:["Ce sont des services identiques","NSG : règles L4 (IP source/destination + port) sur sous-réseau ou NIC, sans état ou avec état simple — gratuit, intégré aux VNets; Azure Firewall : service de pare-feu managé L4/L7, inspection stateful complète, filtrage FQDN (noms de domaine), renseignements sur les menaces, IDPS, TLS inspection — payant, centralisé, plus puissant","NSG est plus sécurisé","Azure Firewall est gratuit"],a:1,e:"NSG = règles simples (autoriser/bloquer par IP/port). Azure Firewall = pare-feu enterprise : FQDN filtering (ex: autoriser uniquement *.microsoft.com), Threat Intelligence (bloque IPs/domaines malveillants connus via Microsoft), DNAT pour exposer des services. Architecture recommandée : Azure Firewall dans le hub VNet, NSGs pour micro-segmentation dans les spokes."},
  {t:"Networking avancé",q:"Qu'est-ce que Azure Bastion et pourquoi l'utiliser à la place d'un RDP/SSH direct ?",o:["Un service de stockage sécurisé","Azure Bastion fournit un accès RDP/SSH sécurisé aux VMs directement depuis le portail Azure via HTTPS/TLS, sans exposer les ports RDP (3389) ou SSH (22) sur internet et sans IP publique sur les VMs — élimine le risque d'attaques brute-force sur ces ports critiques","Un service VPN","Un pare-feu réseau"],a:1,e:"Sans Bastion : VM avec IP publique + port 3389 ouvert = cible d'attaques brute-force 24/7. Avec Bastion : les VMs n'ont pas d'IP publique, port 3389/22 jamais exposé sur internet. Connexion via navigateur web (portail Azure) en HTTPS. Bastion est déployé dans le VNet et proxie la connexion. Amélioration sécurité massive pour un coût modéré (~140$/mois)."},
  {t:"Compute avancé",q:"Qu'est-ce qu'Azure Virtual Desktop (AVD) ?",o:["Une VM Windows simple","Un service de bureau virtuel (VDI) cloud : fournit des sessions Windows 10/11 multi-utilisateurs ou des postes de travail virtuels individuels, accessibles depuis n'importe quel appareil (PC, Mac, tablette, thin client) via un navigateur ou l'application — idéal pour le télétravail, la sécurisation des accès, les travailleurs temporaires","Un service de gaming","Un serveur de fichiers"],a:1,e:"Azure Virtual Desktop : Windows 10/11 Enterprise Multi-Session (une seule VM pour plusieurs utilisateurs simultanés, uniquement sur Azure). Cas d'usage : télétravailleurs sur appareils personnels non gérés (l'entreprise garde les données dans Azure), utilisateurs temporaires, accès sécurisé aux applications legacy. Intégration Entra ID, FSLogix pour les profils, Azure Monitor."},
  {t:"AI avancé",q:"Qu'est-ce que l'IA Responsable selon Microsoft et quels sont ses 6 principes ?",o:["Une IA qui prend ses propres décisions","Les 6 principes de l'IA Responsable Microsoft : Équité (pas de biais discriminatoires), Fiabilité et sécurité (comportement prévisible), Confidentialité et sécurité (protection des données), Inclusivité (accessible à tous), Transparence (explicabilité), Responsabilité (humain responsable des décisions IA)","Une IA open-source","Une IA sans erreurs"],a:1,e:"Microsoft Responsible AI : 1) Fairness — pas de biais sur race, genre, âge, 2) Reliability & Safety — comportement prévisible, défaillances gracieuses, 3) Privacy & Security — données protégées, 4) Inclusiveness — accessible aux personnes handicapées, 5) Transparency — explication des décisions, 6) Accountability — humain responsable. Ces principes guident le développement de tous les services IA Azure."},
  {t:"DevOps avancé",q:"Qu'est-ce que le concept 'GitOps' dans le contexte d'Azure Kubernetes Service ?",o:["Un logiciel de gestion de projets","Une pratique où Git est la source unique de vérité pour l'infrastructure et les applications K8s : les changements de configuration/déploiement sont soumis via Pull Request Git, un opérateur (Flux ou Argo CD) dans AKS synchronise automatiquement l'état du cluster avec l'état dans Git — Azure Arc supporte GitOps nativement","Un service Azure payant","Un type de VM Azure"],a:1,e:"GitOps = IaC + PR-based workflow pour K8s. Avantages : audit trail complet (qui a changé quoi), rollback via revert Git, revues de code pour les changements infra, environnements reproductibles. Azure Arc + GitOps : appliquer le même GitOps workflow à des clusters K8s on-premises. AKS native GitOps avec Flux v2 extension."},
  {t:"Gouvernance avancé",q:"Comment Azure Tags aident-ils à l'allocation des coûts entre départements ?",o:["Les tags n'ont aucun impact sur les coûts","En appliquant des tags (ex: Department=Finance, Project=ERP, CostCenter=CC1234) à toutes les ressources Azure, Azure Cost Management peut grouper et filtrer les coûts par tag — les départements voient uniquement leurs coûts et peuvent être refacturés (chargeback) ou informés (showback) de leur consommation Azure","Les tags changent les prix","Les tags sont uniquement visuels dans le portail"],a:1,e:"Tags + Cost Management = allocation des coûts : rapport 'Cost by Tag' montre la consommation par département, projet, application. Chargeback : facturer le département pour sa consommation Azure. Showback : informer sans facturer (sensibilisation). Azure Policy peut exiger que certains tags soient présents sur toutes les ressources (ex: Deny si pas de tag CostCenter)."},
  {t:"Conformité avancé",q:"Qu'est-ce que la norme ISO 27001 et pourquoi est-elle importante pour Azure ?",o:["Une norme de performance réseau","ISO 27001 est un standard international de gestion de la sécurité de l'information (ISMS) qui certifie qu'une organisation a mis en place des processus et contrôles de sécurité selon les meilleures pratiques — Azure est certifié ISO 27001, ce qui permet aux clients de s'appuyer sur cette certification pour leurs propres audits de conformité","Une norme de développement logiciel","Une norme de gestion des ressources humaines"],a:1,e:"ISO 27001 : standard international reconnu mondialement pour la sécurité de l'information. Azure et Microsoft ont obtenu cette certification après audit par un organisme tiers accrédité. Les clients Azure peuvent télécharger le certificat et les rapports audit sur le Service Trust Portal pour démontrer à leurs propres auditeurs que leur infrastructure cloud est sur une plateforme certifiée."},
  {t:"Sustainability",q:"Qu'est-ce qu'Azure Emissions Impact Dashboard ?",o:["Un tableau de bord des performances des VMs","Un outil dans Microsoft Sustainability Manager qui calcule les émissions de CO2 liées à l'utilisation des services Azure d'une organisation, permettant de mesurer, reporter et réduire son empreinte carbone cloud — utile pour les rapports ESG et les engagements de neutralité carbone","Un service de monitoring réseau","Un service de facturation"],a:1,e:"Microsoft s'est engagé à être carbon negative d'ici 2030 (énergie 100% renouvelable, effacement de tout le CO2 émis depuis 1975). Emissions Impact Dashboard : calcule les émissions scope 1/2/3 liées aux services Azure, par service, région, période. S'intègre dans Microsoft Cloud for Sustainability. Aide les entreprises à quantifier leur empreinte carbone IT."},
  {t:"Misc Azure",q:"Qu'est-ce qu'Azure Resource Graph ?",o:["Un graphique de performance Azure","Un service permettant d'effectuer des requêtes complexes (Kusto Query Language) sur toutes les ressources Azure de plusieurs abonnements simultanément — ex: 'Lister toutes les VMs sans tag CostCenter dans tous mes 50 abonnements' — impossible efficacement via le portail ou Azure CLI standard","Un service de visualisation des coûts","Un service de gestion des identités"],a:1,e:"Azure Resource Graph : moteur de requête sur l'inventaire Azure (Azure Resource Manager). Requêtes KQL sur des millions de ressources en secondes. Cas d'usage : audit de conformité (ressources sans tags, NSGs avec port 3389 ouvert), inventaire (toutes les VMs D-series), reporting (ressources créées ce mois). Accessible via portail (Resource Graph Explorer), CLI, PowerShell, API."},
  {t:"Misc Azure",q:"Qu'est-ce qu'Azure Lighthouse ?",o:["Un service de monitoring des VMs","Un service permettant aux fournisseurs de services managés (MSP) et aux partenaires Azure de gérer les ressources Azure de leurs clients depuis leur propre tenant Entra ID, avec une visibilité centralisée sur tous les clients, sans avoir besoin de se connecter séparément à chaque tenant client","Un service de déploiement de phares physiques","Un service de haute disponibilité"],a:1,e:"Azure Lighthouse = gestion multi-tenant : MSP voit tous ses clients dans son portail Azure, applique des politiques et remediations sur tous les clients depuis un seul endroit. Le client autorise l'accès via ARM (pas de comptes partagés, accès RBAC granulaire). Utile pour les intégrateurs et partenaires Microsoft gérant des dizaines/centaines de clients Azure."},
  {t:"Misc Azure",q:"Que sont les 'Quotas et Limites' dans Azure et comment les augmenter ?",o:["Des limites de vitesse réseau uniquement","Des limites par défaut sur le nombre de ressources Azure par abonnement/région (ex: max 20 000 VMs par abonnement, max 50 IPs publiques par région par défaut) — protègent contre les déploiements accidentels massifs; augmentables via une demande de support Azure (Support Request de type 'Service and subscription limits')","Des quotas non modifiables","Des limites uniquement sur le stockage"],a:1,e:"Quotas Azure : limits per subscription/region. Ex défauts : 20 000 vCPUs totaux, 980 Resource Groups, 100 VNets. Augmentation via portail Azure → Support → New Support Request → 'Service and subscription limits (quotas)'. Certaines limites hard (non augmentables), d'autres soft (sur demande). Vérifier les quotas avant les gros déploiements pour éviter les surprises."}
);

// Supplément Jour 5 — 22 questions pour atteindre 50
window.QDATA[5].push(
  {t:"Révision Stockage",q:"Qu'est-ce que Azure Data Lake Storage Gen2 (ADLS Gen2) ?",o:["Une version améliorée d'Azure SQL","Azure Blob Storage avec des capacités ajoutées pour le Big Data analytics : système de fichiers hiérarchique (dossiers réels, permissions POSIX), protocole HDFS compatible (Hadoop), performances optimisées pour les analytics, intégration native avec Azure Databricks, Synapse Analytics et HDInsight","Un service de sauvegarde","Un service de base de données relationnelle"],a:1,e:"ADLS Gen2 = Blob Storage + hiérarchie + analytics. La hiérarchie (vraie structure de dossiers) permet des opérations atomiques sur les répertoires (renommer 1 million de fichiers en une opération vs un fichier à la fois). Permissions ACL POSIX granulaires. Base des architectures Data Lake Azure. Stockage moins cher que les bases de données pour les PB de données brutes."},
  {t:"Révision Compute",q:"Qu'est-ce que les Azure Container Instances (ACI) et quand les utiliser ?",o:["Un service de gestion de box physiques","Le moyen le plus simple et rapide de déployer un container Docker dans Azure sans gérer aucune infrastructure (pas de VM, pas de K8s) — facturation à la seconde de CPU/mémoire, idéal pour les tâches courtes (batch jobs, CI/CD, tests), les microservices simples sans orchestration complexe","Un service de stockage d'images Docker","Un service identique à AKS"],a:1,e:"ACI vs AKS : ACI = déploiement ultra-simple d'un container en 30 secondes, pas de cluster à gérer, facturation à la seconde, idéal pour tâches ponctuelles et microservices stateless simples. AKS = orchestration K8s complète pour applications multi-containers, auto-scaling, service mesh, rolling updates. ACI peut être utilisé comme 'burst' pour AKS via Virtual Kubelet."},
  {t:"Révision Identity",q:"Qu'est-ce que Azure Managed Identity et pourquoi est-ce la meilleure pratique pour l'authentification service-to-service ?",o:["Un type de compte utilisateur Azure","Une identité Entra ID automatiquement créée et gérée par Azure pour une ressource (VM, App Service, Function) — élimine le besoin de stocker des credentials dans le code ou les configs; la ressource obtient un token automatiquement pour accéder à d'autres services Azure (Key Vault, Storage, SQL) sans mot de passe ni clé API","Un service de gestion des mots de passe","Un type de groupe Entra ID"],a:1,e:"Managed Identity résout 'How do I authenticate my app to Azure services without storing credentials?' : System-assigned (lié au cycle de vie de la ressource, supprimé avec elle) vs User-assigned (créée séparément, partageable entre ressources). La ressource appelle un endpoint local pour obtenir un token Azure AD. Zéro secret dans le code. Best practice absolue pour app-to-Azure authentication."},
  {t:"Révision Database",q:"Qu'est-ce que Azure SQL Managed Instance et comment diffère-t-il d'Azure SQL Database ?",o:["Ce sont des services identiques","Azure SQL Managed Instance : compatibilité SQL Server quasi-totale (Agent SQL, cross-database queries, CLR, linked servers, Service Broker, SSAS) dans un service managé — idéal pour la migration lift-and-shift de bases SQL Server complexes; Azure SQL Database : service PaaS plus limité en fonctionnalités SQL Server mais plus scalable et flexible, idéal pour les nouvelles apps cloud-native","SQL MI est gratuit","SQL Database est plus compatible avec SQL Server"],a:1,e:"SQL Managed Instance = 'SQL Server dans le cloud sans VM' : ~99% de compatibilité SQL Server. VNet integration native. Supporte les fonctionnalités avancées : SQL Agent (jobs planifiés), cross-database transactions, linked servers. Idéal pour migrer des apps on-prem complexes. SQL Database = PaaS pur, hyperscale, serverless possible, mais sans certaines fonctionnalités SQL Server legacy."},
  {t:"Révision Réseau",q:"Qu'est-ce que le NAT Gateway dans Azure et quand l'utiliser ?",o:["Un service de traduction de noms de domaine","Un service Azure qui fournit une ou plusieurs IPs publiques statiques sortantes pour toutes les ressources d'un sous-réseau (VMs sans IP publique), permettant le trafic sortant vers internet via une IP fixe prévisible — utile pour les listes blanches IP dans des services tiers","Un type de VPN","Un service de DNS"],a:1,e:"NAT Gateway : fournit la connectivité internet sortante (outbound) à des ressources VNet sans IP publique. Une seule IP NAT pour tout le sous-réseau → prévisible pour les listes blanches chez des partenaires. Supporte 64 000 connexions simultanées par IP. Alternative à l'IP publique sur chaque VM. Différent de Azure Firewall (qui offre aussi l'inspection du trafic)."},
  {t:"Révision AI",q:"Qu'est-ce qu'Azure AI Search (anciennement Azure Cognitive Search) ?",o:["Un moteur de recherche web","Un service de recherche-as-a-service permettant d'ajouter une recherche full-text intelligente à vos applications : indexation de données (Blob, SQL, Cosmos DB), enrichissement via IA (OCR, traduction, extraction d'entités), ranking personnalisable, facettes, suggestions — comparable à Elasticsearch mais managé par Azure","Un service de surveillance des VMs","Un service de base de données"],a:1,e:"AI Search = Elasticsearch managé + IA : indexez vos documents (PDF, Word, images → OCR), votre base de données SQL, votre Blob Storage. Recherche full-text, filtres, facettes (ex: filtrer par date, auteur), suggestions autocomplete. Enrichissement cognitif : extraire des entités, détecter la langue, résumer. Utilisé dans les moteurs de recherche internes d'entreprise."},
  {t:"Révision Architecture",q:"Qu'est-ce qu'une 'région pairée' (paired region) dans Azure et pourquoi existe-t-elle ?",o:["Deux régions au même emplacement physique","Chaque région Azure est associée à une autre région dans la même zone géographique (ex: France Centre ↔ France Sud, East US ↔ West US 2) distante d'au moins 300 km — Microsoft assure que les mises à jour système ne sont jamais déployées simultanément dans les deux régions pairées et que les sauvegardes GRS/GZRS se répliquent dans la région paire","Deux régions dans des continents différents","Des régions identiques en termes de services"],a:1,e:"Régions pairées : protection contre les catastrophes régionales (séisme, ouragan). Avantages : GRS/GZRS stockage vers la région paire, Azure Site Recovery utilise la région paire par défaut, priorité de restauration en cas de panne massive (une région restaurée en premier), pas de mise à jour simultanée des deux régions. Important pour la stratégie DR."},
  {t:"Révision Sécurité",q:"Qu'est-ce que Azure DDoS Protection Standard et pourquoi l'utiliser en plus de Azure DDoS Basic ?",o:["DDoS Protection Standard est inutile","DDoS Protection Standard ajoute : atténuation adaptative et spécifique à votre application (DDoS Basic protège l'infrastructure Azure globalement), SLA de garantie de disponibilité pendant les attaques, rapports d'attaque détaillés, accès à l'équipe Azure DDoS Rapid Response, protection des IPs publiques personnalisées — recommandé pour les applications exposées à internet à fort enjeu","DDoS Basic est suffisant pour tout","Standard est inclus gratuitement"],a:1,e:"DDoS Basic : inclus pour tous, protège l'infrastructure Azure (couche réseau). Standard (~2900$/mois, protège jusqu'à 100 IP publiques) : protection adaptée à votre trafic normal (algorithmes ML apprennent votre baseline), mitigation plus rapide et précise, pas de faux positifs, rapport post-attaque, SLA garantissant la disponibilité pendant l'attaque. Pour les sites bancaires, e-commerce critiques."},
  {t:"Révision Monitoring",q:"Comment Azure Monitor Workbooks améliore-t-il la visualisation des métriques Azure par rapport aux dashboards standard ?",o:["Workbooks est une simple alternative aux dashboards","Azure Monitor Workbooks crée des rapports interactifs et paramétrisables combinant métriques, logs (KQL), texte, paramètres et visualisations avancées — exportables, partageables, versionnés dans GitHub, idéaux pour des rapports de capacité mensuels ou des playbooks d'investigation d'incidents réutilisables","Workbooks est moins puissant que les dashboards","Workbooks est uniquement pour les alertes"],a:1,e:"Workbooks vs Dashboards : Dashboards = épingler des graphiques existants. Workbooks = créer des rapports dynamiques avec du texte explicatif, des paramètres interactifs (choisir l'abonnement, la période), des requêtes KQL et des métriques combinées dans un seul document. Partageable, templateable, versionnable. Idéal : rapport de santé mensuel de l'infrastructure, playbook de troubleshooting."},
  {t:"Révision Compute",q:"Qu'est-ce qu'Azure Dedicated Host ?",o:["Un service d'hébergement web","Des serveurs physiques Azure dédiés exclusivement à votre organisation (pas partagés avec d'autres clients), permettant le contrôle du scheduling de maintenance, la conformité réglementaire requérant isolation physique, et le Bring Your Own License (BYOL) pour certaines licences — coût fixe par hôte physique","Un service de VM standard","Un service de conteneur dédié"],a:1,e:"Dedicated Host : serveur physique Azure exclusif. Cas d'usage : conformité réglementaire exigeant isolation hardware (secteur bancaire, défense), BYOL pour Windows Server/SQL Server avec Software Assurance, contrôle des maintenances (choisir quand l'hôte est restarté). Facturation par hôte physique (pas par VM), quel que soit le nombre de VMs. Plus cher mais nécessaire pour certaines conformités."},
  {t:"Révision Storage",q:"Qu'est-ce que le Lifecycle Management dans Azure Blob Storage ?",o:["La gestion du cycle de vie des VMs","Des règles automatiques qui déplacent les blobs entre tiers de stockage (Hot → Cool → Cold → Archive) ou les suppriment selon leur âge ou dernière modification — ex: 'après 30 jours sans accès, déplacer vers Cool; après 90 jours, vers Archive; supprimer après 7 ans' — optimise automatiquement les coûts de stockage","Un service de gestion des instances","Un service de sauvegarde uniquement"],a:1,e:"Blob Lifecycle Management : configure des politiques (JSON ou GUI) sur le Storage Account. Ex: logs d'application → Hot (30 jours accès fréquent), Cool (30-90 jours), Archive (après 90 jours), Delete (après 7 ans pour conformité). S'exécute automatiquement. Réduction des coûts sans intervention manuelle. Compatible avec immutable storage pour les archives légales."},
  {t:"Révision Cost",q:"Qu'est-ce qu'Azure Hybrid Benefit et à qui s'applique-t-il ?",o:["Un avantage pour les systèmes hybrides physiques","Une remise Azure permettant d'utiliser les licences Windows Server et SQL Server avec Software Assurance (ou abonnements actifs) déjà possédées on-premises pour réduire les coûts des VMs et SQL Database Azure — économies jusqu'à 49% pour Windows Server, 55% pour SQL Server","Un avantage uniquement pour Linux","Un avantage pour les clients Azure depuis plus de 5 ans"],a:1,e:"Hybrid Benefit : si vous avez déjà payé des licences Windows Server ou SQL Server avec Software Assurance (maintenance annuelle), vous pouvez les 'porter' vers Azure et ne payer que le compute (pas la licence OS/SQL). Ex: SQL Database = jusqu'à 55% d'économies. Windows Server VM = jusqu'à 49%. Combiné aux Reservations : économies totales jusqu'à 80%."},
  {t:"Révision Governance",q:"Qu'est-ce qu'une Azure Blueprint et comment fonctionne-t-elle ?",o:["Un modèle 3D de datacenter","Un package réutilisable regroupant des politiques Azure Policy, des rôles RBAC, des Resource Groups et des templates ARM — permet de déployer rapidement un environnement Azure complet et conforme (ex: Landing Zone d'un département IT avec tous les contrôles de sécurité) de manière cohérente et répétable","Un service de documentation","Un type d'abonnement Azure"],a:1,e:"Azure Blueprints va au-delà des ARM templates : orchestre policies + RBAC + ARM ensemble, avec suivi de conformité (sait quelles ressources viennent du blueprint), verrouillage (empêche la modification des ressources déployées par le blueprint). Déploiement d'une Landing Zone complète en quelques minutes. Versionning des blueprints. Maintenant intégré dans Azure Deployment Environments."},
  {t:"Révision Support",q:"Qu'est-ce que Azure Advisor et comment diffère-t-il du support Azure ?",o:["Un service de formation Azure","Un service de recommandations automatisé et gratuit qui analyse votre environnement Azure et suggère des améliorations dans 5 domaines : Fiabilité, Sécurité, Performance, Excellence opérationnelle et Coûts — ex: 'Vous avez des VMs sans backup, activez Azure Backup' ou 'Ces réservations vous feraient économiser 500$/mois'","Un humain qui conseille sur Azure","Un service identique au support Microsoft"],a:1,e:"Azure Advisor = consultant automatique intégré : analyse vos ressources et génère des recommandations personnalisées. Fiabilité : 'Cette VM n'a pas de backup'. Sécurité : 'Ces VMs ont des ports non nécessaires ouverts'. Performance : 'Cette App Service plan est trop grande pour votre charge'. Coûts : 'Ces VMs sont sous-utilisées, réduisez leur taille'. Gratuit, disponible via le portail."},
  {t:"Révision Services",q:"Qu'est-ce qu'Azure Service Bus et quand l'utiliser vs Azure Queue Storage ?",o:["Un service de transport en commun Azure","Azure Service Bus : messagerie enterprise avancée (files d'attente et topics/abonnements pub/sub), sessions, transactions, dead-letter queue, ordonnancement, filtrage de messages, AMQP/MQTT — pour les architectures microservices complexes; Azure Queue Storage : messagerie simple et bon marché (max 64Ko/message, pas de pub/sub) — pour le découplage simple","Service Bus est gratuit, Queue Storage est payant","Ils sont identiques"],a:1,e:"Service Bus : messagerie enterprise. Topics = pub/sub (1 producteur, N consommateurs avec filtres). Sessions = traitement ordonné. Dead-letter = messages non traités après N tentatives. FIFO garanti. Transactions. Pour : microservices, workflows, intégrations enterprise. Queue Storage : simple, messages < 64Ko, max 7 jours TTL, pas de pub/sub. Pour : découplage simple, background jobs, scale-out."},
  {t:"Révision Services",q:"Qu'est-ce qu'Azure Event Hubs et pour quel cas d'usage est-il conçu ?",o:["Un service de calendrier d'événements","Un service d'ingestion de données en streaming à très haute échelle (millions d'événements/seconde) compatible Apache Kafka — conçu pour les architectures de big data streaming : télémétrie IoT, logs applicatifs, clickstream analytics, données financières temps réel → Azure Stream Analytics ou Azure Databricks pour le traitement","Un service de gestion d'événements Azure (pannes, maintenances)","Un service identique à Service Bus"],a:1,e:"Event Hubs vs Service Bus : Event Hubs = ingestion streaming à volume massif (think Apache Kafka). Retention configurable (1-90 jours), Consumer Groups pour multiples lecteurs indépendants. Pas de dead-letter, pas de sessions, pas de transactions. Service Bus = messages individuels importants avec garanties de livraison. Event Hubs capture optionnelle vers Azure Storage/ADLS Gen2 pour le replay."},
  {t:"Révision Architecture",q:"Qu'est-ce qu'Azure Application Gateway et quel est son avantage par rapport à Azure Load Balancer pour les applications web ?",o:["Application Gateway est moins performant","Application Gateway est un load balancer L7 (HTTP/HTTPS) offrant : SSL/TLS termination (déchiffrement SSL centralisé, VMs reçoivent du HTTP), WAF (protection OWASP), routage basé sur l'URL (/api → farm API, /images → farm statique), cookie-based session affinity, redirection HTTP vers HTTPS, rewrite headers — Load Balancer L4 ne comprend pas le protocole HTTP","Load Balancer est toujours préférable","Ils sont identiques"],a:1,e:"Application Gateway L7 est supérieur pour le web : SSL offloading (les VMs ne gèrent pas le SSL, économies CPU), WAF intégré (bloquer SQL injection, XSS), path-based routing (architecture multi-tier propre), header rewriting. Load Balancer L4 = distribution TCP/UDP haute performance sans inspection du contenu. Schéma typique : Application Gateway devant les VMs web, Load Balancer entre les VMs et les serveurs backend."},
  {t:"Révision Compliance",q:"Qu'est-ce que la norme SOC 2 Type II et pourquoi Azure est-il certifié SOC 2 ?",o:["Un standard de performance réseau","SOC 2 Type II est un rapport d'audit indépendant certifiant qu'Azure a maintenu des contrôles efficaces de Sécurité, Disponibilité, Intégrité des données, Confidentialité et Protection de la vie privée sur une période de temps (généralement 12 mois) — plus rigoureux que SOC 2 Type I (qui ne teste qu'un instant T)","Un standard de gestion des ressources humaines","Une certification de performance"],a:1,e:"SOC 2 Type II : audité annuellement par un auditeur indépendant (CPA). Azure SOC 2 Type II couvre les 5 critères Trust Services. Téléchargeable sur Service Trust Portal. Différence Type I vs II : Type I = à un instant donné, Type II = sur une période (plus de valeur). Les clients peuvent utiliser le rapport SOC 2 Azure dans leur propre audit SOC 2 via le concept de 'shared responsibility'."},
  {t:"Révision Identity",q:"Comment fonctionne le SSO (Single Sign-On) avec Microsoft Entra ID ?",o:["SSO nécessite l'installation d'un agent sur chaque application","L'utilisateur s'authentifie une fois auprès d'Entra ID (avec MFA si requis) et reçoit un token JWT valide pour toutes les applications intégrées (Microsoft 365, Salesforce, ServiceNow, applications custom SAML/OIDC) — sans se reconnecter à chaque application pendant la durée de validité du token","SSO est uniquement pour les applications Microsoft","SSO ne fonctionne pas avec les applications tierces"],a:1,e:"SSO avec Entra ID : protocoles standards (SAML 2.0, OpenID Connect, OAuth 2.0, WS-Fed). L'utilisateur se connecte → Entra ID authentifie → token JWT émis → applications validant le token Entra ID acceptent l'accès. 4000+ apps pré-intégrées dans la galerie Azure AD. Apps custom : configuration SAML ou OIDC. Bénéfice : moins de mots de passe à retenir, moins de risques."},
  {t:"Révision Cost",q:"Qu'est-ce que Azure Cost Management Budgets et comment les configurer ?",o:["Un service qui bloque automatiquement les dépenses quand le budget est atteint","Un mécanisme dans Azure Cost Management permettant de définir des seuils de dépenses (ex: budget 5000€/mois pour un abonnement) et d'envoyer des alertes email quand les dépenses réelles ou prévues atteignent un pourcentage du budget (ex: alerter à 80% et 100%) — ne bloque pas automatiquement les ressources mais alerte pour une action manuelle","Un service de paiement Azure","Un type d'abonnement Azure"],a:1,e:"Budget alerts : configurables par abonnement, Resource Group, ou tag. Alertes à 70%, 90%, 100% de dépenses réelles ou forecasted (Azure prédit les dépenses du mois). Par défaut : email au propriétaire du budget. Peut déclencher un Runbook Azure Automation ou un webhook pour des actions automatiques (stopper des VMs via script). Pas de blocage automatique natif (Azure Policy peut bloquer les déploiements si budget dépassé avec une configuration avancée)."},
  {t:"Révision Compliance",q:"Qu'est-ce que le concept de 'residency of data' vs 'sovereignty of data' dans Azure ?",o:["Ces termes sont synonymes","Residency : où les données sont stockées physiquement (ex: données stockées uniquement dans les régions Europe Azure); Sovereignty : qui peut accéder légalement aux données (ex: les autorités d'un pays peuvent-elles demander l'accès?) — Sovereign Cloud Azure (Government, China) adresse les deux : stockage en territoire national ET opérations par du personnel local sous juridiction locale","Sovereignty concerne uniquement la sécurité","Residency concerne uniquement les performances"],a:1,e:"Residency = géographie du stockage. Azure permet de choisir sa région. Sovereignty = contrôle juridique. Les lois des pays où sont les datacenters s'appliquent (CLOUD Act US). Azure Sovereign Clouds : Azure Government (US gov, personnel US, loi américaine), Azure China (21Vianet, loi chinoise), Azure Germany (T-Systems comme Treuhänder, loi allemande - maintenant fermé). Pour les gouvernements, les deux sont critiques."}
);

// Supplément Jour 6 — 24 questions pour atteindre 50
window.QDATA[6].push(
  {t:"Well-Architected",q:"Comment le pilier 'Optimisation des coûts' du Well-Architected Framework est-il implémenté dans Azure ?",o:["En supprimant toutes les ressources inutilisées manuellement","Via : Azure Cost Management (suivi et budgets), Azure Advisor (recommandations de rightsizing et reservations), Reservations et Savings Plans (engagement = économies), Auto-shutdown pour dev/test, PaaS vs IaaS (moins de gestion), architectures serverless (payer uniquement à l'usage)","En utilisant uniquement des VMs gratuites","Via Azure Policy uniquement"],a:1,e:"Optimisation des coûts Well-Architected : Design for cloud (architectures serverless et PaaS coûtent moins en gestion), Monitor and optimize (Azure Cost Management + Advisor), Use consumption pricing (serverless pour les charges variables), Rightsize (VMs trop grosses → Advisor recommande), Plan commitments (Reservations pour charges stables). Pas une optimisation unique mais un processus continu."},
  {t:"Well-Architected",q:"Quelle est l'importance du pilier 'Excellence opérationnelle' dans le Well-Architected Framework Azure ?",o:["Ce pilier concerne uniquement les équipes DevOps","Ce pilier couvre : les processus de déploiement CI/CD (Azure DevOps, GitHub Actions), l'Infrastructure as Code (reproductibilité), le monitoring et observabilité (Azure Monitor, Application Insights), les runbooks pour les opérations routinières (Azure Automation), la gestion des incidents, et la culture d'amélioration continue","Ce pilier n'est pas pertinent pour les petites applications","Ce pilier concerne uniquement la sécurité"],a:1,e:"Excellence opérationnelle = tout ce qui permet de livrer des changements sûrement et rapidement : CI/CD pipelines (déploiements automatisés, pas manuels), IaC (infrastructures reproductibles), observabilité (savoir ce qui se passe), alertes et runbooks (réponse aux incidents automatisée). Une application bien architecturée peut être déployée, monitorée et récupérée de manière fiable et répétable."},
  {t:"Hybrid Cloud",q:"Qu'est-ce qu'Azure Stack Edge ?",o:["Un service de stockage edge","Une appliance physique Microsoft combinant compute GPU/CPU, stockage et réseau, déployée chez le client pour le traitement de données en périphérie (edge computing) — exécute des modules IoT Edge, des modèles ML localement (inférence sans connexion cloud), et synchronise les données vers Azure : idéal pour les usines, les hôpitaux, les plateformes pétrolières","Un service Azure pour les téléphones","Un type de region Azure"],a:1,e:"Azure Stack Edge (anciennement Data Box Edge) : matériel Azure dans vos locaux. GPU pour inférence ML en temps réel (vision par ordinateur sur chaîne de production sans latence réseau), traitement local des données IoT (filtrer avant d'envoyer au cloud), stockage NAS géré, synchronisation Azure. Cas : usines sans connexion internet fiable, médecine en terrain isolé, véhicules autonomes."},
  {t:"Migration",q:"Qu'est-ce que l'Azure Cloud Adoption Framework (CAF) ?",o:["Un framework de facturation Azure","Un guide Microsoft complet pour l'adoption du cloud en entreprise : phases Strategy (définir les motivations), Plan (roadmap), Ready (préparer l'environnement avec Landing Zones), Adopt (migrer et innover), Govern (policies et compliance), Manage (opérations) — avec des outils, templates et meilleures pratiques pour chaque phase","Un framework de développement logiciel","Un type d'abonnement Azure"],a:1,e:"CAF = playbook de transformation cloud Microsoft : la phase Ready produit les Landing Zones (environnement Azure gouverné prêt pour les workloads), la phase Adopt couvre Migration (lift-and-shift existant) et Innovation (nouveaux services cloud-native), Govern couvre Azure Policy/RBAC, Manage couvre Azure Monitor/Backup. Documentation complète sur learn.microsoft.com."},
  {t:"Architecture Patterns",q:"Qu'est-ce que le pattern 'Strangler Fig' dans le contexte d'une migration progressive vers Azure ?",o:["Un type de déploiement K8s","Un pattern de migration qui remplace progressivement les fonctionnalités d'un système monolithique par de nouveaux services cloud-native, routant le trafic progressivement vers les nouveaux services (via Azure Application Gateway ou Traffic Manager) jusqu'à ce que l'ancien système soit complètement remplacé — sans migration big bang risquée","Un pattern de sécurité réseau","Un pattern de base de données"],a:1,e:"Strangler Fig (du figuier étrangleur qui pousse autour d'un arbre) : la modernisation progressive. Application Gateway route /feature1 vers le nouveau microservice Azure, /feature2 reste vers l'ancien monolithe. Au fil du temps, tout le trafic est routé vers les nouveaux services, le monolithe 'étranglé' est arrêté. Minimise le risque vs réécriture complète. Adapté à la migration d'applications complexes."},
  {t:"Serverless",q:"Qu'est-ce qu'Azure Durable Functions ?",o:["Une version améliorée d'Azure App Service","Une extension d'Azure Functions permettant d'écrire des workflows stateful dans un environnement serverless — patterns : Function Chaining (séquence de fonctions), Fan-out/Fan-in (paralleliser), Human interaction (attendre une approbation), Eternal orchestrations (monitoring polling) — état persisté automatiquement sans gérer les queues ou le stockage","Un service de sauvegarde des fonctions","Un type de base de données serverless"],a:1,e:"Durable Functions résout les workflows longs et complexes en serverless : une fonction orchestrateur coordonne des fonctions activités. L'état est automatiquement checkpointé (si la Function est redémarrée, elle reprend là où elle s'est arrêtée). Idéal : processus d'approbation multi-étapes, traitement de commande (vérifier stock → débiter → notifier), batch processing parallèle avec consolidation."},
  {t:"Sécurité avancée",q:"Qu'est-ce qu'Azure Active Directory Identity Protection (maintenant Entra ID Protection) ?",o:["Un service d'antivirus","Un service qui utilise le ML de Microsoft (qui analyse des milliards de connexions/jour) pour détecter des connexions à risque (IPs anonymes, voyage impossible, credential stuffing) et des utilisateurs à risque (credentials exposés sur le dark web) — peut déclencher automatiquement une MFA challenge ou bloquer la connexion","Un service de gestion des mots de passe","Un service de monitoring des VMs"],a:1,e:"Entra ID Protection : analyse chaque connexion avec le signal global Microsoft (14 milliards de connexions/jour). Détecte : connexion depuis IP Tor, connexion impossible (Paris puis Tokyo en 1h), credential stuffing (tentatives massives), leaked credentials (mots de passe trouvés dans des bases de données compromises). Politique de risque utilisateur → forcer le changement de mot de passe si compromis."},
  {t:"Données",q:"Quelle est la différence entre Azure Stream Analytics et Azure Databricks pour le traitement en temps réel ?",o:["Ils sont identiques","Azure Stream Analytics : SQL-like pour le streaming temps réel simple, configuration sans code, intégration native Event Hubs/IoT Hub/Blob, latence faible, idéal pour les agrégations et transformations simples en temps réel; Azure Databricks Structured Streaming : streaming Spark complet, Python/Scala/SQL, ML temps réel, transformations complexes, mais plus coûteux et complexe à configurer","Stream Analytics est plus puissant que Databricks","Databricks ne supporte pas le streaming"],a:1,e:"Stream Analytics : pour les opérateurs (équipes IoT, data engineers moins avancés), configuration via requêtes SQL-like dans le portail, 90% des cas de streaming simples (agrégations par fenêtre temporelle, détection d'anomalies simples). Databricks Structured Streaming : pour les data scientists (Python/Scala), ML temps réel, joins complexes avec données historiques, Delta Lake. Coût : Stream Analytics (par Streaming Unit), Databricks (clusters)."},
  {t:"Données",q:"Qu'est-ce que le service Azure Purview (maintenant Microsoft Purview) ?",o:["Un service de surveillance réseau","Un service de gouvernance des données permettant de : découvrir et cataloguer automatiquement les données (scan Azure, SQL, SAP, S3), classifier les données sensibles (numéros de carte, données personnelles), tracer la lignée des données (de la source à Power BI), gérer les politiques d'accès aux données et assurer la conformité RGPD","Un service de facturation","Un service de déploiement"],a:1,e:"Microsoft Purview (Data Governance) : catalogue de données entreprise. Le scanner découvre les assets de données (tables SQL, conteneurs Blob, fichiers ADLS) et les classe automatiquement (PII, financier, médical via ML). La lignée montre comment les données circulent (table SQL → Data Factory → ADLS → Power BI dashboard). Essentiel pour le RGPD (where is my personal data?)."},
  {t:"DevOps",q:"Qu'est-ce que Azure Container Registry (ACR) ?",o:["Un service de gestion des voitures","Un registre d'images Docker privé dans Azure permettant de stocker, gérer et distribuer les images de containers (Docker, OCI) — intégré avec ACI, AKS, App Service; géo-réplication pour distribuer les images mondialement; tâches ACR pour builder des images sans infrastructure CI; scan des vulnérabilités des images avec Microsoft Defender","Un service de gestion des conteneurs physiques","Un service identique à Docker Hub"],a:1,e:"ACR vs Docker Hub : ACR est privé, dans votre VNet, intégré nativement avec AKS et l'authentification Entra ID (Managed Identity d'AKS peut puller sans credentials). Géo-réplication : image disponible dans toutes les régions Azure en latence minimale. Tâches ACR : builder une image sur commit Git sans agent CI. Defender for Container Registry : scan CVE des images à chaque push."},
  {t:"DevOps",q:"Comment Azure DevOps Pipelines et GitHub Actions se comparent-ils pour CI/CD dans Azure ?",o:["Azure DevOps Pipelines est toujours supérieur","Azure DevOps Pipelines : mature, YAML ou UI, intégration profonde Azure, gestion avancée des environnements et approbations, traces et tests; GitHub Actions : syntaxe YAML moderne, marketplace d'actions (10 000+), intégration GitHub native, GitHub Copilot pour écrire les workflows, open-source friendly — les deux peuvent déployer vers Azure, le choix dépend de l'écosystème de l'équipe","GitHub Actions est toujours supérieur","Ils ne peuvent pas déployer vers Azure"],a:1,e:"Azure DevOps Pipelines : enterprise features (deployment gates, approvals, release management, test plans intégrés). GitHub Actions : moderne, marketplace énorme, intégré avec GitHub PRs et issues. Microsoft recommande GitHub Actions pour les nouvelles implémentations mais supporte les deux. Credential : GitHub Actions utilise des OIDC tokens (sans secret) pour déployer vers Azure via Azure Login action."},
  {t:"Architecture",q:"Qu'est-ce que l'architecture Hub-Spoke dans Azure et pourquoi est-elle recommandée ?",o:["Une architecture uniquement pour les grandes entreprises","Architecture réseau Azure recommandée : un VNet Hub central (contenant les services partagés : Azure Firewall, VPN/ExpressRoute Gateway, DNS, Bastion) connecté via VNet Peering à plusieurs VNets Spoke (un par application/département) — centralise les services de sécurité et évite les connexions directes entre spokes (passent par le hub)","Une architecture uniquement pour K8s","Une architecture identique à un VNet unique"],a:1,e:"Hub-Spoke : analogie à une roue de vélo. Hub = services centraux (Firewall centralise l'inspection, Gateway = connectivité on-prem). Spoke = workloads isolés (pas de communication directe spoke-to-spoke sauf via hub). Avantages : sécurité centralisée, séparation des responsabilités, scalabilité (ajouter un nouveau spoke = nouveau département), coût optimisé (un seul Firewall/Gateway). Pattern de référence Azure Landing Zone."},
  {t:"Architecture",q:"Qu'est-ce qu'Azure Traffic Manager et comment diffère-t-il d'Azure Front Door ?",o:["Ce sont des services identiques","Azure Traffic Manager : service de load balancing DNS (Couche 4) routant vers des endpoints en fonction de la latence, de la géographie, de la priorité ou du poids — fonctionne avec tout endpoint public (Azure, on-prem, autres clouds); Azure Front Door : CDN + load balancer L7 HTTP/HTTPS avec accélération du trafic, WAF, caching — optimisé pour les applications web","Traffic Manager est plus récent","Front Door est moins cher"],a:1,e:"Traffic Manager = DNS LB : le client DNS résout l'URL → Traffic Manager retourne l'IP de l'endpoint le plus adapté → client se connecte directement. Latency routing : mesure la latence vers chaque région et route vers la plus proche. Front Door : Anycast (le trafic entre dans le réseau Microsoft dès le premier POP et y reste jusqu'à destination), optimisation TCP, WAF. Pour les apps web : Front Door. Pour les endpoints non-HTTP (TCP, UDP) ou multi-cloud : Traffic Manager."},
  {t:"Architecture",q:"Qu'est-ce que Azure API Management (APIM) ?",o:["Un service de gestion des VMs","Un service de passerelle API (API Gateway) permettant de publier, sécuriser, documenter et analyser les APIs : authentication (OAuth, API keys), rate limiting (throttling), transformation des requêtes/réponses, portail développeur (documentation interactive), analytics d'utilisation, versionning des APIs — façade unifiée pour des APIs hétérogènes","Un service de base de données API","Un service de messagerie"],a:1,e:"APIM = façade pour toutes vos APIs : backend peut être App Service, Functions, K8s, on-prem. Policies : transformer les requêtes (ajouter headers, remplacer URLs), appliquer des quotas par souscription, cacher les réponses. Portail développeur : documentation Swagger interactive auto-générée pour les consommateurs d'API. Monetisation possible (souscriptions payantes). Intégration Azure Monitor pour analytics."},
  {t:"Sécurité",q:"Qu'est-ce qu'un WAF (Web Application Firewall) dans Azure et où peut-il être déployé ?",o:["Un service uniquement pour les grandes entreprises","Un WAF inspecte le trafic HTTP/HTTPS et bloque les attaques OWASP Top 10 (SQL injection, XSS, CSRF, etc.) — dans Azure, déployable sur : Azure Application Gateway (WAF SKU), Azure Front Door (WAF global), Azure CDN — basé sur des règles CRS (Core Rule Set) OWASP avec mode Detection ou Prevention","Un type de pare-feu réseau L4","Un service uniquement pour WordPress"],a:1,e:"WAF (Couche 7) vs NSG/Firewall (Couches 3-4) : le WAF comprend le protocole HTTP et peut détecter les injections SQL dans les paramètres URL. Application Gateway WAF : pour les applications dans une région, colocalise load balancing et WAF. Front Door WAF : global, protège les applications multi-régions. Modes : Detection (log uniquement, pas de blocage — pour calibrer), Prevention (bloquer les attaques). CRS 3.2 par défaut."},
  {t:"Sécurité",q:"Comment Azure Key Vault protège-t-il les clés cryptographiques avec HSM ?",o:["Key Vault n'utilise pas de HSM","Azure Key Vault Premium tier utilise des Hardware Security Modules (HSM) certifiés FIPS 140-2 Level 2 pour stocker les clés de chiffrement — les clés ne quittent jamais le HSM physiquement, toutes les opérations cryptographiques se font dans le HSM, même les administrateurs ne peuvent pas extraire les clés en clair","Key Vault Premium est identique à Standard","HSM n'est pas certifié dans Azure"],a:1,e:"Key Vault Premium HSM : clés générées et stockées dans le HSM (puce physique tamper-proof). BYOK (Bring Your Own Key) : transférer vos propres clés depuis un HSM on-prem vers Azure HSM de manière sécurisée. Azure Managed HSM : HSM dédié exclusivement à votre tenant (pas multi-tenant), certifié FIPS 140-2 Level 3. Pour les exigences de conformité les plus strictes (banques, défense, gouvernements)."},
  {t:"Architecture",q:"Qu'est-ce que le concept de 'multi-tenant' dans Azure et comment Azure isole-t-il les tenants ?",o:["Multi-tenant signifie que plusieurs entreprises partagent les mêmes VMs","Multi-tenant = plusieurs organisations partagent la même infrastructure physique Azure, mais chaque organisation (tenant) est logiquement isolée des autres via : hyperviseur (isolation des VMs), VNets (isolation réseau), Entra ID tenants séparés, chiffrement des données au repos et en transit — les tenants ne peuvent pas voir les données des autres","Multi-tenant = moins sécurisé que dédié","Multi-tenant est uniquement pour les abonnements gratuits"],a:1,e:"L'isolation multi-tenant Azure est fondamentale pour la sécurité cloud public : l'hyperviseur Hyper-V isole les VMs (une VM compromisée ne peut pas accéder à une autre VM sur le même hôte), les VNets sont des réseaux overlay logiques entièrement isolés (deux entreprises peuvent utiliser 10.0.0.0/24 sans conflit), chaque tenant Entra ID est une forêt AD séparée. Microsoft est responsable de cette isolation (modèle de responsabilité partagée)."},
  {t:"Architecture",q:"Pourquoi Azure recommande-t-il d'utiliser plusieurs abonnements plutôt qu'un seul grand abonnement pour une grande organisation ?",o:["Pour facturer plus","Pour des raisons de : isolation (environnements prod/dev/test séparés préviennent les erreurs), quotas (limites de ressources par abonnement évitées en les distribuant), billing (facturation par équipe/projet), governance (politiques et RBAC différents par contexte), conformité (certaines données dans des abonnements avec politiques strictes) — Management Groups gèrent l'ensemble","Un seul abonnement est toujours suffisant","Azure limite les abonnements à 10"],a:1,e:"Multi-abonnements recommandés : abonnement production (politique strictes, pas de dev), abonnement dev/test (plus permissif, réductions), abonnements par business unit (billing séparé, quotas séparés). Azure Landing Zone typique : Management, Connectivity, Identity abonnements Platform + N abonnements Landing Zone pour les workloads + Sandboxes pour les tests. Management Groups fédère le tout."},
  {t:"Services Divers",q:"Qu'est-ce qu'Azure SignalR Service et pour quels cas d'usage ?",o:["Un service de signature électronique","Un service PaaS managé qui permet d'ajouter des fonctionnalités temps réel (WebSocket) à vos applications web : notifications push instantanées, chat en direct, tableaux de bord temps réel, collaboration en temps réel — sans gérer l'infrastructure SignalR/WebSocket","Un service de certificats TLS","Un service VPN"],a:1,e:"Azure SignalR Service : pour les applications nécessitant des mises à jour du serveur vers le client (server-push) sans polling. Cas d'usage : tableau de bord boursier mis à jour en temps réel, application de chat, jeux multi-joueurs, suivi de localisation, notifications d'alertes instantanées. Compatible avec les apps ASP.NET Core SignalR existantes. Scale automatique à des millions de connexions WebSocket simultanées."},
  {t:"Services Divers",q:"Qu'est-ce qu'Azure Static Web Apps ?",o:["Un service pour des sites web qui ne changent jamais","Un service de déploiement et d'hébergement optimisé pour les applications web statiques (HTML, CSS, JavaScript — Angular, React, Vue, Svelte) avec : déploiement CI/CD automatique depuis GitHub/Azure DevOps, distribution CDN globale gratuite, SSL inclus, intégration Azure Functions pour le backend API, authentification intégrée","Un service uniquement pour WordPress","Un service identique à Azure App Service"],a:1,e:"Static Web Apps : gratuit pour les applications statiques basiques. Le push vers GitHub déclenche automatiquement le build et le déploiement (GitHub Actions). CDN global inclus. SSL/HTTPS automatique. API via Azure Functions intégré (même déploiement). Staging environments pour les Pull Requests (preview de chaque PR). Authentification : Google, GitHub, Twitter. Idéal pour les SPA modernes."},
  {t:"Services Divers",q:"Qu'est-ce que Azure Cognitive Services (maintenant Azure AI Services) ?",o:["Un service pour les développeurs uniquement","Un ensemble de services IA pré-construits accessibles via des APIs REST : Vision (analyse d'images, OCR, reconnaissance faciale), Language (traduction, analyse de sentiment, NLP), Speech (speech-to-text, text-to-speech, traduction vocale), Decision (Personalizer, Content Moderator, Anomaly Detector), OpenAI (GPT, DALL-E) — utilisables sans expertise ML","Un service de base de données IA","Un service de gestion des équipes"],a:1,e:"Azure AI Services (ex-Cognitive Services) : IA clé en main. Appel API → résultat IA. Ex: envoyer une image → recevoir description en texte (Computer Vision), envoyer du texte → recevoir la langue, les entités et le sentiment (Language Service), envoyer audio → recevoir transcription (Speech). Pas besoin de dataset, pas d'entraînement. Consommation Pay-per-call. Base des applications IA sans expertise ML."},
  {t:"Services Divers",q:"Qu'est-ce qu'Azure IoT Hub et comment fonctionne-t-il ?",o:["Un service de gestion des datacenters physiques","Un service cloud gérant la communication bidirectionnelle entre des millions d'appareils IoT et Azure : les appareils enregistrés s'authentifient avec des certificats X.509 ou SAS tokens, envoient leurs données vers IoT Hub (device-to-cloud), IoT Hub peut envoyer des commandes vers les appareils (cloud-to-device), et Azure Stream Analytics ou Functions traitent les données en temps réel","Un service WiFi Azure","Un service de gestion des conteneurs"],a:1,e:"IoT Hub = 'broker' entre appareils et cloud. Protocoles : MQTT, AMQP, HTTPS. Fonctionnalités : Device Twin (état désiré vs état réel de l'appareil), Jobs (mise à jour de milliers d'appareils en parallèle), Message routing (router les messages vers différents services Azure selon les propriétés), Device Provisioning Service (enregistrement automatique à grande échelle). Base de toute architecture IoT Azure."},
  {t:"Services Divers",q:"Qu'est-ce qu'Azure Batch ?",o:["Un service de traitement par lots de factures","Un service de calcul haute performance (HPC) permettant d'exécuter des milliers de tâches parallèles sur des VMs managées : Azure Batch provisionne automatiquement les VMs, exécute les jobs, et les désalloue quand terminé — idéal pour le rendu 3D, la simulation financière, l'analyse génomique, le traitement vidéo","Un service de mise à jour des VMs","Un service de gestion des bases de données"],a:1,e:"Azure Batch : HPC-as-a-service. Vous définissez un pool de VMs (type, taille, nombre), une liste de tâches. Batch orchestre l'exécution : assigne les tâches aux VMs, gère les retentatives en cas d'échec, scale down quand terminé. Supporte les Spot VMs pour réduire les coûts (80%+). Rendu de films Pixar/DreamWorks utilise ce type d'infrastructure. Facturation : uniquement pour les heures VM utilisées."}
);

// Supplément Jour 7 — 26 questions pour atteindre 50
window.QDATA[7].push(
  {t:"Révision finale",q:"Quelle est la différence fondamentale entre Azure Policy et Azure RBAC ?",o:["Ils sont identiques","Azure RBAC contrôle QUI peut faire QUOI sur les ressources Azure (permissions d'actions : créer VM, lire Key Vault), tandis qu'Azure Policy contrôle CE QUE les ressources PEUVENT ÊTRE (contraintes sur les propriétés : toutes les VMs doivent être dans westeurope, toutes les ressources doivent avoir un tag)","RBAC est uniquement pour les utilisateurs, Policy pour les services","Policy est plus récent que RBAC"],a:1,e:"RBAC = autorisation (qui peut agir). Policy = gouvernance (quelles propriétés les ressources peuvent avoir). Exemple : RBAC donne à l'équipe réseau le droit de créer des VNets, Policy impose que tous les VNets doivent être dans un certain range CIDR. Les deux se complètent : RBAC sans Policy = les gens peuvent créer des ressources non-conformes; Policy sans RBAC = tout le monde est bloqué par les policies."},
  {t:"Révision finale",q:"Qu'est-ce que le concept de 'defence in depth' (défense en profondeur) dans Azure ?",o:["Une stratégie militaire","Une approche de sécurité multi-couches : couche physique (sécurité des datacenters Microsoft), couche réseau (NSG, Firewall, DDoS), couche périmètre (WAF), couche calcul (VMs patchées, Defender), couche application (code sécurisé), couche données (chiffrement at-rest/in-transit, Key Vault) — chaque couche protège si la précédente est compromise","Une seule couche de sécurité très robuste","Un service Azure spécifique"],a:1,e:"Défense en profondeur : pas de point unique de défaillance pour la sécurité. Si un attaquant contourne le WAF (couche application), il tombe sur le NSG. S'il contourne le NSG, les données sont chiffrées. Microsoft est responsable des couches physiques/réseau infrastructure; vous êtes responsable des couches plus hautes (selon modèle responsabilité partagée). Zero Trust prolonge ce concept avec 'vérifier toujours, ne jamais faire confiance'."},
  {t:"Révision finale",q:"Un administrateur souhaite s'assurer que toutes les ressources Azure de l'organisation ont des tags 'Environment' et 'CostCenter'. Quelle est la meilleure approche ?",o:["Créer un script PowerShell exécuté manuellement chaque semaine","Créer une Azure Policy avec l'effet 'Deny' qui refuse la création de ressources sans ces tags requis, assignée au niveau Management Group pour couvrir tous les abonnements — alternativement 'Audit' pour visibilité sans blocage immédiat","Contacter chaque équipe pour qu'elles ajoutent les tags","Utiliser Azure Cost Management pour ajouter les tags"],a:1,e:"Azure Policy Deny + tags requis = enforcement automatique. Si un développeur essaie de déployer une VM sans tag Environment → sa demande est refusée immédiatement (Deny mode). Audit mode = la ressource est créée mais signalée comme non-conforme (utile pour inventorier avant d'enforcer). Assignment au Management Group = s'applique à tous les abonnements enfants automatiquement. Initiative = grouper plusieurs policies (une pour chaque tag requis)."},
  {t:"Révision finale",q:"Quelle est la différence entre la haute disponibilité (HA) et la reprise après sinistre (DR) dans Azure ?",o:["Ils sont identiques","HA = maintenir le service disponible malgré des pannes locales/composants (Availability Zones, Scale Sets, Load Balancer — RTO proche de zéro, dans la même région), DR = récupérer après un sinistre majeur affectant une région entière (Azure Site Recovery, géo-réplication, backup — RTO peut être de minutes à heures, vers une autre région)","HA est plus coûteux que DR","DR est uniquement pour les bases de données"],a:1,e:"HA : composants redondants dans une région (AZ1 + AZ2 + AZ3 = si AZ1 tombe, le service continue sur AZ2/AZ3, transparence totale). DR : stratégie pour une région entière qui serait détruite (tremblement de terre, inondation massive) — basculer vers une région paired (North Europe ↔ West Europe). RTO (Recovery Time Objective) = combien de temps sans service acceptable. RPO (Recovery Point Objective) = combien de données perdues acceptables."},
  {t:"Révision finale",q:"Comment fonctionne Azure Advisor et quelles sont ses catégories de recommandations ?",o:["Azure Advisor est uniquement pour les coûts","Azure Advisor analyse continuellement vos ressources Azure et fournit des recommandations personnalisées dans 5 catégories : Cost (rightsizing, Reserved Instances), Security (Secure Score améliorations), Reliability (HA, backup), Operational Excellence (bonnes pratiques), Performance (améliorations de perf)","Azure Advisor nécessite une configuration manuelle","Azure Advisor n'est pas gratuit"],a:1,e:"Azure Advisor : consultant automatique gratuit inclus dans Azure. Scanne vos ressources et compare aux meilleures pratiques Microsoft. Exemples : Cost → 'cette VM est utilisée à 5% de sa capacité, passez à une VM plus petite, économisez $200/mois'; Security → 'MFA pas activé sur 3 comptes admin'; Reliability → 'cette VM n'a pas de sauvegarde configurée'. Recommandations avec impact (High/Medium/Low) et économie potentielle estimée."},
  {t:"Révision finale",q:"Qu'est-ce que le Service Level Agreement (SLA) composite dans Azure ?",o:["Le SLA d'un seul service Azure","Quand une application utilise plusieurs services Azure en séquence, le SLA composite est le PRODUIT des SLAs individuels : App Service (99.95%) × SQL Database (99.99%) × Key Vault (99.99%) = 99.93% — donc plus de services en séquence = SLA composite plus bas","Le SLA composite est toujours 99.99%","Le SLA composite n'existe pas dans Azure"],a:1,e:"SLA composite = 99.95% × 99.99% × 99.99% ≈ 0.9995 × 0.9999 × 0.9999 = 99.93%. Chaque service peut être indépendamment le maillon faible. Pour améliorer le SLA composite : architecture active-active multi-région (App Service dans 2 régions + Traffic Manager → SLA = 1-(1-0.9995)²  ≈ 99.9999%), redondance par composant. Un SLA de 99.9% = ~8.7h de downtime/an; 99.99% = ~52 minutes/an; 99.999% = ~5 minutes/an."},
  {t:"Révision finale",q:"Dans quel scénario Azure Spot VMs sont-elles recommandées et pourquoi ?",o:["Pour toutes les charges de production","Pour les charges de travail tolérantes aux interruptions (calcul distribué, rendu, traitement de données, CI/CD pipelines de test, environnements de dev) car elles utilisent la capacité inutilisée d'Azure avec jusqu'à 90% de réduction — mais peuvent être évincées avec 30 secondes de préavis","Pour les bases de données de production","Pour les applications web à fort trafic"],a:1,e:"Spot VMs : prix variable selon la disponibilité de la capacité Azure. Idéal pour : rendu 3D (job interruptible et repris), ML training (checkpoints réguliers), Kubernetes batch jobs (pods reprogrammés automatiquement sur eviction), tests automatisés (relancés si interrompus). Prix actuel visible dans le portail, vous définissez un prix max. Si la capacité est requise par Azure ou si le prix dépasse votre max → VM évincée. Savings par rapport aux VMs Pay-As-You-Go : jusqu'à 90%."},
  {t:"Révision finale",q:"Comment Azure gère-t-il la conformité réglementaire et comment peut-on auditer la conformité ?",o:["Azure ne supporte pas la conformité réglementaire","Via plusieurs outils : Azure Policy (enforce les configurations conformes), Microsoft Defender for Cloud (Secure Score + tableau de bord conformité RGPD, ISO 27001, PCI DSS), Service Trust Portal (rapports d'audit tiers, certifications Microsoft), Compliance Manager (évaluer et améliorer la posture de conformité), Compliance offerings (80+ certifications mondiales)","Via des audits manuels uniquement","La conformité n'est pas la responsabilité d'Azure"],a:1,e:"Service Trust Portal (trust.microsoft.com) : rapports d'audit SOC 2 Type II, ISO 27001, PCI DSS effectués par des auditeurs tiers indépendants que Microsoft met à disposition. Defender for Cloud tableau de bord réglementaire : mappe vos ressources aux exigences PCI DSS Article 6.3 etc. et montre ce qui est conforme/non-conforme. Compliance Manager : score de conformité de votre organisation (pas juste Azure, inclut vos pratiques)."},
  {t:"Révision finale",q:"Quelle est la différence entre Azure Backup et Azure Site Recovery (ASR) ?",o:["Ils sont identiques","Azure Backup : sauvegarde ponctuelle des données (VMs, bases de données, fichiers) avec rétention selon les politiques — pour se protéger contre la corruption/suppression accidentelle (RPO = dernière sauvegarde); Azure Site Recovery (ASR) : réplication continue vers une région secondaire pour la DR — maintient une copie quasi-temps-réel, bascule en cas de sinistre régional (RPO = quelques minutes/heures selon fréquence réplication)","Azure Backup est plus récent","Azure Site Recovery est uniquement pour les VMs on-premises"],a:1,e:"Backup vs ASR : complémentaires. Backup protège contre : suppression accidentelle de données, corruption, ransomware (restaurer une version antérieure). RPO = heures ou jours (selon fréquence des sauvegardes). ASR protège contre : panne d'une région entière Azure. RPO = secondes à minutes (réplication async ou sync). Pour une architecture DR robuste : Backup + ASR combinés. ASR supporte : VMs Azure → autre région, VMs VMware → Azure, VMs Hyper-V → Azure."},
  {t:"Révision finale",q:"Qu'est-ce que l'Azure Well-Architected Framework Reliability pillar recommande pour les applications critiques ?",o:["D'utiliser une seule grande VM très puissante","De supprimer les tests de charge","Définir des cibles de fiabilité (SLOs), identifier et éliminer les SPOF (Single Points of Failure) via la redondance (Availability Zones, Scale Sets), implémenter des patterns de résilience (retry, circuit breaker, bulkhead), effectuer des tests de chaos (Chaos Engineering — tuer des composants volontairement pour valider la résilience), définir RTO/RPO et avoir un plan DR testé","D'utiliser uniquement les SLAs Microsoft"],a:1,e:"Reliability WAF : SPOF = un seul point qui, s'il tombe, arrête tout. Eliminer les SPOFs : Load Balancer devant plusieurs VMs (pas une seule), Availability Zones (pas une seule zone), réplication des bases de données. Chaos Engineering : Netflix 'Chaos Monkey' tue aléatoirement des VMs pour s'assurer que les systèmes se rétablissent. Azure Chaos Studio : outil Microsoft pour tests de chaos contrôlés. SLO (Service Level Objective) : objectif interne de fiabilité (99.99%) ≠ SLA (engagement contractuel avec les clients)."},
  {t:"Révision finale",q:"Comment fonctionne Azure Cost Management pour contrôler les dépenses cloud ?",o:["Azure Cost Management bloque automatiquement les dépenses","Azure Cost Management fournit : analyse des coûts (dashboards et graphiques par service/ressource/tag), budgets (alertes à 80% et 100% d'un budget mensuel défini), exports (données de facturation vers Blob Storage pour analyse externe), recommandations (via Azure Advisor), et prévisions (projection des coûts futurs selon la tendance actuelle)","Azure Cost Management est payant séparément","Azure Cost Management est uniquement pour les grands comptes"],a:1,e:"Azure Cost Management : gratuit, inclus dans chaque abonnement. Budget + alerte : définir 1000€/mois de budget → alerte email à 800€ (80%) et 1000€ (100%). Alerte ne bloque pas les ressources, juste notifie. Pour bloquer : Azure Policy (DeployIfNotExists avec action de shutdown) ou Azure Automation (runbook déclenché par l'alerte). Export vers Blob : automatiser l'export CSV mensuel pour réconciliation comptable. Tags : taguer par projet/équipe pour répartir les coûts."},
  {t:"Révision finale",q:"Qu'est-ce que le programme Azure Reserved Instances / Savings Plan et comment choisir entre les deux ?",o:["Ce sont des services identiques","Reserved Instances (RI) : engagement 1 ou 3 ans sur un type de VM spécifique dans une région spécifique → jusqu'à 72% d'économies; Savings Plan for Compute : engagement 1 ou 3 ans sur un montant horaire de compute ($X/heure) applicable à n'importe quelle VM, ACI ou Functions → jusqu'à 65% d'économies, plus flexible — RI = prévisibilité totale (charge stable et connue), Savings Plan = flexibilité (workloads changeants ou migrations en cours)","Reserved Instances sont uniquement pour les grandes entreprises","Savings Plan n'existe pas dans Azure"],a:1,e:"RI : 'je vais toujours utiliser une VM D4s_v5 en West Europe pendant 3 ans' → 72% de réduction sur ce type exact. Si vous changez de taille/région, vous pouvez échangez le RI (avec pénalité possible). Savings Plan : 'je vais dépenser au moins $5/heure en compute pendant 1 an' → 65% de réduction sur tout ce qui tombe dans ce montant, peu importe la taille/région/service. Recommandation : Savings Plan pour les workloads modernes changeants, RI pour des workloads legacy stables."},
  {t:"Gouvernance",q:"Qu'est-ce qu'Azure Lighthouse et pour quel cas d'usage est-il conçu ?",o:["Un service d'éclairage intelligent","Un service permettant aux prestataires de services gérés (MSP) de gérer les ressources Azure de plusieurs clients depuis un seul tenant Entra ID — sans avoir besoin d'un compte guest dans chaque tenant client, le MSP délègue des droits RBAC granulaires depuis le tenant client vers le tenant MSP","Un service de monitoring des performances","Un concurrent à Azure Monitor"],a:1,e:"Azure Lighthouse : multi-tenant management pour les MSP. Cas d'usage : une société de conseil IT gère l'Azure de 100 clients. Sans Lighthouse : 100 comptes différents, 100 connexions, 100 portails. Avec Lighthouse : un seul portail MSP, toutes les souscriptions clients visibles et gérables en Cross-tenant management. Les clients gardent le contrôle (peuvent révoquer l'accès). Granularité RBAC : le MSP peut avoir uniquement 'Read' sur certains abonnements et 'Contributor' sur d'autres. Bonne pratique : journalisation complète des actions MSP."},
  {t:"Révision finale",q:"Quelle est l'utilité de l'Azure Pricing Calculator vs Azure TCO Calculator ?",o:["Ce sont des outils identiques","Azure Pricing Calculator : estime le coût mensuel d'une architecture Azure spécifique que vous concevez (sélectionner les services, régions, tiers, quantités) — pour budgéter un nouveau projet; Azure TCO Calculator : compare le coût d'infrastructure on-premises vs Azure sur 5 ans — pour justifier la migration cloud auprès du management","Pricing Calculator est uniquement pour les entreprises","TCO Calculator est pour les développeurs uniquement"],a:1,e:"Pricing Calculator (calculator.azure.com) : additionne les coûts des services que vous allez utiliser. Exemple : 2 VMs D4s_v5 + 1 SQL Database Premium + 1 App Gateway → $X/mois estimé. TCO Calculator (azure.microsoft.com/tco) : entre vos serveurs actuels (nombre, specs, OS, stockage, bande passante, électricité) → compare avec le coût Azure équivalent sur 3 ou 5 ans. Typiquement montre 30-50% d'économies. Utilisé dans les business cases de migration pour convaincre la direction."},
  {t:"Révision finale",q:"Comment Azure Active Directory (maintenant Entra ID) diffère-t-il de Windows Server Active Directory Domain Services (AD DS) ?",o:["Ils sont identiques","Entra ID : service IAM cloud-native (REST APIs/OAuth2/OIDC), conçu pour les applications web/SaaS/mobiles, pas de notion de domaine/forêt/LDAP, géo-distribué et HA automatiquement, Conditional Access, MFA, B2B/B2C; AD DS : service d'annuaire on-premises (Kerberos/LDAP/NTLM), domaines et forêts, Group Policy Objects, Domain Join pour les machines Windows — pour les apps legacy nécessitant AD DS dans le cloud : Azure AD DS (service managé)","Entra ID est uniquement pour Microsoft 365","AD DS est plus moderne qu'Entra ID"],a:1,e:"Entra ID ≠ AD DS dans le cloud. Entra ID = identité moderne (OIDC, OAuth2, SAML). AD DS = identité legacy (Kerberos, LDAP). Migration : synchroniser AD DS vers Entra ID avec Microsoft Entra Connect (synchronisation des users/groupes/mots de passe). Pour les apps qui NÉCESSITENT LDAP/Kerberos (AS/400, vieilles apps Windows) dans Azure : Azure AD DS (service managé qui fournit un vrai domaine AD DS sans gérer des DCs). Entra ID + Conditional Access + MFA = bien plus sécurisé que AD DS classique."},
  {t:"Révision finale",q:"Qu'est-ce que Microsoft Secure Score dans Microsoft Defender for Cloud ?",o:["Un score de performance des VMs","Un score de 0 à 100% mesurant la posture de sécurité de votre environnement Azure en comparant vos configurations aux bonnes pratiques : chaque recommandation non implémentée diminue le score, chaque recommandation corrigée l'augmente — permet de prioriser les améliorations de sécurité par impact","Un score de facturation Azure","Un score de performance réseau"],a:1,e:"Secure Score : votre note de sécurité Azure. 100% = toutes les bonnes pratiques Microsoft implémentées (théoriquement). Recommandations classées par impact (points gagnés si corrigée). Exemple : 'Activer MFA sur les comptes admins' = +15 points, 'Restreindre accès RDP depuis Internet' = +8 points. Dashboard montrant l'évolution dans le temps. Objectif : amélioration continue. Defender for Cloud intègre aussi MCSB (Microsoft Cloud Security Benchmark) et des standards réglementaires (RGPD, ISO 27001)."},
  {t:"Révision finale",q:"Comment choisir entre Azure Service Bus et Azure Event Hubs ?",o:["Ils sont identiques","Azure Service Bus : messaging enterprise (exactement-une-fois, ordering, sessions, dead-letter queue, transactions) pour l'intégration de systèmes et la communication microservices (commandes, processus business); Azure Event Hubs : streaming d'événements à très haute échelle (millions/seconde), rétention jusqu'à 90 jours, lecture à partir d'un point (offset) — pour la télémétrie, les logs, les pipelines Big Data, les événements IoT","Service Bus est toujours préférable","Event Hubs est pour les petites applications"],a:1,e:"Service Bus = file de messages (pas de réponse immédiate, traitement asynchrone). Event Hubs = log distribué immutable (Kafka-compatible). Cas Service Bus : passer une commande → service d'inventaire traite → service de paiement traite → service de livraison traite. Chaque service lit exactement-une-fois. Cas Event Hubs : 10 000 capteurs IoT envoient 1M d'événements/sec → stocker 7 jours → Azure Stream Analytics et Databricks lisent en parallèle le même stream depuis des offsets différents."},
  {t:"Révision finale",q:"Qu'est-ce que Azure App Configuration et quand l'utiliser ?",o:["Un service de configuration des VMs","Un service centralisé pour gérer les paramètres de configuration des applications (feature flags, chaînes de connexion, paramètres applicatifs) séparément du code — avantages : modifier la configuration sans redéployer l'app, feature flags (activer/désactiver des fonctionnalités en production sans redéploiement), configuration centralisée pour les microservices, historique et rollback des configurations","Un service identique à Key Vault","Un service de gestion des Azure Policies"],a:1,e:"App Configuration vs Key Vault : App Configuration = paramètres applicatifs non-secrets (feature toggles, URLs, timeouts). Key Vault = secrets, clés, certificats. Les deux sont souvent utilisés ensemble. Feature flags : 'canary release' → activer une nouvelle feature pour 5% des utilisateurs (via App Configuration + feature management SDK), observer les métriques, puis étendre à 100%. Changement de config sans redéploiement = blue/green switch instantané. Microservices : chaque service se connecte à App Configuration au démarrage."},
  {t:"Révision finale",q:"Quelle est la stratégie recommandée pour sécuriser l'accès à une base de données Azure SQL depuis une application Azure ?",o:["Utiliser un nom d'utilisateur et mot de passe hardcodés dans le code","Utiliser une Managed Identity (identité managée) pour l'application (App Service, Functions, AKS) — l'application s'authentifie auprès d'Azure SQL sans credentials hardcodés, via Entra ID : zero secrets dans le code ou les fichiers de config, rotation automatique des tokens, auditabilité complète — associer la Managed Identity au rôle Azure SQL approprié","Ouvrir le firewall SQL à Internet public","Stocker les credentials dans des variables d'environnement en clair"],a:1,e:"Managed Identity + Azure SQL = credential-free connection. App Service Managed Identity → Microsoft Entra ID (token JWT) → Azure SQL (vérifie le token). Pas de mot de passe SQL. Configuration : activer Entra authentication sur Azure SQL, créer un user SQL correspondant à la Managed Identity, donner db_datareader/db_datawriter. Avantage : pas de secret à gérer/faire tourner/exposer accidentellement. Si la VM/App Service est compromise, l'attaquant ne peut pas extraire de credentials SQL."},
  {t:"Révision finale",q:"Comment fonctionne la géo-réplication d'Azure SQL Database ?",o:["La géo-réplication nécessite une configuration complexe impossible pour les débutants","Active Geo-Replication : réplique de manière asynchrone une Azure SQL Database vers jusqu'à 4 régions secondaires lisibles — les secondaires peuvent servir des requêtes en lecture (offload), en cas de défaillance de la région primaire : basculement manuel ou automatique via Failover Groups (basculement automatique + endpoint unique invariant)","La géo-réplication n'est disponible qu'en niveau Premium","La géo-réplication copie les données une fois par jour"],a:1,e:"Active Geo-Replication : réplication continue async. RPO ≈ quelques secondes (lag de réplication). Geo-Secondary en lecture : décharger les requêtes analytics/rapports sur la secondaire pour réduire la charge sur la primaire. Failover Groups (recommandé) : endpoint invariant (.database.windows.net unique) qui pointe automatiquement vers la primaire courante → basculement transparent pour l'application. Politique de failover automatique configurable (délai avant basculement auto)."},
  {t:"Révision finale",q:"Qu'est-ce que le plan Azure Free Account et quelles sont ses limitations ?",o:["Le compte gratuit donne un accès illimité à tous les services Azure","Azure Free Account : 200$ de crédit gratuit les 30 premiers jours (essayer tous les services), puis : 12 mois de services populaires gratuits à utilisation limitée (B1S Linux VM, 250GB SQL Database, 5GB Blob Storage), et plus de 55 services toujours gratuits sans limite de temps (Azure Functions 1M exécutions/mois, Azure AD B2C 50 000 MAU, Cognitive Services Free tier) — carte bancaire requise pour vérification","Le compte gratuit est uniquement pour les entreprises","Le compte gratuit n'inclut pas les VMs"],a:1,e:"Azure Free Account vs Pay-As-You-Go : Free Account = parfait pour l'apprentissage et les tests. Après 30 jours ou $200 épuisés, automatiquement basculé en Pay-As-You-Go (sauf si vous gérez ça dans les paramètres). Services toujours gratuits : Azure Functions free tier (parfait pour dev), Static Web Apps, Azure DevOps (5 utilisateurs gratuits), Cosmos DB (1000 RU/s + 25GB), etc. Azure for Students : $100/an sans carte bancaire, pour .edu emails."},
  {t:"Révision finale",q:"Comment Azure gère-t-il les mises à jour et la maintenance des services Azure ?",o:["Azure n'effectue jamais de maintenance","Pour les services IaaS (VMs) : Azure annonce les maintenances planifiées à l'avance, propose de les reprogrammer dans une fenêtre de maintenance configurable; les VMs dans des Availability Sets ont des Update Domains (mise à jour progressive) et Fault Domains (séparation physique); pour les services PaaS/SaaS : Microsoft gère les mises à jour de manière transparente, sans interruption pour l'utilisateur","La maintenance Azure arrête toujours les services","Azure nécessite une approbation pour chaque mise à jour"],a:1,e:"Maintenance Azure : distinction IaaS vs PaaS. IaaS : vous partagez la responsabilité — Microsoft met à jour l'hyperviseur, vous patcher vos VMs OS (Azure Update Manager). Pour les maintenances hôte : Live Migration (déplacer la VM vers un autre hôte sans interruption, 99.9% des cas) ou Memory Preserving Updates. Availability Sets Update Domains : si 10 VMs en Availability Set avec 5 Update Domains, seulement 2 VMs redémarrées par vague. PaaS : Microsoft gère tout, zéro maintenance visible pour vous."},
  {t:"Révision finale",q:"Résumé AZ-900 : Quel est le domaine examiné avec la pondération la plus élevée dans l'examen AZ-900 ?",o:["Les fonctionnalités et services Azure (environ 35-40% de l'examen selon Microsoft Learn) incluant les services de compute, réseau, stockage, données, IA et DevOps","La gestion des coûts Azure (environ 5-10%)","La gouvernance et conformité (environ 5-10%)","La sécurité et accès réseau (environ 25-30%)"],a:0,e:"Distribution AZ-900 selon Microsoft : Describe cloud concepts 25-30%, Describe Azure architecture and services 35-40%, Describe Azure management and governance 30-35%. Le domaine 2 (services Azure) est donc le plus important avec 35-40%. Focus : bien connaître les catégories de services (Compute, Networking, Storage, Data, AI, DevOps, Monitoring) et quand utiliser chaque service. Le domaine 3 (management/governance) est important aussi : Cost Management, RBAC, Policy, Blueprints, Compliance."},
  {t:"Révision finale",q:"Dans un scénario d'examen AZ-900, une entreprise veut migrer ses serveurs de fichiers vers Azure pour réduire les coûts. Quel service Azure recommanderiez-vous ?",o:["Azure Blob Storage","Azure Files : partages de fichiers SMB/NFS entièrement managés dans Azure, montables comme lecteurs réseau sur Windows/Linux/macOS, remplaçant direct des serveurs de fichiers on-premises — alternative : Azure File Sync pour synchroniser le serveur de fichiers on-prem avec Azure Files (cache local + stockage cloud)","Azure Data Lake","Azure Queue Storage"],a:1,e:"Azure Files : migration 'lift and shift' des serveurs de fichiers. \\\\storageaccount.file.core.windows.net\\share → montable comme Z: sur Windows. Protocoles : SMB 2.1/3.0, NFS 4.1. Azure File Sync : stratégie hybride (conserver le serveur de fichiers on-prem comme cache pour la performance locale, synchroniser dans le cloud, partager entre plusieurs sites). Tiers : Standard (HDD, moins cher) et Premium (SSD, IOPS élevées, pour les charges de travail intensives)."},
  {t:"Révision finale",q:"Dernière question de révision : Pourquoi est-il important de comprendre le modèle de responsabilité partagée Azure avant de déployer des applications en production ?",o:["Ce n'est pas important, Azure s'occupe de tout","Le modèle de responsabilité partagée définit précisément ce que Microsoft gère vs ce que VOUS devez gérer. Ne pas comprendre ce modèle → failles de sécurité par 'assumption gap' (croire qu'Azure gère quelque chose qu'il ne gère pas). Exemple IaaS : vous DEVEZ patcher l'OS des VMs, configurer le firewall, chiffrer les disques. Exemple PaaS : Azure gère l'OS, vous gérez le code et les données. Exemple SaaS : Azure gère tout, vous gérez les accès utilisateurs","Microsoft est toujours responsable en cas d'incident","La responsabilité partagée ne s'applique qu'aux grandes entreprises"],a:1,e:"Failles par 'assumption gap' = problème réel : 'Je pensais qu'Azure sauvegardait automatiquement ma VM' (faux pour IaaS — vous devez configurer Azure Backup), 'Je pensais qu'Azure chiffrait mes données en transit' (oui pour les endpoints Azure, mais pas pour le trafic VM-à-VM dans un VNet si vous ne configurez pas TLS dans votre app). Résumé : IaaS = vous gérez OS, apps, données, réseau interne; PaaS = vous gérez apps et données; SaaS = vous gérez accès et données seulement. Le cloud déplace mais ne supprime pas votre responsabilité sécurité."}
);

// Correctif — 1 question pour Jour 5
window.QDATA[5].push(
  {t:"Révision scénario",q:"Une entreprise souhaite que ses développeurs puissent déployer des ressources Azure mais ne puissent pas modifier les politiques de sécurité. Quelle approche RBAC est recommandée ?",o:["Donner le rôle Owner à tous les développeurs","Attribuer le rôle Contributor aux développeurs (créer/gérer les ressources mais pas les accès RBAC ni les politiques) et réserver le rôle Owner ou Security Admin aux équipes sécurité/ops — appliquer le principe du moindre privilège","Donner le rôle Reader à tous les développeurs","Créer un rôle custom qui donne tous les droits"],a:1,e:"Principe du moindre privilège : chaque identité n'a que les droits strictement nécessaires. Contributor = peut créer/modifier/supprimer les ressources mais ne peut pas modifier les RBAC assignments. Owner = Contributor + gestion des accès. Security Admin = gérer les policies Defender. Rôles custom : si aucun rôle built-in ne correspond exactement, créer un rôle custom avec les permissions précises (mais à éviter si un built-in suffit)."}
);

// Correctif — 1 question pour Jour 6
window.QDATA[6].push(
  {t:"Architecture avancée",q:"Qu'est-ce que le pattern 'CQRS' (Command Query Responsibility Segregation) et comment Azure le supporte ?",o:["CQRS est uniquement un pattern de base de données","CQRS sépare les opérations de lecture (Query) des opérations d'écriture (Command) avec des modèles de données différents — Azure le supporte via : Cosmos DB (écriture) + Azure Cognitive Search ou Redis Cache (lecture optimisée), Event Sourcing avec Event Hubs, CQRS + Event Sourcing avec Azure Service Bus pour la propagation des changements","CQRS est uniquement pour les microservices K8s","CQRS est contre-indiqué dans Azure"],a:1,e:"CQRS : les lectures et écritures ont des besoins différents (lecture = optimisée pour la performance et les jointures, écriture = optimisée pour la cohérence et les transactions). Exemple Azure : API écrit des commandes dans Cosmos DB → Azure Function écoute les changements (Change Feed) → met à jour un index Redis optimisé pour la lecture. Avantage : scale indépendant (plus de lectures que d'écritures typiquement). Complexité accrue : à utiliser seulement si les performances le justifient."}
);
